  def solve(): Unit = {
    val S = ns()
    val N = S.length
    val next = Array.fill[Int](26, N + 1)(-1)
    REP_r(N) { i =>
      REP(26) { j =>
        next(j)(i) = next(j)(i + 1)
      }
      next(S(i)-'a')(i) = i + 1
    }
    debugDim(next)
    val inf = 1e9.toInt
    val dp = Array.ofDim[Int](N + 1)
    val char = Array.ofDim[Int](N + 1)
    REP_r(N + 1) { i =>
      var ms = inf
      var firstChar = -1
      REP(26) { j =>
        val v = if (next(j)(i) == -1)
          1
        else {
          dp(next(j)(i)) + 1
        }
        if (v < ms) {
          ms = v
          firstChar = j
        }
      }
      dp(i) = ms
      char(i) = firstChar
    }
    debug(dp)
    debug(char)

    var i = 0
    while (i != -1) {
      out.print((char(i)+'a').toChar)
      i = next(char(i))(i)
      debug(s"i:$i")
    }
    out.println()
  }
