int dp[300000];

const int inf = 1e8;

vector<vector<int>> makeCH(string S){
  int N = S.size();
  vector<vector<int>> res(N+1, vector<int>(26,N));
  // res[i][j] == Nは存在しないことを意味
  for(int i = N-1; i >= 0; i--){
    for(int j = 0; j < 26; j++){
      res[i][j] = res[i+1][j];
    }
    res[i][S[i]-'a'] = i;
  }
  return res;
}


