  auto ch = makeCH(A); vector<pair<char,int>> recon(n+1, {'?',n});


  for(int i = n-1; i >= 0; i--){
    for(int j = 0; j < 26; j++){

      if( ch[i][j] == n){ // A[i]以降、a+jが存在しない場合→一文字でいい
        if( dp[i] > 1){
          dp[i] = 1; recon[i] = {(char)(j+'a'), n};
        }
      }
      else{
        if( dp[i] > dp[ch[i][j]+1]+1){
          dp[i] = dp[ch[i][j]+1]+1; recon[i] = {(char)(j+'a'),ch[i][j]+1};
        }
      }
    }
  }

    int index = 0;
    string ans = "";
    while( index < n){
      auto p = recon[index];
      ans += p.first;
      index = p.second;
    }

    cout << ans << endl; return 0;
  }

