const int N = 200010;

char s[N];
int ne[N][26];
int f[N];

int main() {
  scanf("%s", s);
  int n = (int)strlen(s);
  for (int i = 0; i < 26; ++i) {
    ne[n][i] = n;
  }
  for (int i = n - 1; i >= 0; --i) {
    for (int j = 0; j < 26; ++j) {
      ne[i][j] = ne[i + 1][j];
    }
    ne[i][s[i] - 'a'] = i;
  }
  f[n] = 0;
  for (int i = n - 1; i >= 0; --i) {
    int k = 0;
    for (int j = 0; j < 26; ++j) {
      k = max(k, ne[i + 1][j]);
    }
    f[i] = f[k] + 1;
  }
  int len = 1e9;
  for (int i = 0; i < 26; ++i) {
    len = min(len, f[ne[0][i]]);
  }
  string ans = "";
  int j = -1;
  while (j < n) {
    int k = -1;
    for (int i = 26; i >= 0; --i) {
      if (f[ne[j + 1][i]] == len) {
        k = i;
      }
    }
    assert(k != -1);
    ans += (char)('a' + k);
    j = ne[j + 1][k];
    --len;
  }
  printf("%s\n", ans.c_str());
}

