ll minlen(const string& S) {
    ll ret = 1;
    V<ll> cnt(26, 0);
    RREP(i, SIZE(S)) {
        cnt[S[i] - 'a']++;
        bool judge = true;
        REP(i, 26) {
            if (cnt[i] == 0) {
                judge = false;
                break;
            }
        }

        if (judge) {
            ret++;
            fill(ALL(cnt), 0);
        }
    }
    return ret;
}

