int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    string S;
    cin >> S;

    V<V<ll>> place(26);
    REP(i, SIZE(S)) {
        place[S[i] - 'a'].pb(i);
    }

    ll len = minlen(S);

    string ans;
    ll head = 0;
    REP(i, len) {
        REP(j, 26) {
            auto itr = lower_bound(ALL(place[j]), head);
            if (itr == place[j].end()) {
                if (len - i - 1 == 0) {
                    ans.pb(char(j + 'a'));
                    break;
                } else {
                    continue;
                }
            }

            ll p = *itr;
            if (minlen(S.substr(p + 1)) == len - i - 1) {
                ans.pb(char(j + 'a'));
                head = p + 1;
                break;
            }
        }
    }

    cout << ans << endl;
    return 0;
}

