        if(idx == sz(cnt[j])){
            ret = 1;
            break;
        }
        ret = min(ret, 1 + solve(cnt[j][idx] + 1));
    }
    return ret;
}

void track(int i){
    if(i >= sz(s)){
        if(i == sz(s)) cout << "a";
        cout << '\n';
        return ;
    }
    int ad = 1e9, k = -1, nxt = -1;
    for(int j = 0 ; j < 26 ; ++j){
        int idx = upper_bound(all(cnt[j]), i - 1) - cnt[j].begin();
        if(idx == sz(cnt[j])){
            k = j;
            nxt = sz(s) + 1;
            break;
        }
        int sm = 1 + solve(cnt[j][idx] + 1);
        if(sm < ad) ad = sm, k = j, nxt = cnt[j][idx] + 1;
    }
    cout << (char)(k + 'a');
    track(nxt);
}

