                                             val > st.val;
    }
};

const int LEN = 300000;

string cost[LEN];
int next_idx[LEN][26];

bool better(string& s1, string& s2) {
    return s1.size() != s2.size() ? s1.size() < s2.size() : s1 < s2;
}

int main() {
    for (int i = 0; i < LEN; i++) {
        cost[i] = to_string(0);
    }
