    int len = A.size();
    for (int i = 0; i < 26; i++) next_idx[0][i] = 0;

    for (int i = 0; i <= len; i++) {
        for (int j = 0; j < 26; j++) {
            next_idx[i + 1][j] = next_idx[i][j];
        }
        if (i == 0) continue;
        next_idx[i + 1][A[i - 1] - 'a'] = i;
    }

    priority_queue<State, vector<State>, greater<State>> que;

    cost[len + 1] = "";
    que.push({len + 1, cost[len + 1]});
    while (!que.empty()) {
        auto st = que.top(); que.pop();
        int idx = st.idx;
