        for (int i = 0; i < 26; i++) {
            int to = next_idx[idx][i];
            string nval = (char)('a' + i) + val;

            if (cost[to][0] == '0' or better(nval, cost[to])) {
                cost[to] = nval;
                que.push({to, nval});
            }
        }
    }

    return 0;
}

