			iPos = i+1;
			return true;
		}
	}
	return false;
}


bool is_sub(string &s,string &sub)
{
	int i,isubLen = (int)sub.length(),iPos=0;
	char c;
	bool bIsSub = true;
	for (i = 0; i < isubLen; i++) {
		c = sub[i];
		bIsSub = is_CharInS(s, iPos, c);
		if (!bIsSub) { break; }
	}

	return bIsSub;
}
string fNextString(const char *s)
{
	string sRet;
	int i, iCarry=1;
	char c;

	i = (int)strlen(s) - 1;
	for (; i >= 0;i--) {
		if (iCarry == 0) {
			sRet.insert(sRet.begin(), s,&s[i+1]);
			break;
		}
		c = s[i] + iCarry;		
		iCarry = (c > 'z')?1:0;
		c = (c > 'z')?'a': c;
		sRet.insert(sRet.begin(), c);
	};
	if (iCarry!=0) { sRet.insert(sRet.begin(), 'a'); }

	return sRet;
}


