int calc(vector<vector<int>> &v, vector<int> &dp, vector<int> &next, int now = 0){
	if(now == dp.size()) return 1;
	if(dp.size() < now) return 0;
	if(dp[now] != 1 << 30) return dp[now];
	for(int i = 0; i < 26; i++){
		int length = calc(v, dp, next, *lower_bound(v[i].begin(), v[i].end(), now) + 1) + 1;
		if(length < dp[now]){
			dp[now] = length;
			next[now] = i;
		}
	}
	return dp[now];
}

