V<ll> minlen(const string& S) {
    V<ll> ret(SIZE(S));
    ll cnt = 1;
    V<bool> used(26, 0);

    RREP(i, SIZE(S)) {
        used[S[i] - 'a'] = true;
        bool judge = true;
        REP(i, 26) {
            if (!used[i]) {
                judge = false;
                break;
            }
        }

        if (judge) {
            cnt++;
            fill(ALL(used), false);
        }

        ret[i] = cnt;
    }
    return ret;
}

