    REP(i, N) {
        place[S[i] - 'a'].pb(i);
    }

    V<ll> len = minlen(S);

    string ans;
    ll head = 0;

    REP(i, len[0]) {
        REP(j, 26) {
            auto itr = lower_bound(ALL(place[j]), head);
            if (itr == place[j].end()) {
                if (len[0] - i - 1 == 0) {
                    ans.pb(char(j + 'a'));
