const int INF = (int)1e9 + 7;
template<class T> inline bool chmin(T& a, T b) { if (a > b) { a = b; return 1; } return 0; }

vector<vector<int>> calc_next(const string &s) {
    int n = s.size();
    vector<vector<int>> nxt(n + 1, vector<int>(26, n));
    for (int i = n - 1; i >= 0; i--) {
        for (int j = 0; j < 26; j++) nxt[i][j] = nxt[i + 1][j];
        nxt[i][s[i] - 'a'] = i;
    }
    return nxt;
}

int main() {
    string s; cin >> s;
    int n = s.size();
    auto nxt = calc_next(s);
    vector<int> dp(n + 1, INF);
    vector<pair<char, int>> recon(n + 1, {'?', n});
    dp[n] = 1;
    for (int i = n - 1; i >= 0; i--) for (int j = 0; j < 26; j++) {
        if (nxt[i][j] == n) {
            if (dp[i] > 1) dp[i] = 1, recon[i] = {'a' + j, n};
        } else if (chmin(dp[i], dp[nxt[i][j] + 1] + 1)) {
            recon[i] = {'a' + j, nxt[i][j] + 1};
        }
    }
    string res = "";
    int idx = 0;
    while (idx < n) {
        auto p = recon[idx];
        res += p.first;
        idx = p.second;
    }
    cout << res << endl;
}

