void BFS()
{
	bool flag=false;
	queue<jp> q;
	jp ans;
	memset(pre,-1,sizeof(pre));
	q.push(jp(-1,0));
	while(q.size()&&!flag)
	{
		jp state=q.front(); q.pop();
		if(state.ch!=-1) exist[state.ch][state.st]=false;
		for(int i=0;i<26;i++)
		{
			set<int>::iterator it=ch[i].lower_bound(state.st);
			if(it==ch[i].end())
			{
				pre[i][200049][0]=state.ch;
				pre[i][200049][1]=state.st;
				ans=jp(i,200049);
				flag=true;
				break;
			}
			else
			{
				if(!exist[i][*it+1]) exist[i][*it+1]=true;
				if(pre[i][*it+1][1]==-1)
				{
					pre[i][*it+1][0]=state.ch;
					pre[i][*it+1][1]=state.st;
				}
				q.push(jp(i,*it+1));
			}
		}
	}
	s[0]=0;
	for(jp state=ans ;state.ch!=-1 ;state=jp(pre[state.ch][state.st][0],pre[state.ch][state.st][1]))
		s[++s[0]]=state.ch;
	while(s[0])
		putchar('a'+s[s[0]--]);
	return;
}
