template <class T> using reversed_priority_queue = priority_queue<T, vector<T>, greater<T> >;
typedef long long ll;

char left_m;

int get_len (string S) 
{
    if (S.size() == 0) return 0;
    bool used[26] = {};
    int cnt = 0;
    int ret = 1;
    for (int i = (int)S.size() - 1; i >= 0; i--) {
        if (!used[S[i] - 'a']) {
            used[S[i] - 'a'] = true;
            cnt++;
        }
        if (cnt == 26) {
            fill (used, used + 26, false);
            cnt = 0;
            ret++;
        }
        if (i == 0) {
            for (int i = 0; i < 26; i++) {
                if (!used[i]) {
                    left_m = 'a' + i;
                    break;
                }
            }
        }
    }
    return ret;
}

int main ()
{
    string A; cin >> A;

    vector < int > p[26];
    REP(i,A.size()) {
        p[A[i] - 'a'].push_back(i);
    }

    int K = get_len(A);
    string ans;
    ans.push_back(left_m);
    int acc = 0;
    REP(i,A.size()) {
        if (A[i] == left_m) {
            acc = i + 1;
            break;
        }
    }

    for (int i = 0; i < K - 1; i++) {
        for (int j = 0; j < 26; j++) {
            char c = 'a' + j;
            int l = -1, r = (int)p[j].size() - 1;
            while (r - l > 1) {
                int mid = (l + r) / 2;
                if (p[j][mid] >= acc) r = mid;
                else l = mid;
            }
            if (p[j].size() == 0) {
                int Kt = 1;
                if (K - i == Kt) {
                    ans.push_back(c);
                    acc = A.size();
                    break;
                }
            }
            else {
                int idx = p[j][r];
                cerr << c << " " << idx << endl;
                string At = A.substr(idx, A.size() - idx);
                int Kt = get_len(At);
                if (K - i == Kt) {
                    ans.push_back(c);
                    acc = p[j][r] + 1;
                    break;
                }
            }
        }
    }

    cout << ans << endl;

    return 0;
}

