const int N = 200007, K = 18;
int n, up[K][N], fen[N], last[26][N];
string s;

void upd(int x, int y) {
    for (; x <= n; x |= (x + 1)) {
        fen[x] += y;
    }
}

int get(int x) {
    int res = 0;
    for (; x >= 0; x = (x & (x + 1)) - 1) {
        res += fen[x];
    }
    return res;
}

int path(int x) {
    if (x == 0) {
        return -1;
    }
    if (x > n) {
        return -1;
    }
    int res = 0;
    for (int i = K - 1; i >= 0; i--) {
        if (up[i][x] <= n) {
            x = up[i][x];
            res += (1 << i);
        }
    }
    return res;
}

int main() {
    ios_base::sync_with_stdio(false), cin.tie(NULL);
    #ifdef LOCAL
        freopen("input.txt", "r", stdin);
    #endif

    cin >> s;
    n = s.size();
    memset(& last, -1, sizeof(last));
    up[0][n + 1] = n + 1;
    for (int i = n; i >= 1; i--) {
        for (int j = 0; j < 26; j++) {
            last[j][i] = last[j][i + 1];
        }
        int ch = (s[i - 1] - 'a');
        if (last[ch][i] == -1) {
            upd(i, 1);
        }   else {
            upd(last[ch][i], -1);
            upd(i, 1);
        }
        last[ch][i] = i;
        if (get(n) < 26) {
            up[0][i] = n + 1;
        }   else {
            int l = 0, r = n + 1;
            while (l < r - 1) {
                int mid = l + r >> 1;
                if (get(n) - get(mid - 1) > 0) {
                    l = mid;
                }   else {
                    r = mid;
                }
            }
            up[0][i] = l;
        }
    }
    for (int i = 1; i < K; i++) {
        for (int j = 1; j <= n + 1; j++) {
            up[i][j] = up[i - 1][up[i - 1][j]];
        }
    }
    int len = path(1) + 1, cur = 1;
    string ans = "";
    for (int i = 1; i <= len; i++) {
        for (int j = 0; j < 26; j++) {
            if (len - i > path(last[j][cur] + 1)) {
                cur = last[j][cur] + 1;
                ans += char('a' + j);
                break;
            }
        }
    }
    cout << ans;
}

