string solve() {
    rep(i, 0, 26) fast[i] = -1;
    rrep(i, N - 1, 0) {
        int ng = 0;
        rep(j, 0, 26) to[i][j] = fast[j];
        rep(j, 0, 26) if (fast[j] < 0) ng = 1;
        if (ng) dp[i] = 1;
        else {
            dp[i] = 10101010;
            rep(j, 0, 26) dp[i] = min(dp[i], dp[fast[j]] + 1);
        }

        fast[A[i] - 'a'] = i;
    }

   // rep(i, 0, N) printf("%d ", dp[i]);
   // printf("\n");

    string ans = "";

    rep(i, 0, 26) if (fast[i] < 0) {
        ans += char('a' + i);
        return ans;
    }

    int mi = 10101010;
    rep(i, 0, 26) mi = min(mi, dp[fast[i]]);

    int good = -1;
    rep(i, 0, 26) if (dp[fast[i]] == mi) {
        good = i;
        break;
    }

    int idx = fast[good];
    //printf("[%d]\n", mi);

    while (1 < mi) {
        ans += A[idx];
        int cu = idx;
        idx = -1;
        rep(i, 0, 26) if (dp[to[cu][i]] == mi - 1) {
            idx = to[cu][i];
            break;
        }
        assert(0 <= idx);
        mi--;
    }
    ans += A[idx];
    rep(i, 0, 26) if (to[idx][i] < 0) {
        ans += char('a' + i);
        break;
    }

    return ans;
}
