int lkt[200010][26];
bool safe[200010];

void solve() {
    queue<pair<int, string>> q;
    q.push(make_pair(0, string("")));

    while(!q.empty()) {
        pair<int, string> current = q.front();
        q.pop();

        if(safe[current.first]) continue;

        int *current_lkt = lkt[current.first];
        for(int i = 0; i < 26; i++) {
            string s = current.second;
            s += ((char) i + 'a');
            if(current_lkt[i] == -1) {
                throw s;
            }
            if(!safe[current_lkt[i]]) q.push(
                make_pair(
                    current_lkt[i],
                    s
                )
            );
        }

        safe[current.first] = true;
    }
}

