    }

    n = seq.size() - 1;

    int current_lkt[26];
    for(int i = 0; i < 26; i++) {
        current_lkt[i] = -1;
    }

    for(int i = n; i >= 0; i--) {
        memcpy(lkt[i], current_lkt, 26 * sizeof(int));
        current_lkt[seq[i]] = i;
    }

    try {
        solve();
    } catch(string s) {
        cout << s << endl;
    }

    return 0;
}

