struct subsequence{
    struct node;
    using np=node*;
    struct node{
        np ch[26]={};
        int idx;
        node(int idx):idx(idx){}
    };
    string s;int n;
    vector<vector<int>>m;
    vector<np>v;
    np root=0;
    subsequence(string s):s(s),n(s.size()),m(n+1,vector<int>(26,-1)),v(n+1){
        for(int i=n-1;i>=0;--i){
            m[i]=m[i+1];
            m[i][s[i]-'a']=i;
        }
        for(int i=0;i<n+1;++i)v[i]=new node(i);
        for(int i=0;i<n;++i){
            for(int j=0;j<26;++j){
                if(~m[i][j])v[i]->ch[j]=v[m[i][j]+1];
            }
        }
        root=v[0];
    }
    //ここから問題ごとに書く
    vector<lint>dp;
    void dp2(){
        dp.resize(n+1);
        for(int i=n;i>=0;--i){
            np t=v[i];
            dp[i]=INF;
            for(int j=0;j<26;++j){
                if(!t->ch[j])dp[i]=1;
                else chmin(dp[i],dp[t->ch[j]->idx]+1);
            }
        }
    }
    string ans;
    void dfs(np t){
        for(int i=0;i<26;i++){
            if(!t->ch[i]){
                ans+=char(i+'a');
                if(t->idx)ans+=s[t->idx-1];
                return;
            }
            if(dp[t->ch[i]->idx]==dp[t->idx]-1){
                dfs(t->ch[i]);
                if(t->idx)ans+=s[t->idx-1];
                return;
            }
        }
    }
    string solve(){
        dp2();
        dfs(root);
        return ans;
    }
};

