string A;
vector<vector<int>> nextCharPos;
list<int> changePoint;

void calcNextCharPos(string& s)
{
	int len = s.length();
	nextCharPos.resize(len + 1);
	FOR(i, len + 1) {
		nextCharPos[i].resize(26);
	}

	FOR(i, 26) {
		nextCharPos[len][i] = len;
	}

	for (int i = len - 1; i >= 0; i--) {
		FOR(j, 26) {
			nextCharPos[i][j] = nextCharPos[i + 1][j];
		}
		nextCharPos[i][s[i] - 'a'] = i;
	}
}

int main()
{
	cin.tie(nullptr);
	ios::sync_with_stdio(false);

	cin >> A;
	calcNextCharPos(A);
	int len = A.length();
	changePoint.push_back(len);

	bool flags[26] = { false };
	int counter = 0;
	for (int i = len - 1; i >= 0; i--) {
		if (!flags[A[i] - 'a']) {
			flags[A[i] - 'a'] = true;
			counter++;
			if (counter == 26) {
				FOR(j, 26) {
					flags[j] = false;
				}
				counter = 0;
				changePoint.push_front(i);
			}
		}
	}

	string ans = "";
	int index = 0;
	for (list<int>::iterator it = changePoint.begin(); it != changePoint.end(); it++) {
		FOR(i, 26) {
			if (*it <= nextCharPos[index][i]) {
				ans += (char)(i + 'a');
				index = nextCharPos[index][i] + 1;
				break;
			}
		}
	}

	cout << ans << ENDL;

	return 0;
}

