                cout << char('a' + j) << char('a' + k) << '\n';
                return 0;
            }
        }
    }
    vector<int> pos;
    for (int i = 0; i < n; i++) {
        good[i][0] = true;
        for (int j = 0; j < 26; j++) {
            if (next[i][j] == -1) {
                good[i][0] = false;
                break;
            }
        }
        pos.push_back(i);
    }
    for (int len = 1; len < 10000; len++) {
        vector<int> pos1;
        for (int it = sz(pos) - 1; it >= 0; it--) {
            int i = pos[it];
            good[i][len] = true;
            for (int j = 0; j < 26; j++) {
                if (!good[next[i][j]][len - 1]) {
                    good[i][len] = false;
                    break;
                }
            }
            if (good[i][len]) {
                pos1.push_back(i);
            }
        }
        pos = pos1;
        for (int ii = 0; ii < 26; ii++) {
            if (!good[last[ii]][len]) {
                int cur = last[ii];
                string ans;
                ans += char(ii + 'a');
                for (int i = 0; i <= len; i++) {
                    bool wasm = 0;
                    int where;
                    for (int j = 0; j < 26; j++) {
                        if (next[cur][j] == -1) {
                            wasm = true;
                            where = j;
                            break;
                        }
                        if (!good[next[cur][j]][len - i - 1]) {
                            ans += char(j + 'a');
                            cur = next[cur][j];
                            break;
                        }
                    }
                    if (wasm) {
                        ans += char(where + 'a');
                        for (int j = i + 1; j <= len; j++) {
                            ans += 'a';
                        }
                        break;
                    }
                }
                cout << ans << '\n';
                return 0;       
            }
        }
    }
    return 0;
}

