vector<vector<int>> calc_next(const string &s) {
    int n = s.size();
    vector<vector<int>> nxt(n + 1, vector<int>(26, n));
    for (int i = n - 1; i >= 0; i--) {
        for (int j = 0; j < 26; j++) nxt[i][j] = nxt[i + 1][j];
        nxt[i][s[i] - 'a'] = i;
    }
    return nxt;
}

int main() {
    string s; cin >> s;
    int n = s.size();
    auto nxt = calc_next(s);
    // dp[i] := i 文字目以降について「部分文字列とならない」最短の文字列長
    vector<int> dp(n + 2, INF);
    vector<pair<char, int>> recon(n + 1, {'?', n});
    dp[n + 1] = 0;
    for (int i = n - 1; i >= 0; i--) for (int j = 0; j < 26; j++) {
        if (chmin(dp[i], dp[nxt[i][j] + 1] + 1)) {
            recon[i] = {'a' + j, nxt[i][j] + 1};
        }
    }
    // 復元
    string res = "";
    int idx = 0;
    while (idx < n) {
        auto p = recon[idx];
        res += p.first;
        idx = p.second;
    }
    cout << res << endl;
}

