    for (int i = n - 1; i >= 0; i--) {
        for (int j = 0; j < 26; j++) {
            if (next[i][j] == n + 1) {
                if (dp[i] > 1) {
                    dp[i] = 1;
                    recon[i] = 'a' + j;
                }
            } else if (chmin(dp[i], dp[next[i][j] + 1] + 1)) {
                recon[i] = 'a' + j;
            }
        }
    }


    string res = "";
    int index = 0;
    while (index <= n) {
        res += recon[index];
        index = next[index][recon[index] - 'a'] + 1;
    }
    return res;
}

