const int N = 200007, K = 19, alph = 26;
int n, up[K][N], fen[N], last[26][N];
string s;

void upd(int x, int y) {
    for (; x <= n; x |= (x + 1)) {
        fen[x] += y;
    }
}

int get(int x) {
    int res = 0;
    for (; x >= 0; x = (x & (x + 1)) - 1) {
        res += fen[x];
    }
    return res;
}

int path(int x) {
    if (x > n) {
        return 0;
    }
    int res = 0;
    for (int i = K - 1; i >= 0; i--) {
        if (up[i][x] <= n) {
            x = up[i][x] + 1;
            res += (1 << i);
        }
    }
    return res;
}

int main() {
    ios_base::sync_with_stdio(false), cin.tie(NULL);
    #ifdef LOCAL
        freopen("input.txt", "r", stdin);
    #endif

    cin >> s;
    n = s.size();
    memset(& last, -1, sizeof(last));
    for (int i = 0; i < K; i++) {
        up[i][n + 1] = n + 1;
    }
    for (int i = n; i >= 1; i--) {
        for (int j = 0; j < alph; j++) {
            last[j][i] = last[j][i + 1];
        }
        int ch = (s[i - 1] - 'a');
        if (last[ch][i] == -1) {
            upd(i, 1);
        }   else {
            upd(last[ch][i], -1);
            upd(i, 1);
        }
        last[ch][i] = i;
        if (get(n) < alph) {
            up[0][i] = n + 1;
        }   else {
            int l = i, r = n + 1;
            while (l < r - 1) {
                int mid = l + r >> 1;
                if (get(n) - get(mid - 1) > 0) {
                    l = mid;
                }   else {
                    r = mid;
                }
            }
            up[0][i] = l;
        }
    }
    for (int i = 1; i < K; i++) {
        for (int j = 1; j <= n; j++) {
            up[i][j] = up[i - 1][min(n + 1, up[i - 1][j] + 1)];
        }
    }
    int len = path(1) + 1, cur = 1;
    string ans = "";
    for (int i = 1; i <= len; i++) {
        for (int j = 0; j < alph; j++) {
            if (last[j][cur] == -1) {
                if (len == i) {
                    ans += char('a' + j);
                    break;
                }
                assert(false);
            }
            if (len - i > path(last[j][cur] + 1)) {
                cur = last[j][cur] + 1;
                ans += char('a' + j);
                break;
            }
        }
    }
    cout << ans;
}

