	return ret;
}

ll subtract(ll a, ll b, ll m = mod) {
	ll ret = a-b;
	if(ret < 0) ret += m;
	return ret;
}

ll mult(ll a, ll b, ll m = mod) {
	ll ret = a*b;
	if(ret >= m) ret %= m;
	return ret;
}

ll bigmod(ll a, ll b, ll m = mod) {
	ll ret = 1;
	while(b) {
		if(b&1) ret = mult(ret, a, m);
		b >>= 1; a = mult(a, a, m);
	}
	return ret;
}

