struct yes_no : numpunct<char> {
  string_type do_truename()  const { return "YES"; }
  string_type do_falsename() const { return "NO"; }
};

void solve(string A) {
  const int n = A.size();
  vector<vector<int>> next(n + 1, vector<int>(26));
  vector<int> max_len(n + 2);
  REP(i,26) next[n][i] = n;
  for (int i = n - 1; i >= 0; --i) {
    REP(j,26) {
      if (A[i] == j + 'a') next[i][j] = i;
      else next[i][j] = next[i+1][j];
    }
  }
  max_len[n+1] = 0;
  max_len[n] = 1;
  for (int i = n - 1; i >= 0; --i) {
    int mi = 1e9;
    REP(j,26) {
      mi = min(mi, max_len[next[i][j] + 1] + 1);
    }
    max_len[i] = mi;
  }
  // for (int i: max_len) cout << i << " ";
  // cout << endl;
  string res;
  int pos = 0;
  for (int len = max_len[0] - 1; len >= 0; --len) {
    REP(i,26) {
      if (max_len[next[pos][i] + 1] == len) {
        res += char('a' + i);
        // cout << res << endl;
        pos = next[pos][i] + 1;
        break;
      }
    }
  }
  cout << res << endl;
  // cout << max_len[0] << endl;
}

