#define SZ(a) int((a).size())
#define REP(i,n) for(int i=0,_n=(n);i<_n;++i)
#define FOR(i,a,b) for(int i=(a),_b=(b);i<=_b;++i)

typedef long long llong;
typedef vector<int> VI;
typedef vector<VI> VVI;
typedef pair<int,int> II;

int N;
string S;
VI nxt[26];

const int INF = 1000000;
#define MAXN 200004
int memo[MAXN];
II path[MAXN];
int go(int n) {
   if (n > N) return 0;
   int& res = memo[n];
   if (res < 0) {
      res = INF;
      REP(k, 26) {
         int j = upper_bound(nxt[k].begin(), nxt[k].end(), n) - nxt[k].begin();
         //if (n == 0)
         //   cerr << k << " " <<  j << " " << endl;
         int cur = go( nxt[k][j] ) + 1;
         if (res > cur) {
            res = cur;
            path[n] = II(k, nxt[k][j]);
         }
      }
   }
   return res;
}

string solve() {
   N = SZ(S);
   REP(i, N)
      nxt[ S[i]-'a' ].push_back(i+1);
   REP(k, 26)
      nxt[k].push_back(N+1);

   memset(memo, -1, sizeof(memo));
   int len = go(0);
//   cerr << len << endl;

   string res;
   for (int l = 0, n = 0; l < len; ++l) {
      int k, nn;
      tie(k, nn) = path[n];
      res += 'a' + k;
      n = nn;
   }

   return res;
}

int main(int argc, char* argv[]) {
   ios_base::sync_with_stdio(false); 
   cin.tie(NULL);

   cin >> S;

   string res = solve();
   cout << res << endl;

   return 0;
}

