void solve()
{
	int i, j;
	int xt[26];
	for(i=0; i<26; i++)
		xt[i] = -1;
	AL = strlen(A);
	for(i=AL-1; i>=0; i--){
		for(j=0; j<26; j++){
			nxt[i][j] = xt[j];
			xt[A[i]-'a'] = i;
		}
	}

	int cnt[26];
	for(i=0; i<26; i++)
		cnt[i] = 0;
	posL = 0;
	for(i=AL-1; i>=0; i--){
		cnt[A[i]-'a'] ++;
		for(j=0; j<26; j++){
			if(cnt[j] == 0)
				break;
		}
		if(j == 26){
			pos[posL] = i;
			posL ++;
			for(j=0; j<26; j++)
				cnt[j] = 0;
		}
	}

	resL = posL+1;
	for(i=0; i<26; i++)
		cnt[i] = 0;
	for(i=pos[posL-1]-1; i>=0; i--){
		cnt[A[i]-'a'] ++;
	}
	for(i=0; i<26; i++){
		if(cnt[i] == 0){
			res[0] = 'a' + i;
			break;
		}
	}
	int p1, p2;
	if(resL > 1){
		if(A[0]==res[0])
			p1 = 0;
		else
			p1=nxt[0][res[0]-'a'];
		for(i=1; i<resL-1; i++){
			for(j=0; j<26; j++){
				p2 = nxt[p1][j];
				if(p2 >= pos[posL-1-i])
					break;
			}
			res[i] = 'a' + j;
			p1 = p2;
		}
	}
	else{
		p1 = -1;
	}
	for(i=0; i<26; i++){
		cnt[i] = 0;
	}
	for(i=p1+1; i<AL; i++){
		cnt[A[i]-'a'] ++;
	}
	for(i=0; i<26; i++){
		if(cnt[i] == 0)
			break;	
	}
	res[resL-1] = 'a' + i;
	res[resL] = 0;
	printf("%s\n", res);
}

