string to_lower_string(int x, int d){
  string s = "";
  for(int i = 0; i < d; i++){
    s += 'a' + x % 26;
    x /= 26;
  }

  reverse(s.begin(), s.end());
  return s;
}

int to_integer(string& s, int pos, int len){
  int ret = 0;
  for(int i = pos; i < pos + len; i++){
    ret *= 26;
    ret += s[i] - 'a';
  }

  return ret;
}

