std::string get_min(std::string const& target, std::vector<char>& memo, std::size_t start)
{
	bool checker[26] = {};
	for (std::size_t i = start; i > 0; --i)
	{
		auto x = std::find(std::begin(checker), std::end(checker), false);
		if (x == std::end(checker))
		{
			auto ret = get_min(target, memo, i);
			for (auto j = i - 1; j < target.size(); ++j)
			{
				if (target[j] == ret.back())
				{
					ret.push_back(memo[j]);
					return std::move(ret);
				}
			}
		}
		else
		{
			memo[i - 1] = char(x - checker + 'a');
			checker[target[i - 1] - 'a'] = true;
		}
	}
	auto y = std::find(std::begin(checker), std::end(checker), false);
	if (y == std::end(checker))
	{
		for (std::size_t j = 0; j < target.size(); ++j)
		{
			if (target[j] == 'a')
			{
				return std::string({ 'a',memo[j] });
			}
		}
	}
	return std::string({ char(y - checker + 'a') });
}
