            x.pop_back();
            succ(x);
            x.push_back('a');
        } else {
            x.back()++;
        }
        return x;
    }

    bool includes(const string& s, const string& t) {
        int i = 0, j = 0;
        while (i < s.size() && j < t.size()) {
            if (s[i] == t[j]) j++;
            i++;
        }
        return j == t.size();
    }

    void solve() {
        string t = "a";
        while (true) {
            if (includes(s, t)) succ(t);
            else break;
        }
        cout << t << endl;
    }
}

