struct subsequence{
    struct node;
    using np=node*;
    struct node{
        np ch[26]={};
        int idx;
        node(int idx):idx(idx){}
    };
    string s;int n;
    vector<map<char,int>>m;
    vector<np>v;
    np root=0;
    subsequence(string s):s(s),n(s.size()),m(n+1),v(n+1){
        for(int i=n-1;i>=0;--i){
            m[i]=m[i+1];
            m[i][s[i]]=i;
        }
        for(int i=0;i<n+1;++i)v[i]=new node(i);
        for(int i=0;i<n;++i){
            for(int j=0;j<26;++j){
                if(m[i].count(j+'a'))v[i]->ch[j]=v[m[i][j+'a']+1];
            }
        }
        root=v[0];
    }
    //ここから問題ごとに書く
    map<np,lint>dp;
    void solve(np t){
        for(int i=n;i>=0;--i){
            np t=v[i];
            dp[t]=INF;
            for(int j=0;j<26;++j){
                if(!t->ch[j])dp[t]=1;
                else chmin(dp[t],dp[t->ch[j]]+1);
            }
        }
    }
    string ans;
    void dfs(np t){
        if(!t)return;
        for(int i=0;i<26;i++){
            if(dp[t->ch[i]]==dp[t]-1){
                if(dp[t]==1)ans+=char(i+'a');
                else dfs(t->ch[i]);
                if(t->idx)ans+=s[t->idx-1];
                return;
            }
        }
    }
    string solve(){
        solve(root);
        dfs(root);
        return ans;
    }
};

int main(){
    string s;
    cin>>s;
    cout<<subsequence(s).solve()<<endl;
}

