int fun(int ind)
{
	if (ind >= n) return 1;
	if (DP[ind] != -1) return DP[ind];


	int res = MOD;
	rep(i,0,26)
	{

		int temp = 1 + fun(jump[ind][i]);
		if (temp < res)
		{
			res = temp;
			nxt[ind] = i;
		}
	}
	return DP[ind] = res;
}
void solve()
{
	cin >> s;
	rep(i,0,200005)rep(j,0,26) jump[i][j] = MOD;
	memset(DP, -1, sizeof DP);
	memset(nxt, -1, sizeof nxt);
	fill(first, first + 26, MOD);

	n = s.length();



	repD(i,n-1,-1)
	{
		rep(j,0,26)
			jump[i][j] = first[j];
		first[s[i] - 'a'] = i;
	}

	rep(i,0,n)rep(j,0,26)assert(jump[i][j] > i);
	int ans = n+1, who = -1;


	rep(i,0,26)
	{
		int len = fun(first[i]);
		if (len < ans)
		{
			ans = len;
			who = i;
		}
	}
	int cur = first[who];
	string res;
	res.pb('a' + who);
	while (1)
	{
		if (cur >= n || nxt[cur] == MOD) break;
		res.pb('a' + nxt[cur]);
		cur = jump[cur][nxt[cur]];
	}
	cout << res << "\n";

}
