ll worst[27];
ll par[27][200005];

void solve(int tc) {
  cin >> s;
  n = s.length();

  ll c[26] = {0};
  f0r(i, n) ++c[s[i] - 'a'];
  f0r(i, 26) if (c[i] == 0) {
    cout << (char)(i + 'a') << '\n';
    return;
  }

  reverse(all(s));
  ms(worst, 0);

  f0r(i, n) {
    ll c = s[i] - 'a';
    ll mval = mod, mpos = -1;
    f0r(j, 26) {
      if (worst[j] < mval) {
        mval = worst[j];
        mpos = j;
      }
    }

    ++mval;
    worst[c] = mval;
    par[c][mval] = mpos;
  }

  ll foc = 0;
  f1r(i, 1, 26) {
    if (worst[i] < worst[foc]) foc = i;
  }

  string ans = "";
  ll v = worst[foc];
  while (v > 0) {
    ans += (char)('a' + foc);
    foc = par[foc][v];
    --v;
  }
  ms(c, 0);
  ll targ = 0;
  f0r(i, n) if (s[i] - 'a' == foc) {
    targ = i;
    break;
  }

  f0r(i, targ) ++c[s[i] - 'a'];
  f0r(i, 26) {
    if (c[i] == 0) {
      ans += (char)('a' + i);
      break;
    }
  }

  cout << ans << '\n';
}

