const int MAXN = 200000 + 10;

int N;
char S[MAXN];
vector <int> V[26];
int Next[MAXN][26];
int first[MAXN], last[MAXN], nd;
int dp[MAXN][26], pre[MAXN][26];

void Work()
{
	scanf("%s", S);
	N = strlen(S);

	for (int i = 0; i < N; i ++)
		V[S[i] - 'a'].push_back(i);

	for (int i = 0; i < N; i ++)
		for (int c = 0; c < 26; c ++)
		{
			auto it = lower_bound(V[c].begin(), V[c].end(), i);
			Next[i][c] = (it == V[c].end()) ? -1 : (*it);
		}

	nd = 0;
	int here = 0;
	while (1)
	{
		if (here >= N)
		{
			for (int c = 0; c < 26; c ++)
				dp[nd][c] = 1;
			nd ++;
			break;
		}

		int fn = 0;
		for (int c = 0; c < 26; c ++)
			if (Next[here][c] == -1)
				fn = 1;
		if (fn)
		{
			for (int c = 0; c < 26; c ++)
				if (Next[here][c] == -1)
					dp[nd][c] = 1;
			nd ++;
			break;
		}

		int nxt = 0;
		for (int c = 0; c < 26; c ++)
			nxt = max(nxt, Next[here][c]);
		first[nd] = here;
		last[nd] = nxt;
		nd ++;

		here = nxt + 1;
	}

	for (int i = nd - 2; i >= 0; i --)
	{
		for (int c = 0; c < 26; c ++)
		{
			for (int cc = 0; cc < 26; cc ++)
				if (dp[i + 1][cc] && (Next[Next[first[i]][c] + 1][cc] == -1 || Next[Next[first[i]][c] + 1][cc] > last[i]))
				{
					dp[i][c] = 1;
					pre[i][c] = cc;
					break;
				}
		}
	}

	int ptr;
	for (int c = 0; c < 26; c ++)
		if (dp[0][c])
		{
			ptr = c;
			break;
		}

	for (int i = 0; i < nd; i ++)
	{
		printf("%c", 'a' + ptr);
		ptr = pre[i][ptr];
	}
	printf("\n");
}

