int conv(char c) {
    return c - 'a';
}

string solve(const string & s) {
    int n = s.length();
    vector<vector<int>> links(26);
    for (int i = 0; i < 26; i++) {
        links[i].resize(n + 1);
        int prev = n;
        for (int j = n - 1; j >= -1; j--) {
            links[i][j + 1] = prev;
            if (j >= 0 && conv(s[j]) == i)
                prev = j;
        }
    }
    string result = "";
    for (int c = 0; c < 26; c++) {
        if (links[c][0] == n) {
            result += (char)(c + 'a');
            return result;
        }
    }
    vector<int> cur_layer(n), prev_layer(n);
    fill(prev_layer.begin(), prev_layer.end(), true);
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < n; j++) {
            cur_layer[j] = true;
            for (int c = 0; c < 26; c++) {
                if (links[c][j + 1] == n)
                    cur_layer[j] = false;
                if (!prev_layer[links[c][j + 1]])
                    cur_layer[j] = false;
            }
        }
        for (int c = 0; c < 26; c++) {
            if (!cur_layer[links[c][0]]) {
                result += (char)(c + 'a') + solve(s.substr(links[c][0] + 1));
                return result;
            }
        }
        swap(cur_layer, prev_layer);
    }
    throw;
}

