				x = j;
			}
		}
		nex[i][s[i]-'a'] = x;
		dp[i][s[i]-'a'] = sma+1;
	}

	int sma = 200010;
	int x = -1;
	for(int i = 0 ; i < 26 ; i ++){
		if(sma > dp[0][i]){
			sma = dp[0][i];
			x = i;
		}
	}
