V< V<int> > calc(string &s) {
    int n = s.size();
    V< V<int> > ret(n + 1, V<int>(26, n));
    for (int i = n - 1; i >= 0; i--) {
        for (int j = 0; j < 26; j++) ret[i][j] = ret[i + 1][j];
