#define MAX_N 200010

string A;

int alph_next[26][MAX_N];   // アルファベット i 位置 j から見た次のアルファベットの位置
int K[MAX_N];               // 文字列の各位置から見たそれ以降の部分文字列 S における
                            // S の部分文字列でない最短文字列の文字数
vector<int> alph_pos[26];   // 各アルファベットの出現位置

void Debug() {
    printf("K: ");
    REP(i, A.length()) {
        printf("%d ", K[i]);
    }
    printf("\n");

    REP(i, 3) {
        printf("alph_next %c: ", i + 'a');
        REP(j, A.length()) {
            printf("%d ", alph_next[i][j]);
        }
        printf("\n");
    }
}

int main()
{
    cin >> A;
    ZERO(alph_next);

    int ans_length = 1;
    // K の作成
    char alph[26];
    int alph_count = 0;
    ZERO(K);
    ZERO(alph);
    for(int i = A.length()-1; i >= 0; --i) {
        if(alph_count >= 26) {
            // 全部のアルファベットが出現する最小文字列 S が見つかった
            if(i + 1 < A.length()) { K[i] = K[i+1] + 1; }
            else { K[i] = 1; }  // ここには来ないはず
            alph_count = 0;
            ZERO(alph);
        } else {
            if(i + 1 < A.length()) { K[i] = K[i + 1]; }
            else { K[i] = 1; }
        }
        if(alph[A[i] - 'a'] == 0) {
            // まだ出ていない文字
            alph[A[i] - 'a'] = 1;
            alph_count++;
        }
        if(alph_count >= 26) { ans_length++; }

        // alph_pos の作成
        alph_pos[A[i] - 'a'].push_back(i);
    }

    // alph_next の作成
    REP(i, 26) {
        SORT(alph_pos[i]);
        int pos_ind = 0;
        REP(j, A.length()) {
            if(pos_ind < alph_pos[i].size()) {
                alph_next[i][j] = alph_pos[i][pos_ind];
            } else {
                alph_next[i][j] = -1;   // もうアルファベットはない
            }
            if(A[j] == i + 'a') { pos_ind++; }
        }
    }

    //Debug();

    string ans = "";
    int cur = 0;
    while(ans.length() < ans_length) {
        bool isFind = false;
        REP(i, 26) {
            //printf("%c K[alph_next[i][cur]] : %d K[cur] : %d\n", i + 'a', K[alph_next[i][cur]], K[cur]);
            // 現在地 cur から見た K と alph_next[i][cur] の K の関係を見て、アルファベットを決定する
            if(K[alph_next[i][cur]] == K[cur] - 1) {
                ans += (char)(i + 'a');
                cur = alph_next[i][cur] + 1;
                isFind = true;
                break;
            }        }
        if(!isFind) {
            ans += 'a';
        }
    }

    cout << ans << endl;

    return 0;
}

