vector<int> C[26];

int search(int i, int now){
	int ng = -1, ok = C[i].size();
	while(ok - ng > 1){
		int mid = (ng + ok)/2;
		if(C[i][mid] > now) ok = mid;
		else ng = mid;
	}
	if(ok == C[i].size()) return -1;
	else return ok;
}

