int lmost [ALPH][MAX_N];
int dp [MAX_N][ALPH];

void report (int length, int start) {
  int cur = start, pos = lmost[start][0];
  for (int k = length - 1; k >= 0; k--) {
    cout << (char) ('a' + cur);    
    if (k != 0) {
      for (int i = 0; i < ALPH; i++) {
        if (dp[k][i] < pos) {
          pos = lmost[i][pos + 1];
          cur = i;
          break;
        }
      }
    }
  }
  cout << endl;
  exit(0);
}

