using namespace std;
int nxt[26][200010];
int dp[200010];
char s[200010];
int n;

const int alpha = 26;

int main() {
	scanf("%s", s);
	n = strlen(s);

	for(int i = 0; i < alpha; i++) {
		int last = n;
		for(int j = n-1; j >= 0; j--) {
			nxt[i][j] = last;
			if(s[j] - 'a' == i) last = j;
		}
	}
	dp[n] = 1;
	for(int i = n-1; i >= 0; i--) {
		int opt = 0;
		for(int j = 0; j < alpha; j++) {
			opt = max(opt, nxt[j][i]);
		}
		dp[i] = 1 + dp[opt];
	}
	int ans = n+1;
	bool vis[30];
	memset(vis, false, sizeof vis);
	vector <int> pos;

	for(int i = 0; i < n; i++) {
		int c = s[i] - 'a';
		if(vis[c] == false) {
			vis[c] = true;
			ans = min(dp[i], ans);
			pos.push_back(i);
		}
	}
	for(int i = 0; i < alpha; i++) {
		if(vis[i] == false) {
			printf("%c\n", i + 'a');
			exit(0);
		}
	}

	int cur = 0;
	int opt = 26;
	for(int i : pos) {
		int c = s[i] - 'a';
		if(dp[i] == ans && opt > c) {
			opt = c;
			cur = i;
		} 
	}

	string res = "";
	res += s[cur];

	for(int i = 2; i <= ans; i++) {
		int best = ans - i + 1;
		assert(cur < n);
		for(int j = 0; j < alpha; j++) {
			if(best == dp[nxt[j][cur]]) {
				char x = j + 'a';
				res += x;
				cur = nxt[j][cur];
				break;
			}
		}
	}
	assert(cur == n);
	cout << res << '\n';
	return 0;
}

