int rec(int i)
{
    if (i >= A.length()) {
        memo[i].second = -1;
        return 1;
    }
    if (dp[i] != 0) return dp[i];

    int minV = 90909090;
    char minC;

    REP(j,26) {
        if (ne[i][j] == A.length()) {   //見つからなかった場合
