#include<bits/stdc++.h>
using namespace std;
const int maxn=200000+10;
char s[maxn];
int n,now[30],nxt[maxn][30],f[maxn],ans[maxn],tot;
int dfs(int p)
{
	if(p==n+1) return 0;
	if(f[p]!=-1) return f[p];
	int res=dfs(p+1)+1;
	for(int i=1;i<=26;i++)
	{
		if(i==s[p]-'a'+1) continue;
		if(!nxt[p][i])
			res=0;
		else res=min(res,dfs(nxt[p][i]+1)+1);
	}
	return f[p]=res;
}
void work(int p)
{
	if(!f[p])
	{
		for(int i=1;i<=26;i++)
			if(!nxt[p][i]&&s[p]-'a'+1!=i)
			{
				ans[++tot]=i;
				return;
			}
	}
	for(int i=1;i<=26;i++)
	{
		if(s[p]-'a'+1==i)
		{
			if(f[p+1]+1==f[p])
			{
				ans[++tot]=i;
				work(p+1);
				return;
			}
		}
		else
		{
			int v=nxt[p][i];
			if(f[v+1]+1==f[p])
			{
				ans[++tot]=i;
				work(v+1);
				return;
			}
		}
	}
}
int main()
{
	scanf("%s",s+1);
	n=strlen(s+1);
	memset(f,-1,sizeof(f));
	for(int i=1;i<=n;i++)
	{
		int v=s[i]-'a'+1;
		for(int j=now[v]+1;j<i;j++)
			nxt[j][v]=i;
		now[v]=i;
	}
	dfs(1);
	work(1);
	for(int i=1;i<=tot;i++)
	{
		char ch=ans[i]+'a'-1;
		cout<<ch;
	}
	return 0;
}

