string bfs(string str)
{
	queue<pair<string,int > > que;
	for (int i = 0; i < 26; ++i)
	{
		bool ex = false;
		for (int j = 0; j < str.length(); ++j)
		{
			if(str[j]==i+'a')
			{
				ex = true;
				string tmp;
				tmp.clear();
				tmp+=str[j];
				que.push({tmp,i});
			}
		}
		if(!ex)
		{
			string tmp;
			tmp.clear();
			tmp.push_back(i+'a');
			return tmp;
		}
	}
	string last = "";
	set<string > s;
	while(!que.empty())
	{
		pair<string,int > now = que.front();
		que.pop();
		// debug(now.first);
		// debug(last);
		if(last=="")
		{
			last = now.first;
			s.clear();
			for (int i = 0; i < 26; ++i)
			{
				string tmp = now.first;
				tmp.push_back(i+'a');
				// debug(tmp);
				s.insert(tmp);
			}
			// debug(s.size());
		}
		else if(now.first!=last)
		{
			// debug(last);
			last = now.first;
			// debug(s.size());
			if(!s.empty())	return *s.begin();
			s.clear();
			for (int i = 0; i < 26; ++i)
			{
				string tmp = now.first;
				tmp.push_back(i+'a');
				s.insert(tmp);
			}
		}
		if(now.second<str.length()-1)
		{
			string tmp = now.first;
			tmp.push_back(str[now.second+1]);
			if(s.find(tmp)!=s.end())
			{
				// debug(tmp);
				s.erase(tmp);
				que.push({tmp,now.second+1});
			}
		}
	}
}
