struct Problem {
  string s;
  int n;
  vector<vector<int>> nxt;

  vector<int> memo, ans;
  Problem(string s) : s(s), n(s.length() + 1), nxt(n, vector<int>(26)), memo(n, -1), ans(n){};
  void solve() {
    s = "*" + s;
    vector<int> tmp(26, INF);
    for (int i = n - 1; i >= 0; --i) {
      nxt[i] = tmp;
      if (i > 0) tmp[s[i] - 'a'] = i;
    }
    dfs(0);
    for (int i = 0; i < INF; i = nxt[i][ans[i]]) {
      cout << (char)('a' + ans[i]);
    }
    cout << endl;
  }
  int dfs(int p) {
    if (p == INF) return 0;
    if (memo[p] >= 0) return memo[p];
    int amin = 0, mini = INF;
    for (int i = 0; i < 26; ++i) {
      int res = dfs(nxt[p][i]);
      if (res < mini) {
        amin = i;
        mini = res;
      }
    }
    ans[p] = amin;
    return memo[p] = mini + 1;
  }
};

int main() {
  cin.tie(0);
  ios_base::sync_with_stdio(false);
  std::string s;
  cin >> s;
  Problem p(s);
  p.solve();
  return 0;
}

