    dp[n] = 1;
    for(int i = n - 1; i >= 0; --i) {
        int l = INT_MAX;
        FOR(j, 0, 26) {
            l = min(l, dp[next[i][j] + 1] + 1);
        }
        dp[i] = l;
    }

    string ans;
    int p = 0;
    for (int i = dp[0] - 1; i >= 0; --i) {
        FOR(j, 0, 26) {
            if (dp[next[p][j] + 1] == i) {
                ans += char('a' + j);
                p = next[p][j] + 1;
                break;
            }
        }
    }
    cout << ans << endl;

