vector<vi32> calcNext(const string &s) {
  int n = s.size();
  // 文字cが存在しないときのインデックスはn
  // 文字列の長さがnなので、nは範囲外を表すものとして最適なのかも
  vector<vi32> res(n + 1, vi32(26, n));
  rrep(i, n) {
    rep(j, 26) res[i][j] = res[i + 1][j];
    res[i][s[i] - 'a'] = i;
  }
  return res;
}

