int getL(vector<int> &vec, int val) {return vec[lower_bound(ALL(vec), val) - vec.begin()];}
int main() {
	scanf("%s", S); N = strlen(S);
	for(int i=0; i<N; i++) Ix[S[i]-'a'].push_back(i);
	for(int k=0; k<26; k++) Ix[k].push_back(N);
	for(int i=0; i<=N; i++) for(int k=0; k<26; k++) Block[0][i] = max(Block[0][i], getL(Ix[k], i));
	for(int p=0; p<LOG_N; p++) Block[p][N+1] = N;
	for(int p=1; p<LOG_N; p++) for(int i=0; i<=N; i++) Block[p][i] = Block[p-1][Block[p-1][i]+1];

	int ansL = 0, nowIx = 0;
	for(int p=LOG_N-1; p>=0; p--) if(Block[p][nowIx] < N) ansL += (1<<p), nowIx = Block[p][nowIx] + 1;
	bitset<26> chkLast; for(int i=nowIx; i<N; i++) chkLast[S[i]-'a'] = true;
	vector<int> candiLast;
	for(int i=0; i<26; i++) if(chkLast[i] == false) candiLast.push_back(i);

	if(ansL == 0) return printf("%c\n", candiLast.front() + 'a') < 0;

	vector<string> candiAns;
	for(int last : candiLast) {
		candiAns.push_back("");
		int now = 0;
		int less = Ix[last][SZ(Ix[last])-2];
		for(int l=1; l<=ansL; l++) {
			for(int k=0; k<26; k++) {
				int start = getL(Ix[k], now)+1; 
				int end = start; for(int p=0; p<LOG_N; p++) if((ansL-l) & (1<<p)) end = Block[p][end] + 1;
				if(end <= less) continue;
				candiAns.back().push_back(k + 'a');
				now = start + 1;
				break;
			}
		}
		candiAns.back().push_back(last + 'a');
	}

	string ans = "";
	for(string &str : candiAns) if(ans == "" or ans > str) ans = str;
	printf("%s\n", ans.c_str());
	return 0;
}

