void solve(string A){
	vector<vector<int> > dp(A.size()+1,vector<int>(26));
	vector<int> mini(A.size()+1);
	REP(c,26)dp[A.size()][c] = 1;
	mini[A.size()] = 1;
	for(int i=A.size()-1;i>=0;i--){
		int mini_val = 1000000000;
		REP(c,26){
			if(A[i]==c + 'a'){
				dp[i][c] = mini[i+1] + 1;
			}else{
				dp[i][c] = dp[i+1][c];
			}
			mini_val = min(dp[i][c], mini_val);
		}
		mini[i] = mini_val;
	}
	int s = mini[0];
	string ans;
	int i = 0;
	while(s>0){
		REP(c,26){
			if(dp[i][c]==s){
				ans += 'a' + c;
				while(i<A.size() and A[i]!='a'+c)i++;
				s--;
				i++;
				break;
			}
		}
	}
	fout<<ans<<endl;
}

int main(){	
	string A;
	fin >> A;
	solve(A);
	return 0;
}

