const int MAX = 2e5 + 5, MOD = 1e9 + 7, oo = 1 << 30;

#define CLR(a,v) memset(a,v,sizeof(a))
#define all(v) v.begin(),v.end()
#define sz(v) (int)v.size()
typedef vector<int> vi;

char s[MAX];
int n, path[MAX], dp[MAX], memo[MAX];
vi occ[26];

int solve(int i) {
	if (i == n + 1)
		return memo[i] = 0;
	int &ret = memo[i];
	if (~ret)
		return ret;
	ret = oo;
	for (int j = 0; j < 26; ++j) {
		int reqIdx = i;
		if (s[i] == j + 'a')
			++reqIdx;
		int idx = lower_bound(all(occ[j]), reqIdx) - occ[j].begin();
		ret = min(ret, solve(occ[j][idx]) + 1);
	}
	return ret;
}

void buildPath(int i) {
	if (i == n + 1)
		return;
	int &mn = memo[i];
	for (int j = 0; j < 26; ++j) {
		int reqIdx = i;
		if (s[i] == j + 'a')
			++reqIdx;
		int idx = lower_bound(all(occ[j]), reqIdx) - occ[j].begin();
		if (memo[occ[j][idx]] + 1 == mn) {
			cout << char(j + 'a');
			buildPath(occ[j][idx]);
			break;
		}
	}
}

int main() {
	scanf("%s", s + 1);
	n = strlen(s + 1);
	for (int i = 1; i <= n; ++i)
		occ[s[i] - 'a'].push_back(i);
	for (int i = 0; i < 26; ++i)
		occ[i].push_back(n + 1);
	CLR(memo, -1);
	solve(0);
	buildPath(0);
}

