using namespace std;

int n;
string seq_s;
vector<char> seq;
int lkt[200010][26];

void solve() {
    queue<pair<int, string>> q;
    q.push(make_pair(0, string("")));

    while(!q.empty()) {
        pair<int, string> current = q.front();
        q.pop();

        int *current_lkt = lkt[current.first];
        for(int i = 0; i < 26; i++) {
            string s = current.second;
            s += ((char) i + 'a');
            if(current_lkt[i] == -1) {
                throw s;
            }
            q.push(
                make_pair(
                    current_lkt[i],
                    s
                )
            );
        }
    }
}

int main() {
    cin >> seq_s;
    seq.push_back(-1);
    for(int i = 0; i < seq_s.size(); i++) {
        seq.push_back(seq_s[i] - 'a');
    }

    n = seq.size() - 1;

    int current_lkt[26];
    for(int i = 0; i < 26; i++) {
        current_lkt[i] = -1;
    }

    for(int i = n; i >= 0; i--) {
        memcpy(lkt[i], current_lkt, 26);
        current_lkt[seq[i]] = i;
    }

    try {
        solve();
    } catch(string s) {
        cout << s << endl;
    }

    return 0;
}

