int n,nxt[26][200010], pre[26], dp[200010], ch[200010];
string ans = "";

int bt(int x) {
	if (dp[x] != -1) return dp[x];
	FOR(i,0,26) {
		if (nxt[i][x] == -1) {;
			ch[x] = i;
			return dp[x] = 1;
		}
	}
	int ans = 1e9 + 7;
	FOR(i,0,26) {
		int cur = (bt(nxt[i][x]));
		if (cur < ans) {
			ch[x] = i;
			ans = cur;
		}
	}
	return dp[x] = ans + 1;
}

void print(int x) {
	ans += ('a' + ch[x]);
	if (dp[x] == 1) return;
	int idx = -1, mi = 1e9 + 7;
	FOR(i,0,26) {
		if (dp[nxt[i][x]] > -1 && dp[nxt[i][x]] < mi) {
			mi = dp[nxt[i][x]];
			idx = nxt[i][x];
		}
	}
	print(idx);
}

