void restore(int i)
{
    if (end[i])
    {
        for (int j = 0; j < 26; j++)
        {
            if (go[i][j] == -1)
            {
                cout << char(j + 'a');
                exit(0);
            }
        }
    }
    else
    {
        for (int j = 0; j < 26; j++)
        {
            if (go[i][j] != -1 && vis[go[i][j]] && dp[go[i][j]] == dp[i] + 1)
