                if (dp[i] > 1) {
                    dp[i] = 1;
                    restoration[i] = make_pair('a'+j, n);
                }
            } else if (dp[i] > dp[next[i][j] + 1] + 1) {
                dp[i] = dp[next[i][j] + 1] + 1;
                restoration[i] = make_pair('a'+j, next[i][j] + 1);
            }
        }
