void make_word(char* word)
{
	unsigned int i;
	for(i=0; i<strlen(word); i++){
		if(word[i] != 'z'){
			goto not_all_z;
		}
	}
	//ここに来たらAll z
	for(i=0; i<strlen(word); i++){
		word[i] = 'a';
	}
	word[i] = 'a';
	word[i+1] = '\0';

	return;

not_all_z:
	if(word[strlen(word)-1]=='z')
	{ 
		word[strlen(word)-1] = 'a';
		for(int j=strlen(word)-2;j>=0;j--){
			if(word[j]!='z'){
				word[j] += 1;
				break;
			}else{
				word[j] = 'a';
			}
		}
	}else{
		word[strlen(word)-1] += 1;
	}

	return;

}

