    temp[s[i]-'a']++;
    len[i]=len[i+1];
    bool flag=true;
    rep(j,0,26)flag&=(temp[j]>0);

    if(flag){
      len[i]++;
      rep(j,0,26)temp[j]=0;
    }
  }

  std::string ans="";
  ll now=0;

  rep(i,0,len[0]){
    rep(j,0,26){
      auto itr=std::lower_bound(all(occur[j]),now);
      if(itr==occur[j].end()||len[now]-1==len[*itr+1]){
        ans+=(char)('a'+j);
        if(itr!=occur[j].end())now=*itr+1;
        break;
      }
    }
  }

  std::cout<<ans;

  return 0;
}

