int main(const int argc, char * argv [])
{
  ios_base::sync_with_stdio(0); cin.tie(0); cout.tie(0);

  string str;
  cin >> str;

  vector<vector<size_t>> xs(26);
  for(size_t i = 0; i < str.size(); ++i)
    xs[str[i] - 'a'].push_back(i);

  typedef struct {
    size_t idx;
    size_t cnt;
    char ch;
  } value_t;

  const auto n = str.size();
  vector<value_t> next(str.size());

  for(size_t x = n - 1; x < n; --x)
  {
    next[x].idx = -1;
    next[x].cnt = -1;
    next[x].ch = '?';

    for(size_t i = 0; i < xs.size(); ++i)
    {
      const auto iter = lower_bound(begin(xs[i]), end(xs[i]), x + 1);
      if (iter != end(xs[i]))
      {
        const auto& v = next[*iter];
        if (v.cnt + 1 < next[x].cnt)
        {
          next[x].idx = *iter;
          next[x].cnt = v.cnt + 1;
          next[x].ch = 'a' + i;
        }
      }
      else
      {
        next[x].idx = -1;
        next[x].cnt = 2;
        next[x].ch = 'a' + i;
        break;
      }
    }
  }

  size_t size = -1, idx = -1;

  for(size_t i = 0; i < xs.size(); ++i)
    if(xs[i].empty())
    {
      cout << ((char) ('a' + i));
      return 0;
    }
    else if (next[xs[i].front()].cnt < size)
    {
      size = next[xs[i].front()].cnt;
      idx = i;
    }

  size_t x = xs[idx].front();
  cout << str[x];

  for(; x != (size_t) -1;)
  {
    cout << next[x].ch;
    x = next[x].idx;
  }

  return EXIT_SUCCESS;
}

