bool comp(string a, string b) {
  if (a == "")
    return true;
  if (a.size() > b.size())
    return true;
  else if (a.size() < b.size())
    return false;
  else {
    ll n = a.size();
    REP(i, n) {
      if (a[i] > b[i])
        return true;
      else if (a[i] < b[i])
        return false;
    }
  }
  return false;
}

