      if (DP[i] > DP[nxt + 1] + 1) {
        restore[i] = {(char)('a' + c), nxt + 1};
        DP[i] = DP[nxt + 1] + 1;
      }
    }
  }
  ll cur = 0;
  while (cur < N) {
