const int MAX = 2e5+10;
const int ALPHA = 26;

string S;

vvii nxt;

string solve() {
    int sz = S.size();
    nxt = vvii(sz+1, vii(ALPHA));
    vii state(ALPHA+1, ii(-1, 0));

    REPR (i, sz) {
        ll mn = MAX;
        REP (a, ALPHA) { 
            nxt[i+1][a] = state[a];
            CHMIN(mn, state[a].second);
        }
        int al = S[i] - 'a';
        state[al].first = i;
        state[al].second = mn+1;
    }
    nxt[0] = vii(26);
    REP (a, ALPHA) nxt[0][a] = state[a];

    int idx = 0;
    string ans = "";
    while (1) {
        ii n(-1, MAX);
        int c = 0;
        REP (a, ALPHA) {
            if (nxt[idx][a].second < n.second) {
                n = nxt[idx][a];
                c = a;
            }
        }
        ans += c + 'a';
        if (n.first == -1) return ans;
        idx = n.first + 1;
    }
}

