	for(int i = 0; i < N + 1; i++) {
		if(dp[i] == INF) continue;
		for(int j = 0; j < 26; j++) {
			int nxt = *lower_bound(idx[j].begin(), idx[j].end(), i + 1);
			dp[nxt] = max(dp[nxt], dp[i] + 1);
		}
	}

	for(int i = N - 1; i >= 0; i--) {
		if(dp[i] == INF) continue;
		for(int j = 0; j < 26; j++) {
			int nxt = *lower_bound(idx[j].begin(), idx[j].end(), i + 1);
			if(dp[i] + 1 == dp[nxt]) {
				nxtc[i] = 'a' + j;
				nxtid[i] = nxt;
				break;
			}
		}
	}

	string ans;
	for(int i = 0; i < N + 1;) {
		ans += nxtc[i];
		i = nxtid[i];
	}
	cout << ans << endl;
}

