    //後ろからdp
    reverse(all(S));
    //次にjが出てくるid(0-indexed)
    vector<vector<int>> nex(N+1, vector<int>(26,N));
    for (int i = N-1; i >= 0; i--) {
        rep(j,26) nex[i][j] = nex[i+1][j];
        nex[i][S[i]-'a'] = i;
    }
    //(1-indexed) i文字目の前まで見て最後にj使ったときの求めたい文字列の長さの最小値
    vector<vector<int>> dp(N+2, vector<int>(26,1e9));
    rep(j,26) dp[0][j] = 0;
    rep(i,N+1) {
        int m = 1e9;
        rep(j,26) chmin(m,dp[i][j]);
        rep(j,26) chmin(dp[nex[i][j]+1][j],m+1);
    }
    for (int i = N+1; i > 0; i--) {
        rep(j,26) chmin(dp[i-1][j],dp[i][j]);
    }
    int cur = N+1;
    int val = 1e9;
    int num = 26;
    int pos = N+1;
    rep(i,26) if (chmin(val,dp[N+1][i])) num = i;
    string ans = "";
