    // cur = nex[i][j]+1のi
    while (cur) {
        while (cur and nex[cur-1][num]+1>=pos) cur--;
        if (!cur) break;
        rep(j,26) {
            if (dp[cur][j]==val-1) {
                num = j;
                break;
            }
        } 
        ans += char(num+'a');
        val--;
        pos = cur;
    }

    cout << ans << ln;
}

