        if (a[n - 1] != i + 'a') {
            dp[n - 1][i] = (char)(i + 'a');
        }
        else {
            dp[n - 1][i] += (char)(i + 'a');
            dp[n - 1][i] += 'a';
        }
    }
    for (int i = n - 2; i >= 0; i--) {
        rep(j, 26) {
            if (a[i] != j + 'a') {
