        bool flag=true;
        for(auto b:x){
            if(!b){
                flag=false;
                break;
            }
        }
        if(flag){
            p.push_back(i);
            ans_size++;
            for(auto b:x){
                b=false;
            }
        }
    }
    reverse(p.begin(),p.end());
    function<int(int)> count_loop = [&](int start){
        for(int i:R(0,p.size())){
            if(start<=p[i]){
                return (int)(p.size()-i);
            }
        }
        return 0;
    };
    vector<vector<int>> y(26,vector<int>(0));
    for(int i:R(0,a.size())){
        y.at(a.at(i)-'a').push_back(i);
    }
    //'a'=0
    vector<int> ans(ans_size,0);
    vector<int> ans_index(ans_size,0);
    for(int i=0;i<ans_size-1;i++){
        while(true){
            int index=(i==0?0:ans_index.at(i-1)+1);
            for(int j=(i==0?0:ans_index.at(i-1)+1);j<a.size();j++){
                if(a.at(j)-'a'==ans.at(i)){
                    index=j;
                    break;
                }
            }
            for(int j:R(0,y.at(ans.at(i)).size())){
                if(index<=y.at(ans.at(i)).at(j)){
                    index=y.at(ans.at(i)).at(j);
                    break;
                }
            }
            //DEBUG(i);
            int c=count_loop(index+1);;
            if(c<ans_size-1-i){
                ans_index.at(i)=index;
                break;
            }else{
                ans.at(i)++;
            }
        }
    }
    for(auto b:x){
        b=false;
    }
    for(int i=ans_index.at(ans_index.size()==1?0:ans_index.size()-2);i<a.size();i++){
        x.at(a.at(i)-'a')=true;
    }
    for(int i=0;i<26;i++){
