class Dijkstra {
    private:
        struct Edge {
            int to;   // 有向辺の行先頂点
            char cost;  // 辺の重み
        };
        typedef pair<string, int> P;       // first: 最短距離 second: 頂点 id
    public:
        // コンストラクタ
        // v … 頂点数, inf: …「無限大」とする値
        Dijkstra(int v, string inf) : m_V(v), m_Inf(inf) {
            m_G.assign(m_V, vector<Edge>());
            m_Dist.assign(m_V, m_Inf);
        }
        // 有向辺の追加。負のコストは未対応
        void AddDirEdge(int from, int to, char cost) { m_G[from].push_back({to, cost}); }
        // 始点 s から各頂点への最短経路の導出 O(E log V)
        void Calc(int s) {
            // 最短距離が短い順で cand を取り出す
            // 頂点 P.second まで P.first のコストで来れたことを情報として入れておく
            priority_queue<P, vector<P>, greater<P> > cand;
            m_Dist[s] = "";  // 始点のコストは 0
            cand.push(P("", s));
            while(!cand.empty()) {
                P p = cand.top(); cand.pop();     // cand のトップを取り出す
                int v = p.second;
                // 頂点 v まで最短経路が、 cand から取り出したものより既に小さいなら何もしない
                if(m_Dist[v] < p.first){ continue; }
                // 現在見ている頂点から延びている辺を全て見る
                for(Edge e : m_G[v]) {
                    if(m_Dist[e.to].length()-1 > m_Dist[v].length() ||
                            (m_Dist[e.to].length()-1 == m_Dist[v].length() && m_Dist[e.to] > m_Dist[v] + e.cost )) {
                        // 現在の最短経路より短くなるなら更新
                        m_Dist[e.to] = m_Dist[v] + e.cost;
                        cand.push(P(m_Dist[e.to], e.to));
                    }
                }
            }
        }
        // 始点 s から頂点 t への最短距離を返す O(1)
        // 前処理として Calc(s) が必要
        string GetDist(int t) { return m_Dist[t]; }

    private:
        const int m_V;                // 頂点の数
        const string m_Inf;              // 無限の代わりとして扱う値
        vector< vector<Edge> > m_G; // 頂点 i から延びている辺の vector(隣接リスト)
        vector<string> m_Dist;           // 各頂点への最短コスト。つまり答え
};

signed main()
{
    cin >> A;
    A2 = "s" + A + "abcdefghijklmnopqrstuvwxyzt";

    // next_pos の作成
    int tail = A2.size()-1;
    int find_alph = A2[tail] - 'a';
    REP(i, 26) {
        next_pos[tail][i] = tail;
    }
    for(int i = A2.size()-2; i >= 0; --i) {
        REP(j, 26) {
            next_pos[i][j] = next_pos[i+1][j];
        }
        next_pos[i][find_alph] = i+1;
        find_alph = A2[i] - 'a';
    }

    // DEBUG
#if 0
    REP(i, A2.size()) {
        REP(j, 26) {
            DBG("next_pos[%lld][%c] : %lld\n", i, static_cast<char>(j + 'a'), next_pos[i][j]);
        }
    }
#endif

    // DAG の構築
    string inf_str = "";
    REP(i, MAX_N) { inf_str += 'z'; }
    Dijkstra dk(A2.size(), inf_str);
    int s_id = 0;
    int t_id = tail;
    REP(i, A2.size() - 1) {
        REP(j, 26) {
            dk.AddDirEdge(i, next_pos[i][j], A2[next_pos[i][j]]);
        }
    }

    dk.Calc(s_id);

    // 最短経路の取得
    string ans = dk.GetDist(t_id);
    ans = ans.substr(0, ans.length()-1);
    printf("%s\n", ans.c_str());

    return 0;
}

