void solve() {
  string s; cin >> s;

  int n = s.size();

  vi cycle({n}); cycle.reserve(n/26);
  bitset<26> used(0);

  rrep(i,n) {
    used.set(s[i]-'a');

    if (used.all()) {
      cycle.emplace_back(i);
      used.reset();
    }
  }

  reverse(ALL(cycle));

  Graph<int> pos(26);

  rep(i,n) {
    pos[s[i]-'a'].emplace_back(i);
  }

  rep(j,26) {
    pos[j].emplace_back(n);
  }

  const int len = cycle.size();
  int prev = -1;
  string ans;

  rep(i,len) {
    rep(j,26) {
      int k = *upper_bound(ALL(pos[j]), prev);

      if (k >= cycle[i]) {
        ans.push_back('a'+j);
        prev = k;
        break;
      }
    }
  }

  cout << ans << endl;
}


