    for (int j = 0; j < 26; j++) {
      if (Next[i][j] != INF) {
        Prev[Next[i][j]].push_back(i);
      }
    }
  }
  for (int i = 0; i < N; i++) {
    bool T = false;
    for (int j = 0; j < 26; j++) {
      if (Next[i][j] == INF) {
        T = true;
      }
    }
    if (T) {
      que.push(make_pair(0,i));
    }
  }

  while (!que.empty()) {
    P p = que.front();
    if (dis[p.S] <= p.F) {
      continue;
    }
    dis[p.S] = p.F; 
    que.pop();
    for (int i = 0; i < (int)Prev[p.S].size(); i++) {
      if (dis[Prev[p.S][i]] > p.F + 1) {
        que.push(make_pair(p.F+1,Prev[p.S][i]));
      }
    }
  }
  string ans = "";
