const int N = 2e5+5;
string a;
int n;
vector<int> b[26];
int dp[N][26];

void fn(int x,int y) {
    //printf("%d %d\n",x,y);
    auto it = lower_bound(b[y].begin(),b[y].end(),x);
    if(it == b[y].end()) {
        dp[x][y] = 1;
        return;
    }
    for(int i=0;i<26;i++) {
        if(dp[*it+1][i] == N) fn(*it+1,i);
        dp[x][y] = min(dp[x][y],dp[*it+1][i]+1);
    }
}

void construct(int x,string& ans) {
    int ix = 0;
    for(int i=0;i<26;i++) if(dp[x][i] < dp[x][ix]) ix = i;
    ans += 'a'+ix;
    if(dp[x][ix] == 1) return;
    else construct(*lower_bound(b[ix].begin(),b[ix].end(),x)+1,ans);
}

