auto comp = [](const string& a, const string& b) { return (a.size() == b.size()) ? a < b : a.size() < b.size(); };

string solve() {
    int idx = 0;
    for (int i = 0; i < 26; i++) {
        string a = {(char)('a'+i)};
        if (s[l-1]-'a' == i) {
            dp[idx][i] = a + "a";
        } else {
            dp[idx][i] = a + "";
        }
    }

    for (int n = l-2; n >= 0; n--) {
        for (int k = 0; k < 26; k++) {
            if (s[n]-'a' == k) {
                vector<string> v;
                for (int i = 0; i < 26; i++) {
                    v.push_back(dp[idx][i]);
                }
                sort(ALL(v), comp);
                dp[1-idx][k] = (char)('a'+k) + v[0];
            } else {
                dp[1-idx][k] = dp[idx][k];
            }            
        }
        idx = 1 - idx;
    }

    vector<string> v;
    for (int i = 0; i < 26; i++) {
        v.push_back(dp[idx][i]);
    }
    sort(ALL(v), comp);
    return v[0];
}

