        if(!pos[i].size()){
            cout << (char)(i + 'a') << endl;
            return 0;
        }
        pos[i].emplace_back(n);
    }

    vector<int> dp(n + 1, INF);
    dp[n] = 0;
    auto MemoRec = [&](auto&& self, int cur_pos = 0) -> int {
        if(dp[cur_pos] != INF)  return dp[cur_pos];
        int res = INF;
        for(int i = 0; i < 26; ++i){
            int nxt_pos = *upper_bound(pos[i].begin(), pos[i].end(), cur_pos);
            chmin(res, self(self, nxt_pos));
        }
        return dp[cur_pos] = res + 1;
    };
    MemoRec(MemoRec);

    int len = INF;
    int cur_pos = -1;
    int idx = 0;
    for(int i = 0; i < 26; ++i){
        if(chmin(len, dp[pos[i][0]])){
            cur_pos = pos[i][0];
            idx = i;
