    while(len > 0){
        for(int i = 0; i < 26; ++i){
            int nxt_pos = *upper_bound(pos[i].begin(), pos[i].end(), cur_pos);
            if(dp[nxt_pos] == len - 1){
                ans += (char)(i + 'a');
                --len;
                cur_pos = nxt_pos;
                break;
            }
        }
    }
    cout << ans << endl;
}

