		return (occ[huruf]==1);
	if(memo[pos][huruf])
		return dp[pos][huruf];
	memo[pos][huruf]=true;
	bool &ret=dp[pos][huruf];
	ret=false;
	int awal=pospertama(batas[pos],huruf)+1;
	bool bisa[totalhuruf];
	for(int i=0;i<totalhuruf;i++)
