using ii = std::pair<int, int>;

std::string str;
int table[200001][26];
int next[200001][26];

int solve(int k, int find)
{
	if (k == str.size() - 1)
	{
		if (str[k] != find + 'a')
			return 0;
		else
			return 987654321;
	}

	if (table[k][find] != -1)
		return table[k][find];

	int& res = table[k][find];
	res = 987654321;

	if (find + 'a' == str[k])
	{
		for (int i = 0; i < 26; i++)
		{
			int calc = 1 + solve(k + 1, i);
			if (calc < res)
			{
				res = calc;
				next[k][find] = i;
			}
		}
	}
	else
	{
		res = solve(k + 1, find);
	}

	return res;
}

int main()
{
	std::cin >> str;

	int min = 987654321;
	int first = 0;

	memset(table, -1, sizeof(table));
	memset(next, -1, sizeof(next));

	for (int i = 0; i < 26; i++)
	{
		int k = solve(0, i);
		if (k < min)
		{
			min = k;
			first = i;
		}
	}

	std::string ans;
	ans.push_back(first + 'a');

	for (int i = 0; i < str.size(); i++)
	{
		if (next[i][first] != -1)
		{
			first = next[i][first];
			ans.push_back(first + 'a');
		}
	}

	std::cout << ans;

	return 0;
}

