#include <bits/stdc++.h>
using namespace std;

deque<char> ans;

int search(int n, vector<vector<int>> &next, string &s) {
    char c = 0;
    for (int cur = 0; cur <= n; ) {
        int maxi = cur;
        for (int i = 0; i < 26; i++) {
            if (next[cur][i] == -1 || next[cur][i] > n) {
                c = 'a' + i;
                maxi = -1;
                break;
            } else maxi = max(next[cur][i], maxi);
        }
        if (maxi == -1) break;
        cur = maxi;
    }
    ans.emplace_back(c);
    for (int i = n-1; i >= 0; i--) {
        if (s[i] == c) return i;
    }
    return -1;
}

int main() {
    string s; cin >> s;
    int n = s.size();
    reverse(s.begin(), s.end());
    vector<vector<int>> next(n+1, vector<int>(26, -1));
    for (int i = 0; i < n; i++) {
        next[i][s[i]-'a'] = i+1;
    }
    for (int i = n; i > 0; i--) {
        for (int j = 0; j < 26; j++) {
            if (next[i-1][j] == -1) next[i-1][j] = next[i][j];
        }
    }
    int u = n;
    while (true) {
        int ret = search(u, next, s);
        if (ret == -1) break;
        else u = ret;
    }
    for (int i = 0; i < ans.size(); i++) {
        cout << ans[i];
    }
    cout << endl;
    return 0;
}

