using namespace std;
#define ll long long

int main(){
    string S;
    cin >> S;
    int N = S.size();
    vector<vector<int>> dp(26, vector<int>(N+1, -1));
    vector<int> l(26, 0); //l[i] = ('a'+i)から始まるn文字の全ての文字列が作れる最大のn
    for (int i = 0; i < 26; i++) dp[i][0] = N;
    for (int i = N-1; i >= 0; i--) {
        int c = S[i] - 'a';
        int t = N;
        for (int j = 0; j < 26; j++) t = min(t, l[j]);
        if (l[c] == t) {
            l[c]++;
            dp[c][t+1] = i;
        }
    }

    //for (int i = 0; i < 26; i++) cout << dp[i][1] << " " << dp[i][2] << " " << dp[i][3] << endl;

    pair<int, int> st;
    st = {0, l[0]};
    for (int i = 1; i < 26; i++) {
        if (st.second > l[i]) st = {i, l[i]};
    }

    int pos = 0;
    int now = st.second;
    string ans = "";
    while(now >= 0) {
        int lim = N;
        for (int i = 0; i < 26; i++) lim = min(lim, dp[i][now]);
        vector<bool> use(26, false);
        for (int i = pos; i < lim; i++) {
            use[S[i]-'a'] = true;
        }
        for (int i = 0; i < 26; i++) {
            if (!use[i]) {
                ans += (char)('a'+i);
                pos = lim+1;
                while (pos < N && (S[pos] - 'a' != i)) pos++;
                break;
            }
        }
        now--;
    }

    cout << ans << endl;
    return 0;
}

