using IV = std::vector<int>;
struct Score {
	uint64_t	score;
	bool		bFound;

	Score() = default;
	Score(uint64_t sc, bool bf):
		score(sc),
		bFound(bf)
	{}
	uint64_t value() const {
		return score | (bFound ? 0 : (uint64_t(1)<<63));
	}
	static Score GetMin(const Score& s0, const Score& s1) {
		if(s0.value() < s1.value())
			return s0;
		return s1;
	}
};
constexpr int NChar = 'z'-'a'+1;
Score BFS(const IV (&pos)[NChar], const int ofs, const uint64_t cur, const int depth, const Score& best) {
	if(depth < 0)
		return {cur, false};

	Score ret = best;
	For(i, 0, NChar) {
		auto& ps = pos[i];
		auto itr = std::lower_bound(ps.begin(), ps.end(), ofs);
		if(itr == ps.end()) {
			ret = Score::GetMin(ret, Score((cur<<8) + i+1, true));
		} else {
			auto nextsc = (cur<<8)+i+1;
			if(Score(nextsc, false).value() < best.value()) {
				const auto lr = BFS(pos, *itr+1, nextsc, depth-1, ret);
				ret = Score::GetMin(ret, lr);
			}
		}
	}
	return ret;
}
std::string NumToStr(uint64_t num) {
	std::string s;
	while(num != 0) {
		s.push_back((num & 0xff) + 'a' - 1);
		num >>= 8;
	}
	std::reverse(s.begin(), s.end());
	return s;
}
int main() {
	DisableIOSync();

	IV	pos[NChar];
	std::string str;
	std::getline(std::cin, str);
	const int Len = str.length();
	For(i, 0, Len) {
		const int idx = str[i] - 'a';
		pos[idx].push_back(i);
	}
	Score res;
	int depth = 0;
	for(;;) {
		res = BFS(pos, 0, 0, depth, Score(std::numeric_limits<uint64_t>::max(), false));
		if(res.bFound)
			break;
		++depth;
	}
	std::cout << std::hex << NumToStr(res.score) << std::endl;
	return 0;
}

