bool isSubstring() {
	int n = T.size(), m = S.size();
	int p = 0, q = 0;
	while (p < n) {
		while (q < m && S[q] != T[p]) {
			q++;
		}
		if (S[q] == T[p]) {
			p++;
			q++;
		}
		if (q >= m) break;
	}
	return p == n;
}
