	while (isSubstring()) {
		int n = T.size();
		for (int p = n-1; p >= 0; p--) {
			if (T[p] < 'z') {
				T[p]++;
				for (int i = p+1; i < n; i++) {
					T[i] = 'a';
				}
				break;
			}
		}
		if (T == string(n, 'z')) {
			T = string(n+1, 'a');
		}
	}
	cout << T << endl;
	exit(0);
}

