int INF = 1e9;
int32_t main()
{
	string s;
	cin >> s;
	int next[26][s.size()+1];
	for (int i=0; i < 26; i++){
		next[i][s.size()] = INF;
	}
	for (int i=s.size()-1;i>=0;i--){
		next[s[i] - 'a'][i] = i;
		for (int j=0; j < 26; j++){
			if (j == s[i] - 'a') continue;
			next[j][i] = next[j][i+1];
		}
	}
	int dp[s.size()+1];
	dp[s.size()] = 1;
	for (int i=s.size() - 1; i>=0; i--){
        int maximum = -1;
        for (int j=0; j < 26; j++){
			maximum = max(maximum, next[j][i]);
        }
        if (maximum == INF) dp[i] = 1;
        else dp[i] = dp[maximum+1] + 1;
	}
	int ans = dp[0];
	vector<vector<int> > vh;
	for (int i=0; i < 26; i++){
		vector<int> help;
		vh.push_back(help);
	}
	for (int i=0; i < s.size(); i++){
		vh[s[i] - 'a'].push_back(i);
	}
	int u[26];
	for (int i=0; i < 26; i++){
		u[i] = 0;
	}
	int last = -1;
	string answer = "";
	while (ans > 0){
        for (int j=0;j < 26; j++){
			while (u[j] != vh[j].size() && vh[j][u[j]] <= last){
				u[j]++;
			}
			if (u[j] == vh[j].size()){
				if (ans == 1){
					answer += j + 'a';
					ans--;
					break;
				}
				continue;
			}
			int ind = vh[j][u[j]];
			if (dp[ind+1] == ans - 1){
				answer += j + 'a';
				ans--;
				last = ind;
				break;
			}
        }
	}
	cout << answer << endl;
    return 0;
}

