            if (go[i][j] == -1 && dp[i] < ans)
            {
                ans = dp[i];
                st = i;
                last = j;
            }
        }
    }
    for (int i = 0; i < n; i++)
    {
        for (int j = 0; j < 26; j++)
        {
            if (go[i][j] == -1 && dp[i] == ans)
            {
                vis[i] = true;
                end[i] = true;
            }
        }
    }
    for (int i = n - 1; i >= 0; i--)
    {
        for (int j = 0; j < 26; j++)
        {
            if (go[i][j] != -1 && dp[go[i][j]] == dp[i] + 1)
            {
                vis[i] = true;
            }
        }
    }
    restore(0);
}

