int solve(int pos){
	if(pos == n) {
		choice[pos] = 'a';
		return 1;
	}
	if(dp[pos] != -1) return dp[pos];
	dp[pos] = 1 << 28;
	for(char c = 'a';c <= 'z';c++) {
		auto p = lower_bound(all(IDX[(int)c]),pos);
		if(p == IDX[(int)c].end()) {
			choice[pos] = c;
			dp[pos] = 1;
			break;
		}
		int tmp = min(dp[pos],1 + solve(*p + 1));
		if(tmp < dp[pos]) {
			dp[pos] = tmp;
			choice[pos] = c;
		}
	}
	return dp[pos];
}

