	for (i = 0; i < isubLen; i++) {
		c = sub[i];
		pos = (char*)strchr(pos, c);
		if (NULL == pos) { return false; }
		pos++;
	}

	return true;
}
string fNextString(const char *s)
{
	string sRet;
	int i, iCarry=1;
	char c;

	i = (int)strlen(s) - 1;
	for (; i >= 0;i--) {
		if (iCarry == 0) {
			sRet.insert(sRet.begin(), s,&s[i+1]);
			break;
		}
		c = s[i] + iCarry;		
		iCarry = (c > 'z')?1:0;
		c = (c > 'z')?'a': c;
		sRet.insert(sRet.begin(), c);
	};
	if (iCarry!=0) { sRet.insert(sRet.begin(), 'a'); }

	return sRet;
}


