const int MAX_N = 2e5 + 5;

int n;
string s;

int nextChar[MAX_N][27], firstLetter[27];

bool usedStates[MAX_N];
int dp[MAX_N], parent[MAX_N];

void Precompute() {
	int currNext[27];
	for(int i = 0; i < 26; i++) {
		currNext[i] = n;
	}

	for(int i = n - 1; i >= 0; i--) {
		for(int j = 0; j < 26; j++) {
			nextChar[i][j] = currNext[j];
		}

		currNext[s[i] - 'a'] = i;
	}

	for(int i = 0; i < 26; i++) {
		firstLetter[i] = currNext[i];
	}
}

int Solve(int ind) {
	if(ind == n) {
		return 0;
	}
	else if(usedStates[ind]) {
		return dp[ind];
	}

	int bestAns = n + 10, bestAnsChar = 0;
	for(int i = 0; i < 26; i++) {
		if(Solve(nextChar[ind][i]) + 1 < bestAns) {
			bestAns = Solve(nextChar[ind][i]) + 1;
			bestAnsChar = i;
		}
	}

	dp[ind] = bestAns;
	parent[ind] = bestAnsChar;
	usedStates[ind] = true;

	return bestAns;
}

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);

	cin >> s;
	n = s.size();

	s += 'a';

	Precompute();

	int ansLength = n + 1, startInd = 0, startLetter = 0;
	for(int i = 0; i < 26; i++) {
		if(Solve(firstLetter[i]) + 1 < ansLength) {
			ansLength = Solve(firstLetter[i]) + 1;
			startInd = firstLetter[i];
			startLetter = i;
		}
	}

	string ans = "";
	ans += (char)(startLetter + 'a');
	while(startInd < n) {
		ans += (char)(parent[startInd] + 'a');

		startInd = nextChar[startInd][parent[startInd]];
	}

	cout << ans << endl;
	return 0;
}

