vll dp;

ll dp_init(ll pos, bool flag){
  if(dp[pos]>=0) return dp[pos];
  if(pos>=N) return 0;
  dp[pos] = N;
  if(flag){
    REP(i,'z'-'a'+1){
      auto itr = upper_bound(ALL(D[i]), pos);
      if(itr==D[i].end()){
        dp[pos] = 1;
      }else{
        ll next_pos = *itr;
        chmin(dp[pos], dp_init(next_pos, flag)+1);
      }
    }
  }else{
    REP(i,'z'-'a'+1){
      auto itr = lower_bound(ALL(D[i]), pos);
      if(itr==D[i].begin()){
        dp[pos] = 1;
      }else{
        ll next_pos = *(itr-1);
        chmin(dp[pos], dp_init(next_pos, flag)+1);
      }
    }
  }
  return dp[pos];
}

string solve(string A, bool flag){
  REP(i,'z'-'a'+1) D[i].resize(0);
  REP(i,N) D[A[i]-'a'].pb(i);
  REP(i,N) dp[i] = -1;

  //mat_print(D);

  REP(i,N) dp_init(i, flag);

  debug_print(A);
  //vec_print(dp);

  string ans = "";
  if(flag){
    ll pos = -1;
    while(pos<N){
      ll min_val = N;
      REP(i,'z'-'a'+1){
        auto itr = upper_bound(ALL(D[i]), pos);
        if(itr==D[i].end()){
          return ans;
        }else{
          ll next_pos = *itr;
          chmin(min_val, dp_init(next_pos, flag));
        }
      }
      REP(i,'z'-'a'+1){
        ll next_pos = *upper_bound(ALL(D[i]), pos);
        if(dp_init(next_pos, flag)==min_val){
          ans += i+'a';
          pos = next_pos;
          break;
        }
      }
    }
  }else{
    ll pos = N;
    while(pos>=0){
      ll min_val = N;
      REP(i,'z'-'a'+1){
        auto itr = lower_bound(ALL(D[i]), pos);
        if(itr == D[i].begin()){
          reverse(ALL(ans));
          return ans;
        }else{
          ll next_pos = *(itr-1);
          chmin(min_val, dp_init(next_pos, flag));
        }
      }
      REP(i,'z'-'a'+1){
        ll next_pos = *(lower_bound(ALL(D[i]), pos)-1);
        if(dp_init(next_pos, flag)==min_val){
          ans += i+'a';
          pos = next_pos;
          break;
        }
      }
    }
  }
  return ans;
}

