using pll = pair<int, int>;

vector<pll> memo;

// i以降の文字列について, 最良の残りstepと選んだ文字
pll f(int i) {
	// 範囲外なのでaでOK
	if(i>=N) return MP(1, 0);

	if(memo[i].first!=-1) return memo[i];

	auto lans = MP(1<<30, 0);
	REP(j, CS) {
		int p = pos(i, j);
		int l = 1;
		// p==-1のときは以降ないのでjでいい
		if(p!=-1) l = 1 + f(p+1).first;
		if(l < lans.first) lans = MP(l, j);
	}
	return memo[i] = lans;
}

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	while(cin>>s) {
		N = s.size();
		memo = vector<pll>(N, MP(-1, 0));
		nxt = VVI(CS, VI(N+1, -1));
		for(int i=N-1;i>=0;i--) {
			REP(j, CS) if(s[i]-'a'==j) nxt[j][i] = i; else if(i+1<N) nxt[j][i] = nxt[j][i+1];
		}
		auto vv = f(0);
