    vector<int> t(n);
    REP(i, n) t[i] = s[i] - 'a';

    constexpr ll w = 'z' - 'a' + 1;
    vector<vector<ll>> g(w);
    REP(i, n) g[t[i]].push_back(i);

    vector<ll> from(n, -2);
    deque<ll> q = {-1};
    ll i;
    ll suffix;
    while (q.size()) {
        i = q.front(); q.pop_front();
        bool done = false;
        REP(j, w) {
            ll k = upper_bound(ALLOF(g[j]), i) - g[j].begin();
            if (k != g[j].size()) {
                k = g[j][k];
                if (from[k] == -2) {
                    from[k] = i;
                    q.push_back(k);
                }
            } else {
                done = true;
                suffix = j;
                break;
            }
        }
        if (done) break;
        // REP(j, q.size()) cerr << q[j] << " \n"[j==q.size()-1];
    }

    vector<ll> ans = {suffix};
    for (; i >= 0; i = from[i]) {
        ans.push_back(t[i]);
    }
    reverse(ALLOF(ans));

    string anss(ans.size(), ' ');
    REP(i, ans.size()) anss[i] = 'a' + ans[i];
    say(anss);

}

