const int MAX_N = 200050;
std::string A;
int memo[MAX_N];

int cal_length_from(const int begin) {
    if (memo[begin] != -1) {
        return memo[begin];
    }

    bool array[26] = {};
    int ret = 1;
    int num = 0;
    for (int i = begin; i < A.size(); i++) {
        if (!array[A[i] - 'a']) {
            array[A[i] - 'a'] = true;
            num++;
            if (num == 26) {
                ret += cal_length_from(i + 1);
                break;
            }
        }
    }
    memo[begin] = ret;
    return ret;
}

int main(int argc, char **argv) {
