void addedge(int st, int ed, int co, char c) {
    edge e;
    e.to = ed;
    e.cost = co;
    e.alph = c;
    G[st].push_back(e);
}

void BFS(int n) {
    fill(d, d + V, llmax);
    queue<int> que;
    d[n] = 0;
    str[n] = "";
    que.push(n);
    while (que.size() > 0) {
        int base = que.front();
        que.pop();
        int s = G[base].size();
        for (int i = 0; i < s; i++) {
            int to = G[base][i].to;
            char c = G[base][i].alph;
            if (d[to] == llmax) {
                d[to] = d[base] + 1;
                str[to] = str[base] + c;
                que.push(to);
            } else if (d[to] == d[base] + 1) {
                if (str[base] + c < str[to]) {
                    str[to] = str[base] + c;
                }
            }
        }
    }
}

