const int INF = (1LL<<30);
const double DINF = std::numeric_limits<double>::infinity();
const int MOD = 1000000007;
#define MAX_N 200100

string A;
// A2 の位置 i から右のアルファベット j がある位置
// ない場合は -1
int next_pos[MAX_N][26];
int dp[MAX_N] = {};  // i 番目の文字以降でできる文字列の部分文字列でないもので、最短のもの

signed main()
{
    cin >> A;
    A = 'x' + A;   // てきとうな文字

    // next_pos の作成
    int tail = A.size()-1;
    int find_alph = A[tail] - 'a';
    REP(i, 26) {
        next_pos[tail][i] = -1;
    }
    for(int i = A.size()-2; i >= 0; --i) {
        REP(j, 26) { next_pos[i][j] = next_pos[i+1][j]; }
        next_pos[i][find_alph] = i+1;
        find_alph = A[i] - 'a';
    }

    // dp の作成
    dp[A.size()-1] = 1;
    for(int i = A.size()-2; i >= 0; --i) {
        dp[i] = INF;
        for(int j = 0; j < 26; ++j) {
            int next_ind = next_pos[i][j];
            if(next_ind < 0) {
                dp[i] = 1;
                break;
            } else {
                dp[i] = min(dp[i], dp[next_ind] + 1);
            }
        }
    }

    string ans = "";

    // 前方から貪欲にたどっていく
    {
        int i = 0;
        while(i < A.size()) {
            vector<char> cand;  // 最短の文字列の i 文字目の候補
            REP(j, 26) {
                int next_ind = next_pos[i][j];
                if(next_ind < 0) {
                    assert(dp[i] == 1);
                    cand.push_back(static_cast<char>(j + 'a'));
                } else {
                    if(dp[next_ind] == dp[i] - 1) {
                        cand.push_back(static_cast<char>(j + 'a'));
                    }
                }
            }
            // 候補の中で辞書順最小を採用
            SORT(cand);
            assert(cand.size() > 0);
            ans += cand[0];
            {
                int next_ind = next_pos[i][cand[0] - 'a'];
                if(next_ind < 0) { break; }
                i = next_ind;
            }
        }
    }
    printf("%s\n", ans.c_str());

    return 0;
}

