V<V<int>> id(const string &s){
    int n=s.size();
    V<V<int>> num(n+1,V<int>(26,n));
    for(int i=n-1;i>=0;i--){
        for(int j=0;j<26;j++)num[i][j]=num[i+1][j];
        num[i][int(s[i]-'a')]=i;
    }
    return num;
}
int main(){
    string s;
    cin>>s;
    int n=s.size();
    V<V<int>> num=id(s);
    V<int> dp(n+1,int(1e7));
    V<char> res(n+1,'a');
    dp[n]=1;
    for(int i=n-1;i>=0;i--){
        for(int j=0;j<26;j++){
            if(num[i][j]==n){
                if(dp[i]>1){
                    dp[i]=1;
                    res[i]=char(j+'a');
                }
            }else{
                if(chmin(dp[i],dp[num[i][j]+1]+1)){
                    res[i]=char(j+'a');
                }
            }
        }
    }
    string ans={};
    int ind=0;
    while(ind<=n){
        ans.push_back(res[ind]);
        ind=num[ind][res[ind]-'a']+1;
    }
    cout<<ans<<"\n";
}

