		x=ans[i]-'a';
		int k=lower_bound(c[x]+fin[x][i],c[x]+fin[x][i+1],c[x][fin[x][i+1]-1])-c[x];
		for(int j=0;j<26;++j) if(k<fin[j][i]&&fin[j][i]<=fin[x][i+1]){
			ans[i-1]='a'+j;
			break;
		}
	}
	reverse(ans.begin(),ans.end());
	cout<<ans<<endl;
}

