string solve(){
    string res = "";
    string A; cin >> A;
    vector<int> f(26,0);
    vector<int> nextC(A.length()+1,0);
    for(int i = (int)A.length()-1; i >= 0; i--){
        int cnt = 0;
        f[A[i]-'a'] = true;
        nextC[i] = nextC[i+1];
        for(int j = 0; j < 26;j++){
            if(f[j]) cnt++;
            else break;
