        if(cnt == 26) for(int j = 0; j < 26;j++) f[j] = false;
        nextC[i] = cnt%26;
    }
    for(int i = 0; i < A.length(); i++){
        char c = nextC[i] + 'a';
        res += c;
        while(i < A.length() && A[i] != c) i++;
    }
    return res;
}
