int solve(int idx){

  if(idx == n + 1)return dp[idx] = 0;

  int &ret = dp[idx];

  if(~ret)return ret;

  ret = INT_MAX;

  for(int j = 0; j < 26; j++)
    ret = min(ret, 1 + solve(nxt[idx][j]));


  return ret;
}

