vector<vector<int> > calcNext(const string &S) {
    int n = (int)S.size();
    vector<vector<int> > res(n+1, vector<int>(26, n));
    for (int i = n-1; i >= 0; --i) {
        for (int j = 0; j < 26; ++j) res[i][j] = res[i+1][j];
        res[i][S[i]-'a'] = i;
    }
    return res;
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    string S;
    cin >> S;
    int n = (int)S.size();

    auto next = calcNext(S);

    vector<int> dp(n+1, 1<<29);
    vector<pair<char,int>> recon(n+1, {'?',n});
    dp[n] = 1;
    for(int i=n-1;i>=0;i--){
        for(int j=0;j<26;j++){
            if(next[i][j] == n){
                if(dp[i] > 1) dp[i] = 1, recon[i] = {'a'+j, n};
            }
            else if(chmin(dp[i],dp[next[i][j] + 1] + 1)) recon[i] = {'a' + j, next[i][j] + 1};
        }
    }
    string ans = "";
    int idx = 0;
    while(idx < n){
        auto p = recon[idx];
        ans += p.first;
        idx = p.second;
    }
    cout << ans << endl;
}

