inline bool ok(int l,int r)
{
	for(register int i=0;i<26;i++)
	{
		if (cnt[i][r]-cnt[i][l-1]<1) return false;
	}
	return true;
}

int getLen(int l,int r)
{
	int res=0;
	for(int d=maxd-1;d>=0;d--)
	{
		if (ff[d][l]<=n) res+=(1<<d),l=ff[d][l]+1;
	}
	return res;
}

