void precalc() {
  int sz = SIZE(s), cur[ A ];
  memset( cur, -1, sizeof(cur) );
  for( int i = sz-1; i >= 0; --i ) {
    for( int j = 0; j < A; ++j ) {
      nxt[ j ][ i ] = cur[ j ];
    }
    cur[ s[i]-'a' ] = i;
  }
}

void solve() {
  int sz = SIZE(s);
  for( int i = sz-1; i >= 0; --i ) {
    dp[ i ] = oo;
    for( int j = 0; j < A; ++j ) {
      if( s[i] == 'a'+j ) dp[ i ] = min( dp[i], 1+dp[i+1] );
      else if( nxt[ j ][ i ] == -1 ) dp[ i ] = 1;
      else dp[ i ] = min( dp[i], 1+dp[ nxt[ j ][ i ] ] );
    }
  }
}

void get_ans( int idx ) {
  for( int i = 0; i < A; ++i ) {
    if( s[idx] == 'a'+i ) {
      if( dp[idx] == 1+dp[idx+1] ) {
        ans.PB( 'a'+i );
        return get_ans( idx+1 );
      }
    }
    if( nxt[ i ][ idx ] == -1 ) {
      ans.PB( 'a'+i );
      return;
    }
    if( dp[ idx ] == dp[ nxt[ i ][ idx ] ]+1 ) {
      ans.PB( 'a'+i );
      return get_ans( nxt[ i ][ idx ]+1 );
    }
  }
}

