class Solver {
  public:
    bool solve() {
        const int NA = 'z' - 'a' + 1;
        string A; cin >> A;
        int N = A.size();
        rep(i, A.size()) A[i] -= 'a';
        int rec = 0;
        int cnt = 0;
        vector<int> contain(NA);
        vector<int> split;

        split.push_back(N - 1);
        for(int i = N - 1; i >= 0; i--) {
            char a = A[i];
            if(not contain[a]) {
                contain[a]++;
                cnt++;
                if(cnt == NA) {
                    fill(all(contain), 0);
                    rec++;
                    cnt = 0;
                    if(i > 0) split.push_back(i - 1);
                }
            }
        }
        string ans;
        if(cnt > 0) split.pop_back();       
        rep(i, NA) {
            if(not contain[i]) {
                ans.push_back('a' + i);
                break;
            }
        }        
        reverse(all(split));        
        rep(i, rec) {
            vector<int> c(NA), c_backup;
            int cnt = 0;
            int j;
            for(j = split[i]; cnt < NA; j--) {
                cnt += c[A[j]] == 0;                
                if(A[j] + 'a' == ans.back()) c_backup = c;
                c[A[j]] = 1;
            }
            c = c_backup;
            // if(cnt < NA - 1) c[A[j]] = 1;
            rep(k, NA) {
                if(not c[k]) {
                    ans.push_back(k + 'a');
                    break;
                }
            }            
        }
        cout << ans << endl;
        return 0;
    }
};

