int rui[200200][26];

void solve(){
  ins(S);
  int N = sz(S);
  vi dp(N + 1);

  vi cnt(26 , 0);
  repr(i , N){
    dp[i] = dp[i + 1];
    cnt[S[i] - 'a']++;
    int flg=1;each(x,cnt)if(x==0)flg=0;
    if(flg){
      dp[i]++;
      fill(all(cnt),0);
    } 
  }

  rep(i , N) rep(j , 26){
    rui[i + 1][j] = rui[i][j] + (S[i] == j + 'a');
  }

  // n文字目以降でjが出現するもの
  auto f = [&](int n,int j) -> int{
    if(rui[N][j] == rui[n][j]) return -1;
    int ok = n , ng = N;
    while(ok + 1 < ng){
      int med = (ok + ng) / 2;
      (rui[med][j] > rui[n][j] ? ng : ok) = med;
    }
    return ok;
  };

  // 答えはdp[0] + 1文字
  // i文字目から決めていく
  string ans;
  int idx = 0;
  rep(i , dp[0] + 1){
    trc(i , idx);
    // i文字目にjを置けるか？
    // 置ける <-> dp[置く場所]が残り文字数未満
    rep(j , 26){
      int nxt = f(idx , j);
      trc(idx , j , nxt);
      if(nxt == -1){
        ans.push_back('a' + j);
        idx = N;
        break;
      }
      // 残り nxt + 1
      // 残り文字... dp[0] - i
      if(dp[nxt + 1] >= dp[0] - i) continue;
      ans.pb('a' + j);
      idx = nxt + 1;
      break;
    }
    if((int)ans.size() == i) exit(1);
  }
  out(ans);


  //trc(dp);

}

