string A;
vector<vector<int>> nextCharPos;
vector<int> searchLimit;

void calcNextCharPos(string& s)
{
	int len = s.length();
	nextCharPos.resize(len + 1);
	FOR(i, len + 1) {
		nextCharPos[i].resize(26);
	}

	FOR(i, 26) {
		nextCharPos[len][i] = -1;
	}

	for (int i = len - 1; i >= 0; i--) {
		FOR(j, 26) {
			nextCharPos[i][j] = nextCharPos[i + 1][j];
		}
		nextCharPos[i][s[i] - 'a'] = i;
	}
}

bool azTest(int depth, int depthObj, int pos, string* ans)
{
	if (depth < depthObj - 1) {
		if (searchLimit[depthObj - depth - 1] < pos) {
			FOR(i, 26) {
				int newPos = nextCharPos[pos][i];
				if (azTest(depth + 1, depthObj, newPos + 1, ans)) {
					*ans = (char)('a' + i) + *ans;
					return true;
				}
			}
			searchLimit[depthObj - depth - 1] = pos;
		}
	}
	else {
		if (searchLimit[0] < pos) {
			int tMin = 200001;
			FOR(i, 26) {
				int nextPos = nextCharPos[pos][i];
				if (nextPos == -1) {
					*ans = (char)('a' + i);
					return true;
				}
				else {
					tMin =  min(tMin, nextPos);
				}
			}
			searchLimit[0] = tMin;
		}
	}
	return false;
}

int main()
{
	cin.tie(nullptr);
	ios::sync_with_stdio(false);

	cin >> A;
	calcNextCharPos(A);

	int i = 1;
	string ans = "";
	while (1) {
		searchLimit.push_back(-1);
		if (azTest(0, i, 0, &ans)) {
			break;
		}
		i++;
	}

	cout << ans << ENDL;

	return 0;
}

