                }else continue;
            }

            cnt++;
            now=next[now][j];

            while(1){
                int maxi=-1;
                bool app=false;
                for(int i=0;i<26;i++){
                    maxi=max(maxi,next[now][i]);
                    if(next[now][i]==-1) app=true;
                }
                if(app) break;
                cnt++;
                if(cnt==length){
                    ok=false;
                    now=was;
                    break;
                }
                now=maxi;
            }
            if(ok){
                T+=('a'+j);
                break;
            }
        }
    }

    cout<<T<<endl;
}

