void _main()
{
    string s; CIN(s);
    ll n = s.size();

    s += "abcdefghijklmnopqrstuvwxyz";
    ll slen = s.size();

    S V<ll> idxlist[256];
    rep (idx, slen) idxlist[s[idx]].pb(idx);

    S ll idxidxs[256];
    memset(idxidxs, 0, sizeof(idxidxs));
    S V<ll> linklist[200100];
    rep (i, slen) {
        idxidxs[s[i]]++;
        srep (c, 'a', 'z'+1) {
            if (idxidxs[c] >= idxlist[c].size()) continue;
            linklist[i].pb(idxlist[c][idxidxs[c]]);
        }
    }

    S ll reverse_idx[200100];
    S queue<t2> q;
    S bool checked[200100];
    memset(checked, 0,sizeof(checked));
    ll lastidx = -1LL;

    srep (c, 'a', 'z'+1) q.push(t2(idxlist[c][0], -1LL));

    while (!q.empty()) {
        auto item = q.front(); q.pop();
        ll idx = get<0>(item);
        ll previdx = get<1>(item);

        if (checked[idx]) continue;
        checked[idx] = true;
        reverse_idx[idx] = previdx;

        if (idx >= n) {
            lastidx = previdx;
            break;
        }

        for (auto nidx : linklist[idx]) q.push(t2(nidx, idx));
    }

    S bool disable[256];
    memset(disable, 0, sizeof(disable));
    rrep (idx, n) {
        if (idx == lastidx) break;
        disable[s[idx]] = true;
    }

    string ans;
    srep (c, 'a', 'z'+1) {
        if (!disable[c]) {
            ans = (char)c + ans;
            break;
        }
    }

    ll nowidx = lastidx;
    while (nowidx >= 0LL) {
        ans = s[nowidx] + ans;
        nowidx = reverse_idx[nowidx];
    }

    cout << ans << endl;
}

