void solution() {
	string s; cin >> s;
	int n = sz(s);

	// (1) of editorial
	vector<vector<int>> next(n+1, vector<int>(26, n));
	for (int i = n-1; i >= 0; --i) {
		for (char c = 'a'; c <= 'z'; ++c) {
			next[i][c-'a'] = next[i+1][c-'a'];
		}
		next[i][s[i]-'a'] = i;
	}

	// (2) of editorial
	vector<int> dp(n+1, N);
	dp[n] = 1;
	for (int i = n-1; i >= 0; --i) {
		for (char c = 'a'; c <= 'z'; ++c) {
			if (next[i][c-'a'] >= n)
				dp[i] = 1;
			else
				dp[i] = min(dp[i], dp[next[i][c-'a']+1]+1);
		}
	}

	// tracing
	int idx = 0;
	while (dp[idx] > 1) {
		for (char c = 'a'; c <= 'z'; ++c) {
			if (dp[idx] == dp[next[idx][c-'a']+1]+1) {
