		for (j = 0; j<26; j++)
		{
			int id = x[i + 1][j];
			if (id <= len)
			{
				if (dp[id] < dp[i])
					dp[i] = dp[id], y[i] = j;
			}
			else {
				dp[i] = -1;
				y[i] = j;
