			cur = memo[pos];
		}
		if(cur == "-"){
			pos++;
			continue;
		}

		for(int i = 0; i <= 'z' - 'a'; i++){
			if(posarr[i].size() > 0 && posarr[i][0] == pos){
				posarr[i].pop_front();
			}
			if(posarr[i].size() == 0){
				if(ans == "-"){
					ans = cur + char(i + 'a');
				}else if(ans.size() > cur.size() + 1){
					ans = cur + char(i + 'a');
				}else if(ans.size() == cur.size() + 1 && ans > (cur + char(i + 'a'))){
					ans = cur + char(i + 'a');
				}
				break;
				//return 0;
			}
			long long nextpos = posarr[i][0];
			string nstr = cur;
			nstr += ('a' + i);
			if(memo[nextpos] == "-"){
				memo[nextpos] = nstr;
			}else{
				if(memo[nextpos].size() > nstr.size()){
					memo[nextpos] = nstr;
				}else if(memo[nextpos].size() == nstr.size() && memo[nextpos] > nstr){
					memo[nextpos] = nstr;
				}
			}
		}
		pos++;
	}
	cout << ans << endl;
}

