int main () {
  cin >> A;
  N = A.size();
  vector<int> V;
  V.push_back(N);
  int size = 0;
  bool used[26];
  clear(used);
  for (auto i = N-1; i >= 0; --i) {
    if (!used[A[i] - 'a']) {
      ++size;
      used[A[i] - 'a'] = true;
    }
    if (size == 26) {
      size = 0;
      clear(used);
      V.push_back(i);
    }
  }
  V.push_back(0);
  reverse(V.begin(), V.end());
  vector<string> W;
  for (auto i = 0; i < (int)V.size()-1; ++i) {
    W.push_back(A.substr(V[i], V[i+1] - V[i]));
  }
  vector<int> ans;
  clear(used);
  for (auto x : W[0]) {
    used[x - 'a'] = true;
  }
  ans.push_back(first(used));
  for (auto i = 1; i < (int)W.size(); ++i) {
    string str = W[i];
    char c = 'a' + ans[i-1];    
    int found = infty;
    for (auto j = 0; j < (int)str.size(); ++j) {
      if (str[j] == c) {
        found = j;
        break;
      }
    }
    assert(found < infty);
    clear(used);
    for (auto j = found+1; j < (int)str.size(); ++j) {
      used[str[j] - 'a'] = true;
    }
    ans.push_back(first(used));
  }
  string ret = "";
  for (auto x : ans) {
    string t{(char)('a' + x)};
    ret = ret + t;
  }
  cout << ret << endl;
}

