int calc(vector<int> pref) {
    int j = 0;
    int res = 0;
    for (int i = 0; i < pref.size(); i++) {
        j = a[j][pref[i]];
        if (j == n) {
            return i + 1;
        }
        j++;
        res++;
    }

    while (j <= n) {
//        cout << j << "\n";
        int max = 0;
        for (int i = 0; i < 26; i++) {
            max = std::max(max, a[j][i]);
        }
        j = max + 1;
        res++;
    }
    return res;
}

