const int MAX = 2e5 + 10;
const int INF = 0x7fff7c7c;

string s;
int n, nxt[MAX][26], dp[MAX];

void build() {
	cin >> s;
	n = (int)s.length();

	for (int i = 0; i <= n; ++i)
		fill(nxt[i], nxt[i] + 26, n);
	fill(dp, dp + n + 1, INF);

	for (int i = n - 1; i >= 0; --i) {
		for (int j = 0; j < 26; ++j)
			nxt[i][j] = nxt[i + 1][j];
		nxt[i][s[i] - 'a'] = i;
	}
}

void solve() {
	vector<pair<char, int>> v(n + 1, { '?', n });

	dp[n] = 1;
	for (int i = n - 1; i >= 0; --i) {
		for (int j = 0; j < 26; ++j) {
			if (nxt[i][j] == n) {
				if (dp[i] > 1) dp[i] = 1, v[i] = { 'a' + j, n };
			}
			else if (dp[i] > dp[nxt[i][j] + 1] + 1) {
				dp[i] = dp[nxt[i][j] + 1] + 1;
				v[i] = { 'a' + j, nxt[i][j] + 1 };
			}
		}
	}

	string ans = "";
	int i = 0;
	while (i < n) {
		auto j = v[i];
		ans += j.first;
		i = j.second;
	}

	cout << ans;
}

int main() {
	cin.sync_with_stdio(0);
