	// 実装しやすい代わりに1だけズレるので注意（例えばn-1文字目は全部nxt=-1のはず）
	rrep(i, n) {
		nxt[i][a[i] - 'a'] = i;
		rep(j, 26) {
			if (j == a[i] - 'a')	nxt[i][j] = i;
			else	nxt[i][j] = nxt[i + 1][j];
		}
	}

	// DPで構築できる最小文字数の算出(a[i:]で構築できる最小文字数を記録)
	// 初期化(でかけりゃ何でもいいんです）。dp[n]=0に注意
	rep(i, n)	dp[i] = mod;
	rrep(i, n) {
		rep(j, 26)	dp[i] = min(dp[i], dp[nxt[i + 1][j]] + 1);
	}

	// 完成したDPテーブルを元に文字列の構築（復元です）
	string ret = "a";
	// aの何文字目を見ているか
	int pos = nxt[0][0];
	rep(i, 26) {
		if (dp[pos] > dp[nxt[0][i]]) {
			ret = 'a' + i;
			pos = nxt[0][i];
		}
	}
	while (pos < n) {
		// 辞書順最小なので、先に見つけたもの勝ち
		rep(i, 26) {
			if (dp[pos] == dp[nxt[pos + 1][i]] + 1) {
				ret += 'a' + i;
				pos = nxt[pos + 1][i];
				break;
			}
		}
	}
	cout << ret << endl;
	return 0;
}

