// ---------------------- template ----------------------

void solve() {
	string S; cin >> S;
	vector<int> A(S.size());
	for (int i = 0; i < S.size(); ++i) {
		A[i] = S[i] - 'a';
	}
	vector<bool> check('z' - 'a'+1);
	vector<vector<int> > G(A.size());
	vector<int> memo(check.size(), -1);

	RREP(i, A.size()) {
		REP(j, check.size()) {
			if (memo[j] == -1) {
				G[i].push_back(-j-1);
				break;
			}
		}
		if (G[i].size() == 0) {
			G[i].resize(memo.size());
			copy(ALL(memo), G[i].begin());
		}
		memo[A[i]] = i;
	}

	vector<bool> visited(A.size());
	queue<int> que;
	for (int i = 0; i < memo.size(); ++i) {
		if (memo[i] == -1) {
			cout << char(i + 'a') << endl;
			return;
		}
		que.push(memo[i]);
		visited[memo[i]] = true;
	}

	vector<int> rev(A.size(), -1);
	int last = -1;
	string res;
	while (not que.empty()) {
		int node = que.front(); que.pop();
		if (G[node].back() < 0) {
			res.push_back(-G[node].back()-1 + 'a');
			last = node;
			break;
		}
		for (auto &to : G[node]) if(not visited[to]) {
			que.push(to);
			visited[to] = true;
			rev[to] = node;
		}
	}
	while (true) {
		if (last == -1) break;
		res.push_back(S[last]);
		last = rev[last];
	}
	reverse(ALL(res));
	cout << res << endl;
}

