constexpr int NChar = 'z'-'a'+1;
struct Ent {
	int		jump[NChar];
};
constexpr int MaxLen = 200000 + 1;
Ent	Entry[MaxLen];
int Came[MaxLen];
int IdHist[MaxLen];

#include <cstring>
int main() {
	DisableIOSync();

	std::string str;
	std::getline(std::cin, str);
	std::memset(Came, 0xff, sizeof(Came));

	const int Len = str.length();
	int prev[NChar];
	for(auto& p : prev)
		p = Len;
	ForGE(i, Len-1, 0) {
		const auto c = str[i];
		const int id = c - 'a';

		auto& ent = Entry[i];
		For(j, 0, NChar) {
			ent.jump[j] = prev[j] - i;
		}
		prev[id] = i;
	}
	std::vector<int> cand[2];
	For(i, 0, NChar) {
		if(prev[i] == Len) {
			IdHist[Len] = i;
			Came[Len] = -100;
			goto END;
		}
		cand[0].push_back(prev[i]);
		Came[prev[i]] = -100;
		IdHist[prev[i]] = i;
	}
	for(;;) {
		cand[1].clear();
		for(auto& c : cand[0]) {
			auto& ent = Entry[c];
			For(i, 0, NChar) {
				const int next = c + ent.jump[i];
				if(next == Len) {
					Came[next] = c;
					IdHist[next] = i;
					goto END;
				} else {
					if(Came[next] == -1) {
						cand[1].push_back(next);
						Came[next] = c;
						IdHist[next] = i;
					}
				}
			}
		}
		std::swap(cand[0], cand[1]);
	}
	END:
	std::string hist;
	int cur = Len;
	for(;;) {
		hist.push_back(IdHist[cur] + 'a');
		cur = Came[cur];
		if(cur == -100)
			break;
	}
	std::reverse(hist.begin(), hist.end());

	return 0;
}

