int next_[MAX_N][26];
int dp[MAX_N];

int main() {
    string s;
    cin >> s;
    fill_n(next_[sz(s)], 26, -1);
    rrep(i, sz(s)) {
        dp[i] = INT_MAX;
        rep(j, 26) { next_[i][j] = next_[i + 1][j]; }
        next_[i][s[i] - 'a'] = i;
    }

    rrep(i, sz(s)) {
        rep(j, 26) {
            auto ic = next_[i][j];
            if (ic == -1) {
                dp[i] = 1;
                break;
            } else if (ic + 1 >= sz(s)) {
                dp[i] = min(dp[i], 2);
            } else dp[i] = min(dp[i], dp[ic + 1] + 1);
        }
    }

    string res;
    int i = 0;
    bool end = false;
    while (!end) {
        rep(j, 26) {
            auto ic = next_[i][j];
            if (ic == -1 && dp[i] == 1) {
                res += 'a' + j;
                end = true;
                break;
            } else if (ic + 1 >= sz(s) && dp[i] == 2) {
                res += 'a' + j;
                res += 'a';
                end = true;
                break;
            } else if (dp[i] == dp[ic + 1] + 1){
                res += 'a' + j;
                i = ic + 1;
                break;
            }
        }
    }
    cout << res << endl;
    return 0;
}

