  vector<vector<ll>> next(n + 1, vector<ll>(26, -1));
  for (ll i = n - 1; i >= 0; i--) {
    rep(j, 0, 26) {
      next[i][j] = a[i] == j ? i + 1 : next[i + 1][j];
    }
