        //cout << res << " " << pos << endl;
        for (int i = 0; i < 26; i++){
            k = (st[i].upper_bound(pos) != st[i].end() ? (*st[i].upper_bound(pos)):s.size());
            if (k > mx){
                mx = k;
            }

        }
        pos = mx;
        res++;
    }
    return res;
}

