                c = 'a' + i;
                pos = N;
                break;
            }

            int ne = lower_bound(v.begin(), v.end(), std::make_tuple(i, pos)) - v.begin();
            ne = snd(v[ne]) + 1;

            if(len[pos] == len[ne] + 1){
                c = 'a' + i;
                pos = ne;
                break;
            }
        }

        std::cout << c << std::endl;
