string A;
ll N;
vvll D('z'-'a'+1);
string NO = "";

ll min_length(ll pos){
  if(pos==N) return 0;
  ll target = pos;
  REP(i,'z'-'a'+1){
    chmax(target, *upper_bound(ALL(D[i]), pos));
  }
  return min_length(target)+1;
}

string search(ll pos, ll length){
  string ans = "";
  if(pos==N) return ans;
  if(length<=0) return NO;
  REP(i,'z'-'a'+1){
    ll next_pos = *upper_bound(ALL(D[i]), pos);
    string tmp = "";
    tmp += (char)(i+'a');
    tmp += search(next_pos, length-1);
    if(ans.size()==0) ans = tmp;
    if(ans.size()>tmp.size()) ans = tmp;
    chmin(ans, tmp);
  }
  return ans;
}

