    vector<vector<int>> nex(N+1, vector<int>(26,N));
    for (int i = N-1; i >= 0; i--) {
        rep(j,26) nex[i][j] = nex[i+1][j];
        nex[i][S[i]-'a'] = i;
    }
    //1-index
    vector<vector<int>> dp(N+2, vector<int>(26,1e9));
