        int m = 1e9;
        rep(j,26) chmin(m,dp[i][j]);
        rep(j,26) chmin(dp[nex[i][j]+1][j],m+1);
    }
    for (int i = N+1; i > 0; i--) {
        rep(j,26) chmin(dp[i-1][j],dp[i][j]);
    }
    int cur = N+1;
