    vector<int> dfs(int d,int pos ,vector<vector<int>> &nxt,vector<int>& can){
        DBG(d,pos)
        if(d==1){
            if(can[pos]==0)return {-1};
            for(int i=0; i<26; ++i){
                if(nxt[pos][i]==0)return {i};
            }
        }
        for(int i=0; i<26; ++i){
            if(nxt[pos][i]>0 and can[nxt[pos][i]]==1){
                auto tmp =dfs(d-1,nxt[pos][i],nxt,can);
                if(tmp[0]>-1){
                    tmp.push_back(i);
                    return tmp;
                }
            }
        }
        return {-1};
    }
