            for(int j=0; j<26; ++j){
                if(nxt[i][j]>-1){
                    tr=true;
                    break;
                }
            }
            if(!tr){
                can[i]=0;
                for(int j = i-1; j>0; --j){
                    nxt[j][s[i]-'a']=-2;
                    if(s[i]==s[j])break;
                }
            }

        }
        ans.resize(anslen);
        auto a = dfs(anslen,0,nxt,can);
        for(int i=(int)a.size()-1; i>=0; --i){
            cout << (char)('a'+a[i]);
        }
        cout << "\n";
    }
};

