	int best_size = INT_MAX;
	// cout<<"exploring "<<index<<" "<<s[index]<<endl;
	for (char ch = 'a'; ch <= 'z'; ++ch)
	{
		vector<int>::iterator next = upper_bound(indices[ch].begin(), indices[ch].end(), index);
		if(next == indices[ch].end()){
			bestchar[index] = -ch;
			return 1;
		}
	}
	for (char ch = 'a'; ch <= 'z'; ++ch)
	{
		vector<int>::iterator next = upper_bound(indices[ch].begin(), indices[ch].end(), index);
		if(next == indices[ch].end()){
			// bestchar[index] = -1;
			bestchar[index] = -ch;
			return 1;
		}
		// cout<<"going in "<<*next<<" "<<s[*next]<<endl;
		int curr_size = dp(*next) + 1;
		if(curr_size < best_size)
			bestchar[index] = *next;
		best_size = min(best_size, curr_size);
	}
	mymap[index] = best_size;
	return best_size;
}
