using namespace std;

int n,dp[N],st[30][N*4];
char s[N];

int get(int node,int bas,int son,int x,int y,int c) {

  if(x>y) return n+1;
  if(bas>y || son<x) return n+1;
  if(bas>=x && son<=y) return st[c][node];
  int orta=(bas+son)/2;
  return min(get(node*2,bas,orta,x,y,c),get(node*2+1,orta+1,son,x,y,c));

}

void build(int node,int bas,int son,int c) {

  if(bas==son) {
    if(s[bas]=='a'+c) {
      st[c][node]=bas;
    }
    else {
      st[c][node]=n+1;
    }
    return ;
  }
  int orta=(bas+son)/2;
  build(node*2,bas,orta,c);
  build(node*2+1,orta+1,son,c);
  st[c][node]=min(st[c][node*2],st[c][node*2+1]);

}

int dfs(int now) {

  int ret=inf;
  if(now>n) return dp[now]=0;
  if(~dp[now]) return dp[now];
  for(int i=0;i<26;i++) {
    int aft=get(1,1,n,now+1,n,i);
    ret=min(ret,dfs(aft)+1);
  }
  return dp[now]=ret;

}

int main() {

  memset(dp,-1,sizeof(dp));
  scanf("%s",s+1);
  n=strlen(s+1);
  for(int i=0;i<26;i++) {
