int main() {
  string s;
  cin >> s;
  int n = s.size();
  vector<vector<int>> next(26, vector<int>(n));
  vector<int> last_of(26, n);
  for (int i = n - 1; i >= 0; --i) {
    for (int j = 0; j < 26; ++j)
      next[j][i] = last_of[j];
    last_of[s[i] - 'a'] = i;
  }
  vector<int> dist(n + 1);
  vector<int> use_value(n);
  dist[n] = 0;
  for (int i = n - 1; i >= 0; --i) {
    dist[i] = n + 1;
    for (int j = 0; j < 26; ++j) {
      int res = 1 + dist[next[j][i]];
      if (res < dist[i]) {
        use_value[i] = j;
        dist[i] = res;
      }
    }
  }
  int result_size = n + 1;
  for (int j = 0; j < 26; ++j)
    result_size = min(result_size, 1 + dist[last_of[j]]);
  string result(result_size, ' ');
  for (int j = 0; j < 26; ++j)
    if (1 + dist[last_of[j]] == result_size) {
      int k = 0;
      result[k++] = 'a' + j;
      for (int i = last_of[j]; i < n;) {
        result[k++] = 'a' + use_value[i];
        i = next[use_value[i]][i];
      }
      break;
    }
  printf("%s\n", result.c_str());
  return 0;
}

