deque<char> ans;

int search(int n, vector<vector<int>> &next, string &s) {
    char c = 0;
    for (int cur = 0; cur <= n; ) {
        int maxi = cur;
        for (int i = 0; i < 26; i++) {
            if (next[cur][i] == -1 || next[cur][i] > n) {
                c = 'a' + i;
                maxi = -1;
                break;
            } else maxi = max(next[cur][i], maxi);
        }
        if (maxi == -1) break;
        cur = maxi;
    }
    ans.emplace_back(c);
    for (int i = n-1; i >= 0; i--) {
        if (s[i] == c) return i;
    }
    return -1;
}

