class NotSubsequence{
    vi dp;
    vector<char> to;
    vector<vi> next;
    string S;
    int N;
    void init(string &s){
        S = s;
        N = (int)s.size();
        dp = vi(N,-1);
        to.resize(N);
        next = vector<vi>(26,vi(N,N));
        for(int i=N-1;i>=0;--i) for(int j=0;j<26;++j){
            if(S[i] == char((int)'a' + j)) next[j][i] = i;
            else next[j][i] = (i<N-1? next[j][i+1]:N);
        }
        return;
    }

    int minLength(int i){
        if(i>=N) return 0;
        if(dp[i] >= 0) return dp[i];
        dp[i] = N+1;
        to[i] = 'z';
        for(int j=0;j<26;++j){
            int tmpl = 1 + minLength(next[j][i]+1);
            if(tmpl < dp[i]){
                dp[i] = tmpl;
                to[i] = (char)((int)'a' + j);
            }
        }
        return dp[i];
    }
public:
    string solution(string s){
        if(s.empty()) return "a";
        init(s);
        int L = minLength(0), j = 0;
        assert(L > 0);
        string ans;
        while(true){
            ans += to[j];
            j = next[(int)(to[j]-'a')][j]+1;
            if(j>=N) break;
        }
        return ans;
    }
};





int main(){
    string s;
    cin>>s;
    cout<<NotSubsequence().solution(s)<<endl;
    return 0;
}

