int n;

int rec(int i){
    if(i >= n) return 0;
    else if(i == n-1) return 1;
    int tmpdpi, tmp = INF, tmpi;
    char tmpc;
    for(char c='a'; c!='z'; c++){
        if(mp[i].find(c) == mp[i].end()){
            tmpi = n;
            tmpc = c;
            tmp = 0;
        }else{
            tmpdpi = mp[i][c] + 1;
            if(dp[tmpdpi] == -1) dp[tmpdpi] = rec(tmpdpi); 
            if(dp[tmpdpi] < tmp){
                tmpi = tmpdpi - 1;
                tmpc = c;
                tmp = dp[tmpdpi];
            }
        }
        if(tmp == 0) break;
    }
    dpi[i] = tmpi;
    dpc[i] = tmpc;
    return tmp+1;
}


