int DP(int x) {
   if(x > n) return 0;
   if(f[x] != -1) return f[x];
   int& res = f[x];
   res = 2 * n; int add;
   for(int i = 0; i < nAlpha; ++i) {
       if(nxt[x][i] > n) add = 0;
       else add = 1;
       if(res > DP(nxt[x][i] + 1) + add) {
          res = DP(nxt[x][i] + 1) + add;
          trace[x] = i;
       }
   }
   return res;
}

