  ioinit();
  string s;
  cin >> s;
  int n = s.size();
  auto next = calcNext(s);
  vi32 dp(n + 1, bit(30));
  dp[n] = 1;
  rrep(i, n) rep(j, 26) {
    if (next[i][j] == n) {
      dp[i] = 1;
    } else {
      amin(dp[i], dp[next[i][j] + 1] + 1);
    }
  }
  string ans = "";
  int i = 0;
  while (i < n) {
    rep(j, 26) {
      if (next[i][j] == n || dp[next[i][j] + 1] + 1 == dp[i]) {
        ans += 'a' + j;
        i = next[i][j] + 1;
        break;
      }
    }
  }
  cout << ans << '\n';
  return 0;
}

