const int maxn = int(2e5)+5, maxc = 27, inf = int(1e9)+5;

int n, memo[maxn], memoi[maxn];
set<int> S[maxc];

int DP(int idx)
{
	if(idx >= n) return 0;
	if(memo[idx] != -1) return memo[idx];
	int res = inf, resi = -1;
	for(int i = 0;i < 26;i++)
	{
		int c = DP(*S[i].upper_bound(idx));
		if(res > c)
		{
			res = c, resi = i;
		}
	}
	memoi[idx] = resi;
	return memo[idx] = res+1;
}

int main(void)
{
	string A;
	cin >> A;
	n = int(A.size());
	for(int i = 0;i < n;i++) S[int(A[i]-'a')].insert(i), memo[i] = -1;
	for(int i = 0;i < 27;i++) S[i].insert(n+1);

	int res = inf, resi = -1;
	for(int i = 0;i < 26;i++)
	{
		int c = DP(*S[i].begin());
		if(res > c)
		{
			res = c, resi = i;
		}
	}
	int cur = *S[resi].begin();
	while(cur < n)
	{
		cout << char(resi+'a');
		resi = memoi[cur];
		cur = *S[resi].upper_bound(cur);
	}
	cout << char(resi+'a');
	cout << "\n";
}

