const int N = 2e5 + 7;

#define pii pair<int,int>
#define fi first
#define se second

int n = 1, go[N + 7][26], dist[N + 7];

string s, ans;
vector<int> occ[26];

void dijkstra(int u){
	priority_queue<pii, vector<pii>, greater<pii>> pq;
	pq.push({0, u});
	dist[u] = 0;

	while(!pq.empty()){
		auto now = pq.top();
		pq.pop();

		if(dist[now.se] == now.fi){
			if(now.se == N) {
				dist[N] = min(dist[N], now.fi);
				continue;
			}
			for(int i = 0; i < 26; ++i){
				if(dist[go[now.se][i]] > dist[now.se] + 1){
					dist[go[now.se][i]] = dist[now.se] + 1;
					pq.push({dist[go[now.se][i]], go[now.se][i]});
				}
			}
		}
	}
}

void trace(int u, int d = 0){
	if(d == dist[N]){
		if(u == N) cout << ans, exit(0);
		else{
			ans.pop_back();
			return;
		}
	}
	for(int i = 0; i < 26; ++i){
		ans += char('a' + i);
		trace(go[u][i], d + 1);
	}
	ans.pop_back();
}

