  	for(int i = 0; i < (int)s.length(); ++i) occ[s[i] - 'a'].push_back(i + 1);

	for(int i = 0; i < N + 7; ++i) dist[i] = N;
	for(int i = 0; i < 26; ++i) occ[i].push_back(N);

	for(int i = 0; i <= n; ++i){
		for(int j = 0; j < 26; ++j){
			go[i][j] = *upper_bound(begin(occ[j]), end(occ[j]), i);
		}
	}

	dijkstra(0);
	trace(0);
}

