        rep(c,0,26) min_index[i][c]=min_index[i+1][c];
        min_index[i][A[i]-'a']=i;
    }

    static int memo[200001]={};
    static bool done[200001]={};

    function<int(int)> rec=[&](int index){
        int &res=memo[index];

        if(done[index]) return res;
        done[index]=true;

        if(index==A.size()) return res=1;

        int ma=0;
        rep(c,0,26) ma=max(ma,min_index[index][c]);
        if(ma==inf) return res=1;

        return res=rec(ma+1)+1;
    };

    function<void(int)> ans=[&](int index){
        int impossible_len=rec(index);

        if(impossible_len==1) rep(c,0,26) if(min_index[index][c]==inf){
            cout << char('a'+c) << endl;
            return;
        }

        rep(c,0,26){
            int index_=min_index[index][c]+1;
            if(rec(index_)==impossible_len-1){
                cout << char('a'+c);
                ans(index_);
                return;
            }
        }
    };

    ans(0);
}

int main(){
    std::cin.tie(0);
    std::ios::sync_with_stdio(false);
    cout.setf(ios::fixed);
    cout.precision(16);
    solve();
    return 0;
}

