            }
        }

        for(int j = 'a'; j <= 'z'; j++)
        {
            if(j == i)continue;
            check(i, j, now[j-'a'] + (it[j-'a'] == v[i-'a'].size()-2), ans, (it[j-'a'] == v[i-'a'].size()-2));
        }
    }

