deque<int> posarr[30];
string memo[200005];
string ans = "-";

int main(){
	cin >> S;
	for(long long i = 0; i < S.size(); i++){
		int idx = S[i] - 'a';
		posarr[idx].push_back(i);
		memo[i] = "-";
	}
	long long pos = -1;
	while(pos < (long long)S.size()){
		string cur = "";
		if(pos != -1){
			cur = memo[pos];
		}
		memo[pos] = "";
		if(cur == "-"){
			pos++;
			continue;
		}

		for(int i = 0; i <= 'z' - 'a'; i++){
			if(posarr[i].size() > 0 && posarr[i][0] == pos){
				posarr[i].pop_front();
			}
			if(posarr[i].size() == 0){
				if(ans == "-"){
					ans = cur + char(i + 'a');
				}else if(ans.size() > cur.size() + 1){
					ans = cur + char(i + 'a');
				}else if(ans.size() == cur.size() + 1 && ans > (cur + char(i + 'a'))){
					ans = cur + char(i + 'a');
