int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;
    const int n = s.length();
    vector<vector<int>> p(26);
    for(int i = 0; i < n; ++i){
        p[s[i] - 'a'].emplace_back(i);
    }
    for(int i = 0; i < 26; ++i){
        if(!p[i].size()){
            cout << (char)(i + 'a') << endl;
            return 0;
        }
        p[i].emplace_back(n);
    }
    vector<ll> dp(n + 1, -1);
    dp[n] = 0;
    auto dfs = [&](auto&& self, int cur) -> int {
        if(dp[cur] != -1)   return dp[cur];
        int res = INF;
        for(int i = 0; i < 26; ++i){
            int next = *upper_bound(p[i].begin(), p[i].end(), cur);
            chmin(res, self(self, next));
        }
        return dp[cur] = res + 1;
    };
    dfs(dfs, 0);
    int len = *max_element(dp.begin(), dp.end());
    int cur = -1;
    string ans = "";
    while(len > 0){
        for(int i = 0; i < 26; ++i){
            if(cur == -1){
                if(dp[p[i][0]] != len){
                    cur = p[i][0];
                    ans += (char)(i + 'a');
                    --len;
                    break;
                }
            }
            else{
                int next = *upper_bound(p[i].begin(), p[i].end(), cur);
                if(dp[next] != len){
                    cur = next;
                    ans += (char)(i + 'a');
                    --len;
                    break;
                }
            }
        }
        if(cur == -1)   ++len;
    }
    cout << ans << endl;
}

