void oput(const int *fr,const int pos,const char end){
	static char buk[N];
	char *pt=buk;
	*pt++=end;
	for(int i=pos; i; i=fr[i]) 
		*pt++=str[i];
	while(pt!=buk)
		putchar(*--pt);
	puts("");
}

void solve(){
	static int fr[N];
	std::queue <data> q;
	q.push((data){0,0});
	while(!q.empty()){
		data d=q.front();
		q.pop();
		for(int i=0; i<26; ++i){
			int y=nxt[d.pos][i];
			if(!y){
				oput(fr,d.pos,i+'a');
				return;
			}
			if(!vis[y]){
				vis[y]=1;
				fr[y]=d.pos;
				q.push((data){y,d.len+1});
			}
		}
	}
	assert(0);
}

