{
	int i, j, k, t;
	vector<vector<ll>> c(n);
	for (i = 0; i < n; i++)
	{
		for (j = 0; j < n; j++)
		{
			t = 0;
			for (k = 0; k < n; k++)
				t = (t + a[i][k] * b[k][j] % M) % M;
