// とても雑な二分探索
enum bscheck{
  BS_OK,
  BS_LARGE,
  BS_SMALL,
  BS_ERR
};

bscheck check(vector<int> &vec, int key, int id){
  if(id==0){
    if(vec[id]>=key){
      return BS_OK;
    }else{
      return BS_SMALL;
    }
  }else{
    if(vec[id] < key){
      return BS_SMALL;
    }else if(vec[id-1]<key){
      return BS_OK;
    }else{
      return BS_LARGE;
    }
  }
  return BS_ERR;
}

// key以上の値を持つ最初のvecのidを返す。vecはソートされているとする
int searchv(vector<int> &vec, int key, int id, int step){
  if(vec.size()==0){
    return -1;
  }
  bscheck bsc = check(vec, key, id);
  const int nstep = max(1,step/2);
  if(bsc == BS_OK){
    return id;
  }else if(bsc == BS_LARGE){
    return searchv(vec, key, id-nstep, nstep);
  }else if(bsc == BS_SMALL){
    if(id == vec.size()-1){
      return -1;
    }
    return searchv(vec, key, id+nstep, nstep);
  }
  return -1; //unreachable
}

