template <typename T, typename E>
struct SegmentTree {
	using F = function<T(T, T)>;
	using G = function<T(T, E)>;
	int n;
	F f; //二項演算
	G g; //update時の更新処理関数
	T ti; //単位元
	vector<T> dat;
	SegmentTree() {};
	SegmentTree(int n_, F f, G g, T ti) :
		f(f), g(g), ti(ti) {
		init(n_);
	}
	void init(int n_) {
		n = 1;
		while (n<n_) n <<= 1;
		dat.assign(n << 1, ti);
	}
	void build(int n_, vector<T> v) {
		for (int i = 0; i<n_; i++) dat[n + i] = v[i];
		for (int i = n - 1; i; i--)
			dat[i] = f(dat[(i << 1) | 0], dat[(i << 1) | 1]);
	}
	void update(int k, E a) {
		k += n;
		dat[k] = g(dat[k], a);
		while (k) {
			k >>= 1;
			dat[k] = f(dat[(k << 1) | 0], dat[(k << 1) | 1]);
		}
	}
	inline T query(int a, int b) {
		//[a,b)で二項演算を行う
		T vl = ti, vr = ti;
		for (int l = a + n, r = b + n; l<r; l >>= 1, r >>= 1) {
			if (l & 1) vl = f(vl, dat[l++]);
			if (r & 1) vr = f(dat[--r], vr);
		}
		return f(vl, vr);
	}
	template<typename C>
	int find(int a, int b, C &check, int k, int l, int r) {
		if (!check(dat[k]) || r <= a || b <= l) return -1;
		if (k >= n) return k - n;
		int m = (l + r) >> 1;
		int vl = find(a, b, check, (k << 1) | 0, l, m);
		if (~vl) return vl;
		return find(a, b, check, (k << 1) | 1, m, r);
	}
	template<typename C>
	int find(int a, int b, C &check) {
		//[a,b)区間がbool関数checkがtrueのとき
		return find(a, b, check, 1, 0, n);
	}
};

