bool check(string &s) {
    int cur = 0;
    for(int i = 0; i < (int)s.size(); i++) {
        if (!pos[cur + 1][s[i] - 'a'])
            return true;
        cur = pos[cur + 1][s[i] - 'a'];
    }
    return false;
}

void go() {
    queue<string> q;
    for(int j = 0; j < 26; j++) {
        string s = "";
        s += 'a' + j;
        q.push(s);
    }
    while(!q.empty()) {
        string temp = q.front();
        q.pop();
        //cout << temp << "\n";
        if(check(temp)) {
            cout << temp << "\n";
            exit(0);
        }
        for(int j = 0; j < 26; j++) {
            temp += 'a' + j;
            q.push(temp);
            temp.pop_back();
        }
    }
}

