char beginChar[maxn];
int nxt[maxn];

vector<int> bucket['z'-'a'+1];
int n;

int calc(int st) {
    if (len[st]>0) return len[st];
    for (char x='a'; x<='z';x++) {
        if (bucket[x-'a'].empty() || bucket[x-'a'][bucket[x-'a'].size()-1] < st) {
            beginChar[st] = x;
            return (len[st] = 1);
        }
    }

    int lnn = 2e6;

    for (char x='a'; x<='z';x++) {
        int ind = *lower_bound(bucket[x-'a'].begin(), bucket[x-'a'].end(), st);
        if (x == 'a' || (1+calc(ind+1)) < lnn) {
            lnn = 1+calc(ind+1);
            beginChar[st] = x;
            nxt[st] = ind+1;
        }
    }

    return (len[st] = lnn);
}

