    for (int i = 0; i < 26; i++) dp[i][0] = N;
    for (int i = N-1; i >= 0; i--) {
        int c = S[i] - 'a';
        int t = N;
        for (int j = 0; j < 26; j++) t = min(t, l[j]);
        if (l[c] == t) {
            l[c]++;
            dp[c][t+1] = i;
        }
    }

    //for (int i = 0; i < 26; i++) cout << dp[i][1] << " " << dp[i][2] << " " << dp[i][3] << endl;

    pair<int, int> st;
