    for (int i = 1; i < 26; i++) {
        if (st.second > l[i]) st = {i, l[i]};
    }

    int pos = 0;
    int now = st.second;
    string ans = "";
    while(now >= 0) {
        int lim = N;
        for (int i = 0; i < 26; i++) lim = min(lim, dp[i][now]);
        vector<bool> use(26, false);
        for (int i = pos; i < lim; i++) {
            use[S[i]-'a'] = true;
