// dp[i] := [i, n) の部分文字列に含まれない文字列の最小の長さ
int dp[200005];
vector<vector<int>> pos(26);
int n;

int get_next(int x, char c){
    int id = c - 'a';
    return *lower_bound(pos[id].begin(), pos[id].end(), x);
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;
    n = s.length();
    for(int i = 0; i < n; ++i){
        int id = s[i] - 'a';
        pos[id].push_back(i);
    }
    // 番兵
    for(int i = 0; i < 26; ++i) pos[i].push_back(n);

    fill(dp, dp + n, INF);
    dp[n] = 1;
    for(int i = n - 1; i >= 0; --i){
        for(char c = 'a'; c <= 'z'; ++c){
            int next = get_next(i, c);
            chmin(dp[i], dp[next + 1] + 1);
        }
    }

    int now = dp[0];
    int now_pos = 0;
    string res = "";
    while(now > 0){     // DPの経路復元
        --now;
        for(char c = 'a'; c <= 'z'; ++c){
            int next = get_next(now_pos, c);
            if(dp[next + 1] == now){    // c と substring([next+1, n)) が条件を満たせば
                res += c;
                now_pos = next + 1;
                break;
            }
        }
    }
    cout << res << "\n";
}

