typedef pair<ll, ll> pll;
typedef pair<int, pii> pip;
const ll INF = 1e9+100;
const ll MOD = 1e9;
const double EPS = 1e-10;
const bool debug = 0;
//------------------------------//

string s;
int dp[212345][28];
int previ[212345][28]; // prev-i

int g[212345][28];

int main() {
	cin >> s;

	REP(i, s.size()) s[i] -= 'a';
	s.insert(0, "a"); s[0] = 26; // st
	s += (char)(27); // ed

	REP(i, 28) g[0][i] = 0;

	REP(i, s.size() - 1) {
		REP(j, 28) {
			if (s[i] == j) continue;
			g[i + 1][j] = g[i][j];
		}
		g[i + 1][s[i]] = i;
	}

	memset(previ, -1, sizeof(previ));
	fill(dp[0], dp[s.size()], INF);

	dp[s.size() - 1][27] = 0;

	for (int i = s.size() - 1; i > 0; i--) { // 0-indexed
		REP(j, 28) {
			if (dp[i][j] == INF) continue;
			REP(k, 26) {
				if (chmin(dp[g[i][k]][s[i]], dp[i][j] + 1))
					previ[g[i][k]][s[i]] = i;
			}
		}
	}

	vector<string> v;

	REP(i, 28) {
		if (dp[0][i] == INF) continue;
		int pos = previ[0][i], cnt = dp[0][i];

		string now = "";
		REP(j, 26) if (g[pos][j] == 0) {
			now += j + 'a';
			break;
		}

		while (pos != s.size() - 1) {
			now += s[pos] + 'a';
			REP(j, 28) if (dp[pos][j] == cnt - 1) {
				pos = previ[pos][j];
				cnt--;
				break;
			}
		}

		v.push_back(now);
	}

	sort(ALL(v));
	int mi = INF;
	string ans;
	REP(i, v.size()) if (chmin(mi, v[i].size())) ans = v[i];
	cout << ans << endl;

	return 0;
}

