const int MAXN = int( 2e5 )+10;
const int MOD  = int( 360 );
const int oo   = INT_MAX;
const int A    = 26;

string s;
int nxt[ A ][ MAXN ];
int dp[ MAXN ];
string ans;

void precalc() {
  int sz = SIZE(s), cur[ A ];
  memset( cur, -1, sizeof(cur) );
  for( int i = sz-1; i >= 0; --i ) {
    for( int j = 0; j < A; ++j ) {
      nxt[ j ][ i ] = cur[ j ];
    }
    cur[ s[i]-'a' ] = i;
  }
}

void solve() {
  int sz = SIZE(s);
  for( int i = sz-1; i >= 0; --i ) {
    dp[ i ] = oo;
    for( int j = 0; j < A; ++j ) {
      if( s[i] == 'a'+j ) dp[ i ] = min( dp[i], 1+dp[i+1] );
      else if( nxt[ j ][ i ] == -1 ) dp[ i ] = 1;
      else dp[ i ] = min( dp[i], 1+dp[ nxt[ j ][ i ] ] );
    }
  }
}

void get_ans( int cur ) {
  for( int i = 0; i < A; ++i ) {
    if( s[cur] == 'a'+i ) {
      if( dp[cur] == 1+dp[cur+1] ) {
        ans.PB( 'a'+i );
        return get_ans( cur+1 );
      }
    }
    if( nxt[ i ][ cur ] == -1 ) {
      ans.PB( 'a'+i );
      return;
    }
    else if( dp[ cur ] == dp[ nxt[ i ][ cur ] ]+1 ) {
      ans.PB( 'a'+i );
      return get_ans( nxt[ i ][ cur ] );
    }
  }
}

