int index[26][max_length + 1];
int first[26];
int length;

void solve() {
	length = strlen(a);
	for (int i = 0; i < 26; i++) {
		fill(index[i], index[i] + length, length);
	}

	for (int i = 0; i < length; i++) {
		int x = a[i] - 'a';

		index[x][first[x]] = i;
		first[x]++;
	}
	fill(first, first + 26, 0);

	int pos = 0;
	char *it = result;
	while (pos < length) {
		int best = -1;

		for (int i = 0; i < 26; i++) {
			int &j = first[i];
			while (index[i][j] < pos) {
				j++;
			}

			if (best == -1 || (index[i][j] > index[best][first[best]])) {
				best = i;

				if (index[i][j + 1] == length) {
					break;
				}
			}
		}

		*it++ = (char)('a' + best);
		pos = index[best][first[best]] + 1;
	}

	*it = '\0';
}

int main() {

	cin >> a;

	solve();

	cout << result << "\n";

	return 0;
}

