	string A; cin >> A;

	for (int i = 0; i < 26; i++) {
		char a = 'a' + i;
		A.push_back(a);
	}
	int N = A.size();

	graphClass G, H;
	G.activate(N, true);
	H.activate(N, true);

	int buf[26];
	for (int i = 0; i < 26; i++) {
		buf[i] = N - 26 + i;
	}
	for (int i = N - 27; i >= 0; i--) {
		int k = A[i] - 'a';
		for (int j = 0; j < 26; j++) {
			G.addEdge(i, buf[j]);
			H.addEdge(buf[j], i);
		}
		buf[k] = i;
	}
	G.sortEdge();
	H.sortEdge();

	return 0;

	vector<ll*> route;
	ll M = N;
	for (int i = 0; i < 26; i++) {
		route.push_back(G.dijkstra(buf[i]));
		for (int j = N - 26; j < N; j++) {
			M = min(M, route[i][j]);
		}
	}

	vector<char> ans;
	for (int i = 0; i < 26; i++) {
		for (int j = N - 26; j < N; j++) {
			if (route[i][j] == M) {
				int k = j;
				while (k >= 0) {
					ans.push_back(A[k]);
