						int y = itr->x + itr->y - k;
						if (route[i][y] == route[i][k] - 1 && A[y] <= m) {
							m = A[y];
							t = y;
						}
					}
					k = t;
				}
				int S = ans.size();
				for (int k = S - 1; k >= 0; k--) {
					cout << ans[k];
				}
				return 0;
			}
		}
	}

	return 0;
}

