#define N 200004

using namespace std;

string s;
ll minlength[N];
ll n;
ll seg[4*N][26];
string ans;

void build(ll low,ll high,ll pos,ll id)
{
    if(low == high)
    {
        seg[pos][id] = (ll)(s[low]-'a' == id);
        return;
    }

    ll mid = (low+high)/2;
    build(low,mid,pos*2+1,id);
    build(mid+1,high,pos*2+2,id);

    seg[pos][id] = seg[pos*2+1][id]+seg[pos*2+2][id];
    return;
}

ll first_occurence(ll low,ll high,ll pos,ll slow,ll id)
{
    ll mid = (low+high)/2;

    if(seg[pos][id] == 0)
        return n;

    if(low >= slow)
    {
        if(low == high)
            return low;
        if(seg[pos*2+1][id] > 0)
            return first_occurence(low,mid,pos*2+1,slow,id);
        return first_occurence(mid+1,high,pos*2+2,slow,id);
    }
    if(high < slow)
        return n;

    return min(first_occurence(low,mid,pos*2+1,slow,id),first_occurence(mid+1,high,pos*2+2,slow,id));
}

ll calc(ll cur)
{
    if(cur > n)
        return 0;
    if(cur == n)
        return 1;

    if(minlength[cur])
        return minlength[cur];

    minlength[cur] = n-cur+1;

    rep(i,0,26)
    {
        ll goes = first_occurence(0,n-1,0,cur,i);

        minlength[cur] = min(minlength[cur],calc(goes+1)+1);
    }

    return minlength[cur];
}

void solve(ll cur,ll pos)
{
    if(cur >= n)
        return;

    rep(i,0,26)
    {
        ll goes = first_occurence(0,n-1,0,cur,i);

        if(minlength[goes+1]+1==minlength[cur])
        {
            ans[pos]=i+'a';
            solve(goes+1,pos+1);
            break;
        }
    }

    return;
}

int main()
{
    ios_base::sync_with_stdio(false);
    cin >> s;
    n = s.size();

    rep(i,0,26)
        build(0,n-1,0,i);

    calc(0);

    rep(i,0,minlength[0])
        ans += "a";

    solve(0,0);

    cout << ans;

    return 0;
}

