string ans="";
int ansSize = INF;

string cal(string strA, string strB){
	if( strA == "" ){
		return strB;
	}
	int sizeA = strA.size();
	int sizeB = strB.size();
	if( sizeA < sizeB ){
		return strA;
	}else if(sizeA > sizeB ){
		return strB;
	}
	return min(strA,strB);//辞書順で小さいもの
}

void dfs(int v,int dep,string now){
	if( dep+1 >= ansSize ){
		return;
	}
	for(int i=0;i<26;++i){
		if( A[v][i] == -1 ){
			string temp = now;
			temp += 'a'+i;
			ans = cal(ans,temp);
			ansSize = ans.size();
			return;
		}
	}
	for(int i=0;i<26;++i){
		int to = A[v][i];
		if( to == -1 ) continue;
		string temp = now;
		temp += 'a' + i;
		dfs( to,dep+1,temp );
	}
}
