void solve(){
	string str;
	cin >> str;
	int N = str.size();
	A = vector< vector<int> >(N,vector<int>(26,-1));
	vector<int> temp(26,-1);
	for(int i=N-1;i>=0;--i){
		A[i] = temp;
		int res = str[i]-'a';//res番目の文字 0index
		temp[res] = i;//一番近い文字になる。
	}

	int cnt = 0;
	for(int i=0;i<26;++i){
		if( temp[i] == -1 ){//無い文字
			char ansC = 'a' + i;
			cout << ansC << endl;
			return;
		}
	}
	void dfs(int v,int dep,string now);
	string dam = "";
	queue<word> que;
	for(int i=0;i<26;++i){
		int to = temp[i];//-1ではない
		dam += 'a'+i;
		word temp;
		temp.v = to;
		temp.str = dam;
		que.push( temp );
		dam = "";
	}

	while( !que.empty() ){
		word now = que.front();que.pop();
		int v = now.v;
		int size = now.str.size();
		if( size+1 >= ansSize ) break;

		for(int i=0;i<26;++i){
			int to = A[v][i];
			if( to == -1 ){
				string res = now.str;
				res += 'a' + i;
				ans = cal(ans, res);
				ansSize = ans.size();
				break;
			}else{
				word temp = now;
				temp.v = to;
				temp.str += 'a' + i;
				que.push( temp );
			}
		}
	}
	cout << ans << endl;
}

