pair<int, int> getAns(int p) {
	if (p == n) return make_pair(-1, 0);
	if (ans[p] != make_pair(0, 0)) return ans[p];
	int minLen = INT_MAX;
	pair<int, int> ret[26];
	for (int i = 0; i < 26; ++i) {
		ret[i] = make_pair(i, getAns(go[p][i]).second + 1);
		minLen = min(minLen, ret[i].second);
	}
	for (int i = 0; i < 26; ++i)
