void solve(){
	cin >> s;
	n = sz(s);
	fr(i, 0, N) fr(k, 0, K) nxt[i][k] = N - 1;
	fdr(i, 0, n){
		if(s[i] >= 'a' && s[i] <= 'z') nxt[i][s[i]-'a'] = i;
		fr(j, 0, K) nxt[i][j] = min(nxt[i][j], nxt[i+1][j]);
	}

	fr(i, 0, N) fr(k, 0, K) d[i][k] = 1, dp[i] = 0;

	fdr(i, 0, n){
		fdr(k, 0, K){
