			d[i][k] = 1 + d[np][dp[np]];
		}
		fr(k, 0, K){
			if(d[i][k] < d[i][dp[i]]) dp[i] = k;
		}
	}

	string ans = "";
	int p = 0;
	while(p < n){
		ans += (char)(dp[p] + 'a');
		p = nxt[p][dp[p]] + 1;
