    SegTree(int n_, const T& def) : Default(def){init(n_);}
    void init(int n_){
        n = 1;
        while(n < n_) n *= 2;
        dat = vector<T>(2*n-1, Default);
    }
    T f(const T& a, const T& b) {
    	return min(a, b);
    }
    void update(int k, const T& a){
        k += n-1;
        dat[k] = a;
        while(k > 0){
            k = (k - 1) / 2;
            dat[k] = f(dat[k * 2 + 1], dat[k * 2 + 2]);
        }
    }
    T query(int a, int b, int k, int l, int r ){
        if(r <= a || b <= l) return Default;
        if(a <= l && r <= b) return dat[k];
        T vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
        T vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
        return f(vl, vr);
    }
    T query(int a, int b) {
    	return query(a, b, 0, 0, n);
    }
};

int main(){
	string s;
	cin >> s;
	int n = s.size();
	SegTree<int> *st[26];
	rep(i, 26) st[i] = new SegTree<int>(n, INF);
	rep(i, n) {
		int idx = s[i] -'a';
		st[idx]->update(i, i);
	}
	auto check = [&] (const string& t) {
		int m = t.size();
		int idx = 0;
		rep(i, m) {
			idx = st[t[i]-'a']->query(idx, n)+1;
			if(idx == INF+1) return false;
		}
		return true;
	};

	queue<string> q;
	q.push("");
	while(!q.empty()) {
		string t = q.front();
		q.pop();
		if(check(t)) {
			for(char c = 'a'; c <= 'z'; c++) q.push(t+c);
		}
		else {
			cout << t << endl;
			return 0;
		}
	}
}

