pair < int, int > ansQ, aint[800009];
int howQ, how[800009];

void Update (int nod, int st, int dr, int pos, pair < int, int > val)
{
    if (st == dr)
    {
        aint[nod] = val, how[nod] = st;
        return ;
    }
    int mij = (st + dr) >> 1, f1 = nod << 1, f2 = f1 | 1;
    if (pos <= mij) Update (f1, st, mij, pos, val);
    else Update (f2, mij + 1, dr, pos, val);
    if (aint[f1] < aint[f2]) how[nod] = how[f1];
    else how[nod] = how[f2];
    aint[nod] = min (aint[f1], aint[f2]);
}

void Query (int nod, int st, int dr, int x, int y)
{
    if (x <= st && dr <= y)
    {
        if (x == st) ansQ = aint[nod], howQ = how[nod];
        else
        if (aint[nod] < ansQ)
            ansQ = aint[nod], howQ = how[nod];
        return ;
    }
    int mij = (st + dr) >> 1, f1 = nod << 1, f2 = f1 | 1;
    if (x <= mij) Query (f1, st, mij, x, y);
    if (mij < y) Query (f2, mij + 1, dr, x, y);
}

