        for(int j = n-1;j>=0;j--)
        {
            if(s[j]-'a'==i)
                epomeno[j][i]=j;
            else
                epomeno[j][i]=epomeno[j+1][i];
        }
    }

    calc(0);

    rep(i,0,minlength[0])
        ans += "a";

    solve(0,0);

    cout << ans;

    return 0;
}

