vector<vector<int>> calcNext(const string &s){
	int n = s.size();
	vector<vector<int>> res(n + 1, vector<int>(26, n)); 
	for(int i = n - 1; i >= 0; --i){
		for(int c = 0; c < 26; ++c){
			res[i][c] = res[i + 1][c]; 
			res[i][s[i] - 'a'] = i; 
		}
	}

	return res;
}

