int getpos(const V<ll> &poslist, ll start)
{
        int left = 0;
        int right = poslist.size() - 1;
        int now = (left + right) / 2LL;
        int idx = right;

        for ( ; left <= right; now = (left + right) / 2) {
                if (poslist[now] < start) {
                        left = now + 1;
                        continue;
                }
                idx = min(idx, now);
                right = now - 1;
        }

        return poslist[idx];
}

