        cur[ a[i] - 'a' + 1 ] = i;
        f[i] = 1e9;
        for ( int j = 1; j <= 26; j++ ){
            if ( cur[j] == n + 1 ){
                f[i] = -1;
            }
            else{
                f[i] = min( f[i], f[ cur[j] + 1 ] );
            }
            nxt[i][j] = cur[j];
        }
        f[i]++;
    }
    int cur = 1, len = f[1] + 1;
    for ( int i = 1; i <= len; i++ ){
        for ( int j = 1; j <= 26; j++ ){
            if ( nxt[cur][j] == n + 1 ){
                ans[++curLen] = 'a' + j - 1;
                break;
            }
            else
            if ( f[ nxt[cur][j] + 1 ] == len - 1 - i ){
                ans[++curLen] = 'a' + j - 1;
                cur = nxt[cur][j] + 1;
                break;
            }
        }
    }
    for ( int i = 1; i <= curLen; i++ ){
        printf("%c",ans[i]);
    }
    return 0;
}

