/////////////////////

int const N = 2e5 + 41;
int const K = 26;

int n;
string s;
int nxt[N][K];
string ans;

int w[N][K];
pair<int, string> d[N][K];

void clearWas(){
	fr(i, 0, N) fr(k, 0, K) w[i][k] = 0;
}

pair<int, string> dfs(int pos, int rem){
	if(rem == 0){
		if(pos > n) return mp(1, "");
		else return mp(0, "");
	}
	if(pos >= n) return mp(1, "");
	if(w[pos][rem]) return d[pos][rem];
	w[pos][rem] = 1;
	pair<int, string> ret = mp(0, "");
	fr(i, 0, K){
		pair<int, string> res = dfs(nxt[pos][i] + 1, rem-1);
		if(res.first){
			ret.first = 1;
			string pans;
			pans.pb(i + 'a');
			pans += res.second;
			if(sz(ret.second) == 0 || pans < ret.second){
				ret.second = pans;
			}
		}
	}

	return d[pos][rem] = ret;
}

void solve(){
	cin >> s;
	n = sz(s);
	fr(i, 0, N) fr(k, 0, K) nxt[i][k] = N;
	fdr(i, 0, n){
		if(s[i] >= 'a' && s[i] <= 'z') nxt[i][s[i]-'a'] = i;
		fr(j, 0, K) nxt[i][j] = min(nxt[i][j], nxt[i+1][j]);
	}

	fr(l, 1, K){
		clearWas();
		pair<int, string> res = dfs(0, l);
		if(res.first){
			ans = res.second;
			break;
		}
	}
	cout << ans << endl;
}

int main(){
#ifdef _DEBUG
	freopen("input.txt","r",stdin);
	freopen("output.txt","w",stdout);
#endif

	solve();


	return 0;
}

