#include <bits/stdc++.h>

using namespace std;

constexpr int N = 200000;
constexpr int M = 26;

char s[N+1];
vector<int> pos;
bitset<M> vis;

int main() {
  scanf("%s", s);
  int n = strlen(s);
  pos.push_back(n);
  int i = n-1;
  while(i >= 0) {
    for(; i>=0; --i) {
      vis[s[i]-'a'] = true;
      if(vis.all()) {
        pos.push_back(i);
        vis.reset();
        break;
      }
    }
    --i;
  }
  string ans;
  i = 0;
  while(true) {
    vis.reset();
    int j = i;
    for(; j<pos.back(); ++j)
      vis[s[j]-'a'] = true;
    for(int k = 0; k<M; ++k)
      if(!vis[k]) {
        ans.push_back('a'+k);
        break;
      }
    pos.pop_back();
    if(pos.empty())
      break;
    while(s[i] != ans.back())
      ++i;
    ++i;
  }
  printf("%s\n", ans.c_str());
}

