bool check(const string &s, const string &t) {
    int s_idx = 0;
    for (int i : rep(0, t.size())) {
        while (s_idx < s.size()) {
            if (s[s_idx] == t[i]) {
                if (i == t.size() - 1) {
                    return false;
                }

                s_idx++;
                break;
            }
            s_idx++;
        }

        if (s_idx == s.size()) {
            break;
        }
    }

    return true;
}

