using namespace std;

int succ[200002][26];
int dp[200002];
int pre[200002];

int main() {
  string s;
  cin >> s;

  const int n = s.size();
  reverse(s.begin(), s.end());
  s = '^' + s;
  for (int i = 0; i < 26; i++) {
    succ[n][i] = -1;
  }
  for (int i = n - 1; i >= 0; i--) {
    for (int j = 0; j < 26; j++) {
      if (s[i + 1] == j + 'a') {
        succ[i][j] = i + 1;
      } else {
        succ[i][j] = succ[i + 1][j];
      }
    }
  }

  for (int i = 0; i < 200002; i++) {
    dp[i] = 1e9;
    pre[i] = -1;
  }
  dp[0] = 0;

  for (int i = 0; i < n; i++) {
    for (int j = 0; j < 26; j++) {
      int k = succ[i][j];
      if (k != -1) {
        if (dp[k] > dp[i] + 1) {
          dp[k] = dp[i] + 1;
          pre[k] = i;
        } else if (dp[k] == dp[i] + 1) {
          if (s[pre[k]] > s[i]) {
            pre[k] = i;
          }
        }
      }
    }
  }

  int mn = 1e9;
  for (int i = 0; i <= n; i++) {
    bool all = true;
    for (int j = 0; j < 26; j++) {
      if (succ[i][j] == -1) all = false;
    }
    if (!all) {
      mn = min(mn, dp[i]);
    }
  }

  string ans = "~";
  for (int i = 0; i <= n; i++) {
    bool all = true;
    for (int j = 0; j < 26; j++) {
      if (succ[i][j] == -1) all = false;
    }
    if (all) continue;
    if (dp[i] != mn) continue;
    string cand;
    for (int j = 0; j < 26; j++) {
      if (succ[i][j] == -1) {
        cand += j + 'a';
        break;
      }
    }
    for (int j = i; j != 0; j = pre[j]) {
      cand += s[j];
    }
    ans = min(ans, cand);
  }

  cout << ans << endl;
}

