    }

    rep(i, n) s[a[i] - 'a'].insert(i);

    string ans;
    int now = 0;
    rep(_, k) rep(i, 'z' - 'a' + 1) {
        auto idx = s[i].lower_bound(now);
        if (idx == s[i].end()) {
            ans += 'a' + (char)i;
            break;
        }
        if (c[*idx + 1] == c[now] - 1) {
            ans += 'a' + (char)i;
            now = *idx + 1;
            break;
        }
    }
    cout << ans << endl;
}

