int conv(char c) {
    return c - 'a';
}

string solve(const string & s) {
    int n = s.length();
    vector<vector<int>> links(26);
    for (int i = 0; i < 26; i++) {
        links[i].resize(n + 1);
        int prev = n;
        for (int j = n - 1; j >= -1; j--) {
            links[i][j + 1] = prev;
            if (j >= 0 && conv(s[j]) == i)
                prev = j;
        }
    }
    string result = "";
    for (int c = 0; c < 26; c++) {
        if (links[c][0] == n) {
            result += (char)(c + 'a');
            return result;
        }
    }
    vector<int> cur_layer(n), prev_layer(n);
    fill(prev_layer.begin(), prev_layer.end(), true);
    vector<vector<int>> par(20);
    for (int i = 0; i < 20; i++) {
        par[i].resize(n + 1);
        for (int j = 0; j < n; j++) {
            cur_layer[j] = true;
            for (int c = 0; c < 26; c++) {
                if (links[c][j + 1] == n || !prev_layer[links[c][j + 1]]) {
                    cur_layer[j] = false;
                    par[i][j] = c;
                    break;
                }
            }
        }
        for (int c = 0; c < 26; c++) {
            if (links[c][0] == n || !cur_layer[links[c][0]]) {
                result += (char)(c + 'a');// + solve(s.substr(links[c][0] + 1));
                int cur = links[c][0];
                int lvl = i;
                while (lvl >= 0) {
                    result += (char)(par[lvl][cur] + 'a');
                    cur = links[par[lvl][cur]][cur + 1];
                    lvl--;
                }
                return result;
            }
        }
        swap(cur_layer, prev_layer);
    }
    return "";
}

int main() {
    cin.tie(0);
    ios_base::sync_with_stdio(false);

    string s;
    cin >> s;
    cout << solve(s) << endl;
}

