bool ismin(string s, string t)
{
	if(s.length() < t.length()) return true;
	if(s.length() > t.length()) return false;
	for(int i = 0; i < s.length(); i++){
		if(s[i] < t[i]) return true;
		else return false;
	}
	return true;
}

