int main(){

    scanner >> S;
    N = S.size();

    const set<int> charset = [](){ set<int> s; repeat(i, A) s.insert('a'+i); return s; }();

    vector<pair<int, int>> ranges;
    ranges.emplace_back(0, 0);

    set<int> ss;
    repeat(i, N) {
        int c = S[i];
        ss.insert(c);
        if (ss.size() == A) {
            ranges.back().second = i;
            ranges.emplace_back(i + 1, 0);
            ss.clear();
        }
    }
    ranges.pop_back();

    repeat(k, A){
        if (ss.count('a' + k)) continue;
        dp[0][k] = -1;
        break;
    }

    int p = 0;
    iterate(it, ranges.rbegin(), ranges.rend()) {
        repeat(c, A) {
            if (dp[p][c] == 0) continue;
            int i = it->second;
            while (S[i] != c + 'a') --i;
            auto s = charset;
            for (--i; it->first <= i; --i) s.erase(S[i]);
            for (int e : s) {
                if (dp[p + 1][e - 'a'] == 0 ||
                    dp[p + 1][e - 'a'] > c + 1)
                    dp[p + 1][e - 'a'] = c + 1;
            }
        }
        ++p;
    }
    int t = 0;
    repeat(c, A) {
        if (dp[p][c] != 0) {
            printer << char(c + 'a');
            t = dp[p--][c] - 1;
            break;
        }
    }
    while (t >= 0) {
        printer << char(t + 'a');
        t = dp[p--][t] - 1;
    }

    printer << '\n';

    return 0;
}

