            int pos2 = *iter2; // search2() 済ry
            FOR(i3, 0, 26) {
                auto iter3 = pos[i3].upper_bound(pos2);
                if(iter3 == end(pos[i3])) {
                    cout << idx2str({i1, i2, i3}) << "\n";
                    return true;
                }
            }
        }
    }

    return false;
}

bool search4()
{
