        int pos1 = *iter1;
        FOR(i2, 0, 26) {
            auto iter2 = pos[i2].upper_bound(pos1);
            int pos2 = *iter2; // search2() 済ry
            FOR(i3, 0, 26) {
                auto iter3 = pos[i3].upper_bound(pos2);
                int pos3 = *iter3; // search3() 済ry
                FOR(i4, 0, 26) {
                    auto iter4 = pos[i4].upper_bound(pos3);
                    if(iter4 == end(pos[i4])) {
                        cout << idx2str({i1, i2, i3, i4}) << "\n";
                        return true;
                    }
                }
            }
        }
    }

    return false;
}

void solve()
{
