bool comp(string a, string b) {
  if (a == "")
    return true;
  if (a.size() > b.size())
    return true;
  else if (a.size() < b.size())
    return false;
  else {
    ll n = a.size();
    REP(i, n) {
      if (a[i] > b[i])
        return true;
      else if (a[i] < b[i])
        return false;
    }
  }
  return false;
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(NULL);
  string A;
  cin >> A;
  ll N = A.size();
  vvl M = VVL(26, N, 0);
  vvl DP = VVL(26, N + 1, -1);
  vl first(26, -1);
  REP(i, N) {
    M[A[i] - 'a'][i] = 1;
    if (first[A[i] - 'a'] == -1)
      first[A[i] - 'a'] = i;
  }
  REP(i, N) {
    REP(j, 26) {
      if (A[N - i] - 'a' == j)
        DP[j][N - i - 1] = N - i;
      else
        DP[j][N - i - 1] = DP[j][N - i];
    }
  }
  string ans = "";
  REP(i, 26) {
    queue<pair<ll, string>> Q;
    string score = "";
    if (first[i] == -1) {
      ans = (string) "" + (char)('a' + i);
      break;
    }
    Q.push(make_pair(first[i], (string) "" + (char)('a' + i)));
    bool end = false;
    while (!end) {
      auto po = Q.front();
      Q.pop();
      if (po.first == N - 1) {
        score = po.second + "a";
        end = true;
        break;
      } else {
        REP(j, 26) {
          // cout << DP[j][po.first + 1] << endl;
          if (DP[j][po.first + 1] == -1) {
            end = true;
            score = po.second + (char)('a' + j);
            // cout << score << endl;
            break;
          } else {
            Q.push(make_pair(DP[j][po.first + 1], po.second + (char)('a' + j)));
          }
        }
      }
    }
    // cout << score << endl;
    if (comp(ans, score))
      ans = score;
  }
  cout << ans << endl;

  return 0;
}

