  while (dp[pos] > 0){
    for (int i = 0; i < 26; i++){
      if (dp[next[pos][i]] == dp[pos] - 1){
        pos = next[pos][i];
        ans += 'a' + i;
        break;
      }
    }
  }
  cout << ans << endl;
