#define SIZE 200010


int f[SIZE][19] = {};
int to[SIZE][19] = {};
int dp[SIZE] = {};
int n;

int next_l(int x){

  int l = x;
  int sum_f = 0;

  for(int j=18;j>=0;j--){
    if(to[l][j] == -1) continue;

    if((sum_f | f[l][j]) != (1 << 26) - 1){
      sum_f |= f[l][j];
      l = to[l][j];
    }
  }

  return l;
}

int main(){
  string s;
  cin >> s;

  n = s.size();

  //debug(n);

  memset(f, 0, sizeof(f));
  memset(to, -1, sizeof(to));

  for(int i=0;i<n;i++){
    f[i][0] = 1 << (s[i] - 'a');
    to[i][0] = i+1;
  }

  for(int j=1;j<19;j++){
    for(int i=0;i<n;i++){
      if(to[i][j-1] != -1)
        to[i][j] = to[to[i][j-1]][j-1];

      f[i][j] = f[i][j-1] | f[to[i][j-1]][j-1];
      //cerr << "to[" << i << "][" << j-1 << "] = " << to[i][j-1] << endl; 
    }
  }

  dp[n] = -1;

  for(int i=n-1;i>=0;i--){
    int ret = next_l(i);
    dp[i] = dp[ret] + 1;

    //cerr << i << " : " << dp[i] << endl;
  }

  int len = dp[0] + 1;

  //debug(len);

  string ans;
  int l = 0;
  int r = next_l(0);

  for(int i=0;i<len;i++){

    if(i + 1  == len){
      int t = 0;
      for(int j=l;j<n;j++){
        t |= 1 << (s[j]-'a'); 
      }

      for(int j=0;j<26;j++){
        if(!(t & (1 << j))){
          ans += "a";
          ans[ans.size()-1] += j;
          break;
        }
      }

      continue;
    }

    bool flag = false;
    bool used[26] = {};

    for(int j=0;j<26;j++){

      for(int k=l;k<=r;k++){
        if(s[k] - 'a' == j && !used[j]){
          used[j] = true;
          auto res = dp[k+1];
          if(res + 2 + i == len){
            ans += "a";
            ans[ans.size()-1] += j;
            l = k + 1;
            r = next_l(k+1) - 1;
            flag = true;
          }
          break;
        }
      }

      if(flag) break;
    }
  }


  cout << ans << endl;

  return 0;
}

