signed main(void){

    string A; cin >> A;
    int sz = (int)A.size();
    vector<vector<int>> graph(sz + 2);

    vector<int> place(26, sz + 1);
    for(int i = sz; i >= 0; i--){
        rep(j, 26)graph[i].push_back(place[j]);
        if(i)place[A[i - 1] - 'a'] = i;
    }

    const int inf = 10000000000;
    typedef pair<int, int> pa;
    vector<pa> dist(sz + 2, pa(inf, inf));
    dist[0] = pa(0, -1);

    queue<int> que;
    vector<int> prev(sz + 2);
    vector<char> way(sz + 2);
    rep(k, (int)graph[0].size()){
        int i = graph[0][k];
        if(chmin(dist[i], pa(1, -1))){
            que.push(i);
            prev[i] = 0;
            way[i] = 'a' + k;
        }
    }

    while(que.size()){
        int v = que.front(); que.pop();
        rep(k, (int)graph[v].size()){
            int i = graph[v][k];
            if(chmin(dist[i], pa(dist[v].first + 1, 'a' + k))){
                que.push(i);
                prev[i] = v;
                way[i] = 'a' + k;
            }
        }
    }

    string ans = "";
    for(int t = sz + 1; t != 0; t = prev[t]){
        ans += way[t];
    }
    reverse(all(ans));
    cout << ans << endl;

}

