vector<vector<int>>nx;
vector<int>dp;

int Search(int n) {
	if (dp[n] != INT_MAX) {
		return dp[n];
	}
	bool flag = true;
	int box = INT_MAX;
	for (int i = 0; i < 26; i++) {
		if (nx[n][i] == INT_MAX) {
			flag = false;
			dp[n] = 0;
			return dp[n];
		}
		box = min(box, Search(nx[n][i]));
	}
	if (flag) {
		dp[n] = box+1;
	}
	return dp[n];
}

