int main() {
    std::iostream::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);

    // code here.
    string s = input<string>();

    vector<vector<int>> next(26, vector<int>(SZ(s) + 1, SZ(s)));
    for (int let = 0; let != 26; ++let)
        for (int pos = SZ(s) - 1; pos >= 0; --pos)
            next[let][pos] = (s[pos] == 'a' + let ? pos : next[let][pos + 1]);

    vector<int> f(SZ(s) + 1, 0);
    for (int i = SZ(s) - 1; i >= 0; --i) {
        int go = -1;
        for (int j = 0; j != 26; ++j)
            go = max(go, next[j][i]);

        if (go < SZ(s))
            f[i] = 1 + f[go + 1];
    }

    int ans_l = f[0] + 1;
    cerr << ans_l << "\n";
    string ans = "";
    int cur_pos = 0;
    for (int i = 0; i != ans_l; ++i) {
        int let;
        for (let = 0; let != 26; ++let)
            if (next[let][cur_pos] == SZ(s) or f[next[let][cur_pos] + 1] < ans_l - i - 1) {
                ans.push_back('a' + let);
                cur_pos = min(SZ(s), next[let][cur_pos] + 1);
                break;
            }

        assert(let != 26);
    }

    cout << ans << "\n";

    return 0;
}

