// Problem Specific Parameter:

const int limit = 200010;
int nxt[26][limit];
string s;
int n, ans[limit], len[limit];


void calc(int pos) {
	int nidx = -1, cmin = limit;

	rep(i, 26) {
		const int tar = nxt[i][pos + 1];

		if (tar == -1) {
			nidx = n + i;
			cmin = 1;
			break;
		} else {
			if (len[tar] == 0) calc(tar);
			if (chmin(cmin, len[tar])) nidx = tar;
		}
	}
	ans[pos] = nidx, len[pos] = cmin + 1;
}

int main(void) {
	cin >> s;
	n = s.size();

	rep(i, 26)rep(j, limit) nxt[i][j] = -1;
	rep(i, n) nxt[s[i] - 'a'][i] = i;

	rep(i, 26)rrep(j, n - 1) {
		if (nxt[i][j] != -1) continue;
		nxt[i][j] = nxt[i][j + 1];
	}

	s += "abcdefghijklmnopqrstuvwxyz";

	int cur = 0,cmin = limit;
	rep(i, 26) {
		const int tar = nxt[i][0];
		if (tar == -1) {
			cout << char(i + 'a') << endl;
			return 0;
		}else{
			if (len[tar]== 0) calc(tar);
			if(chmin(cmin,len[tar])) cur = tar;
		}
	}

	string out = "";
	while(1){
		out += s[cur];
		if(cur >=n) break;
		cur = ans[cur];
	}

	cout << out << endl;

	return 0;
}

