int n;
string str;
vector<int> xid[27];
int dp[200001];
int type[200001],next[200001];

int solve(int v){
	if(dp[v]!=-1)return dp[v];
	int res=n+2,nex=n+2;
	for(int i=0;i<26;i++){
		int nv=lower_bound(xid[i].begin(),xid[i].end(),v)-xid[i].begin();
		if(xid[i][nv]==n){
			if(res>1){
				res=1;
				type[v]=i;
				next[v]=n;
			}
		}else{
			int vv=solve(xid[i][nv]+1);
			if(res>vv+1){
				res=vv+1;
				type[v]=i;
				next[v]=xid[i][nv]+1;
			}
		}
	}
	dp[v]=res;
	return dp[v];
}

int main(void){
	memset(dp,-1,sizeof(dp));
	cin >> str;
	n=str.size();
	dp[n]=1;
	for(int i=0;i<n;i++){
		xid[str[i]-'a'].push_back(i);
	}
	for(int i=0;i<26;i++){
		xid[i].push_back(n);
	}
	solve(0);
	int now=0;
	string res="";
	while(now<n){
		res+=('a'+type[now]);
		now=next[now];
	}
	cout << res << endl;
	return 0;
}

