string decode(ll x){
	string ret = "";
	if(x < 26){
		ll add = x % 26;
		ret += 'a' + add;
		return ret;
	}
	while(x > 0){
		if(x >= 26){
			ll add = x % 26;
			ret += 'a' + add;
			x /= 26;
		}else{
			ll add = x % 26;
			ret += 'a' + add - 1;
			x /= 26;
		}
	}
	reverse(ret.begin(), ret.end());
	return ret;
}

