void precalc() {
  int sz = SIZE(s);
  for( int i = 0; i < A; ++i ) {
    nxt[ i ][ sz ] = -1;
  }
  for( int i = sz-1; i >= 0; --i ) {
    for( int j = 0; j < A; ++j ) {
      nxt[ j ][ i ] = nxt[ j ][ i+1 ];
    }
    nxt[ s[i]-'a' ][ i ] = i+1;
  }
}

void solve() {
  int sz = SIZE(s);
  for( int i = sz; i >= 0; --i ) {
    dp[ i ] = oo;
    for( int j = 0; j < A; ++j ) {
      if( nxt[ j ][ i ] == -1 ) dp[ i ] = 1;
      else dp[ i ] = min( dp[i], dp[ nxt[ j ][ i ] ]+1 );
    }
  }
}

void get_ans( int cur ) {
  for( int i = 0; i < A; ++i ) {
    if( nxt[ i ][ cur ] == -1 ) {
      ans.PB( 'a'+i );
      return;
    }
    else if( dp[ cur ] == dp[ nxt[ i ][ cur ] ]+1 ) {
      ans.PB( 'a'+i );
      return get_ans( nxt[ i ][ cur ] );
    }
  }
}

