	int getfa( int pos ){
		if( dsu[pos] == pos ) return pos;
		return dsu[pos] = getfa( dsu[pos] );
	}
	bool unite( int a , int b ){
		a = getfa( a );
		b = getfa( b );
		if( a == b ) return 0;
		dsu[a] = b;
		return 1;
	}
};
