void _main()
{
    string s; CIN(s);
    ll n = s.size();

    S ll sumacnts[200005][26];
    memset(sumacnts, 0, sizeof(sumacnts));
    rep (i, n) {
        memcpy(sumacnts[i+1], sumacnts[i], sizeof(sumacnts[i+1]));
        sumacnts[i+1][s[i]-'a']++;
    }

    S ll cnts[200005];
    memset(cnts, 0, sizeof(cnts));
    S ll nidxs[200005];
    S ll acnts[256];
    memset(acnts, 0, sizeof(acnts));
    ll nidx = n;

    rrep (i, n) {
        while (acnts_min(acnts)) {
            nidx--;
            acnts[s[nidx]]--;
        }
        nidxs[i] = nidx;
        cnts[i] = cnts[nidx] + 1LL;
        acnts[s[i]]++;
    }

    ll nowidx = n;
    memset(acnts, 0, sizeof(acnts));

    rep (i, n) {
        acnts[s[i]]++;
        if (acnts_min(acnts)) {
            nowidx = i;
            break;
        }
    }

    debug_printf("---- first nowidx=%lld\n", nowidx);

    string ans;
    ll previdx = - 1LL;
    S ll subcnts[26];
    memset(subcnts, 0, sizeof(subcnts));

    while (nowidx < n) {
        ll cnt = cnts[nowidx];
        char c = s[nowidx];
        previdx = nowidx;

        rrep (i, nowidx) {
            if (cnts[i] != cnt) break;
            if (subcnts[s[i]-'a']) continue;
            if (s[i] <= c) {
                c = s[i];
                previdx = i;
            }
        }

        rep (i, 26) subcnts[i] = sumacnts[nowidx][i] - sumacnts[previdx][i];

        ans += c;
        nowidx = nidxs[previdx];
        debug_printf("c=%c idx=%lld n=%lld\n", c, previdx, nowidx);
    }

    S bool disable[256];
