constexpr common_type_t<M,N> gcd(M a,N b){
    a=abs(a);b=abs(b);
    if(a < b) return gcd(b, a);
    M r;
    while ((r=a%b)) {
        a = b;
        b = r;
    }
    return b;
}
template<class M,class N>
constexpr common_type_t<M,N> lcm(M a,N b){
    return a*b/gcd(a,b);
