string back(int u, int last) {
	stack<char> S;
	while (u) {
		S.push(str[u - 1]);
		u = pre[u];
	}
	string ans;
	while (!S.empty()) {
		ans += S.top();
		S.pop();
	}
	ans += 'a' + last;
	return ans;
}

string bfs() {
	queue<int> Q;
	Q.push(0);
	while (!Q.empty()) {
		int u = Q.front();
		Q.pop();
		for (int i = 0; i < N; i++) {
			int v = graph[u][i];
			if (v == -1) return back(u, i);
			if (pre[v] == -1) {
				pre[v] = u;
				Q.push(v);
			}
		}
	}
}

bool solve(int testNumber) {
	if (!(cin >> str)) return false;
	int n = str.size();
	graph.assign(n + 1, vector<int>(N));
	vector<int> nex(N, -1);
	pre.assign(n + 1, -1);
	for (int i = n; i >= 0; i--) {
		for (int j = 0; j < N; j++) graph[i] = nex;
		if (i) nex[str[i - 1] - 'a'] = i;
	}
	string ans = bfs();
	printf("%s\n", ans.c_str());
	return true;
}

void init(const char *in = nullptr, const char *out = nullptr) {
	if (in) freopen(in, "r", stdin);
	if (out) freopen(out, "w", stdout);
}

int main() {
	ios_base :: sync_with_stdio(false);
	cin.tie(nullptr);
	init();
	for (int i=1; solve(i); i++);
	return 0;
}

