string s;
int freq[ALPH_SIZE];
bool processed[ALPH_SIZE];
bool is_option[10000][26];
vector<int> children[10000][26];
int child[10000][26];

bool check_zero()
{
    for0(i,ALPH_SIZE) {
        if (freq[i] == 0)
            return true;
    }
    return false;
}

void process_segment(int seg, int i, int j)
{
    ms(processed,false);
    for (int k=i; k<j; k++) {
        int c = s[k]-'a';
        freq[c]--;
        if (not processed[c] and check_zero()) {
            is_option[seg][c] = true;
            for0(c2,ALPH_SIZE) {
                if (freq[c2] == 0)
                    children[seg][c].pb(c2);
            }
        }
        processed[c] = true;
    }
}


string search(int num_segs)
{    
    ms(child,-1);
    for (int seg=num_segs-2; seg>=0; seg--) {
        for0(c,ALPH_SIZE) {
            if (is_option[seg][c]) {
                bool found = false;
                iter(children[seg][c]) {
                    if (is_option[seg+1][*it]) {
                        found = true;
                        child[seg][c] = *it;
                        break;
                    }
                }
                if (!found)
                    is_option[seg][c] = false;
            }
        }
    }
    print2D(is_option,num_segs,ALPH_SIZE)
    print2D(child,num_segs,ALPH_SIZE)

    string ret = "";
    int cur;
    for0(c,ALPH_SIZE) {
        if (is_option[0][c]) {
            cur = c;
            break;
        }
    }
    for (int seg=0; seg<num_segs; seg++) {
        ret += 'a'+cur;
        cur = child[seg][cur];
    }
    return ret;
}

int32_t main()
{
    #ifdef DEBUG
    freopen("C.txt","r",stdin);
    //freopen("","w",stdout);
    #endif

    ms(is_option,false);
    cin >> s;
    int n = s.length();

    int i = 0;
    bool done = false;
    int seg = 0;

    while (i < n) {
        ms(freq,0);
        int j = i;

        done = false;
        while (j < n and not done) {
            freq[s[j]-'a']++;
            j++;
            done = not check_zero();
        }
        pr(i) pr(j) nl
        pr(s.substr(i,j-i)) nl

        if (done) {
            process_segment(seg,i,j);  
        }
        else {
            for0(c,ALPH_SIZE) {
                if (freq[c] == 0)
                    is_option[seg][c] = true;
            }
        }

        i = j;
        seg++;
    }

    if (done) {
        for0(c,ALPH_SIZE) 
            is_option[seg][c] = true;
        seg++;
    }

    print2D(is_option,seg,ALPH_SIZE)
    string ans = search(seg);    
    cout<<ans<<endl;
    return 0;
}

