#define N 200000

using namespace std;

string s,dp[N];
ll n;
bool vis[N];
ll seg[4*N][26];

void build(ll low,ll high,ll pos,ll id)
{
    if(low == high)
    {
        seg[pos][id] = (ll)(s[low]-'a' == id);
        return;
    }

    ll mid = (low+high)/2;
    build(low,mid,pos*2+1,id);
    build(mid+1,high,pos*2+2,id);

    seg[pos][id] = seg[pos*2+1][id]+seg[pos*2+2][id];
    return;
}

ll first_occurence(ll low,ll high,ll pos,ll slow,ll id)
{
    ll mid = (low+high)/2;

    if(seg[pos][id] == 0)
        return n;

    if(low >= slow)
    {
        if(low == high)
            return low;
        if(seg[pos*2+1][id] > 0)
            return first_occurence(low,mid,pos*2+1,slow,id);
        return first_occurence(mid+1,high,pos*2+2,slow,id);
    }
    if(high < slow)
        return n;

    return min(first_occurence(low,mid,pos*2+1,slow,id),first_occurence(mid+1,high,pos*2+2,slow,id));
}

string mini(string a,string b)
{
    if(a.size() == b.size())
        return min(a,b);

    if(a.size()<b.size())
        return a;
    return b;
}

string calc(ll cur)
{
    if(cur == n)
        return "a";

    if(vis[cur])
        return dp[cur];

    vis[cur] = true;
    dp[cur] = "";
    string tmp = "z";
    string CH = "z";
    tmp[0]++;

    rep(i,0,n)
        dp[cur]+=tmp;

    rep(i,0,26)
    {
        CH[0] = (char)(i+'a');
        ll goes = first_occurence(0,n-1,0,cur,i);

        string epo = "";

        if(goes < n)
            epo = calc(goes+1);

     //   cout << cur << ": " << goes << " " << CH << " " << epo << endl;

   /*     if(cur == 0)
            cout << cur << " " << goes << " " <<CH << " " << epo << endl;
*/
        dp[cur] = mini(dp[cur],CH+epo);
    }

    return dp[cur];
}

int main()
{
    cin >> s;
    n = s.size();

    rep(i,0,26)
        build(0,n-1,0,i);

    cout << calc(0) << "\n";
    return 0;
}

