static const int INF = (1 << 28);

int main() {
    string A;
    cin >> A;

    int N = A.size();
    vector<int> indexes[26];

    for (int i = 0; i < N; i++) {
        indexes[A[i] - 'a'].push_back(i + 1);
    }
    for (int i = 0; i < 26; i++) {
        indexes[i].push_back(N + 1);
    }

    vector<int> table(N + 2, INF);  // A_[i,N]に含まれない最小の部分列の長さ(iは1-indexed)
    table[N + 1] = 0;

    for (int i = N; i >= 0; i--) {
        for (int j = 0; j < 26; j++) {
            int idx = *upper_bound(indexes[j].begin(), indexes[j].end(), i);
            table[i] = min(table[i], table[idx] + 1);
        }
    }

    int idx = 0;
    string ans = "";
    while (idx != N + 1) {
        int nidx = -1;
        char alphabet;

        for (int i = 0; i < 26; i++) {
            int foo = *upper_bound(indexes[i].begin(), indexes[i].end(), idx);
            if (nidx < 0 or table[nidx] > table[foo]) {
                nidx = foo;
                alphabet = char('a' + i);
            }
        }
        idx = nidx;
        ans.push_back(alphabet);
    }

    cout << ans << endl;

    return 0;
}

