void add(long long &a, long long b) {
	a += b;
	if(a >= mod)a -= mod;
	else if(a < 0)a += mod;
}
void calc(int len) {
	for(int i = n; i; --i) {
		for(int j = 0; j < 26; ++j) {
			if(nxt[i][j])add(sump[len][i], dp[len][nxt[i][j]]);
