        for (int j = 0; j < 26; j++){
            int p = lower_bound(a[j].begin(), a[j].end(), l + 1) - a[j].begin();
            if (dp[a[j][p] + 1] + 1 == t){
                ans += ('a' + j);
                l = a[j][p] + 1;
                break;
            }
        }
    }
    cout << ans;
