int dfs( int pos ){
	if( mem[pos] != -1 ) return mem[pos];

	int ans = INF;
	for( int i = 0 ; i < 26 ; i++ ){
		if( nextapp[pos][i] >= n + 1 ){
			ans = 1;
			tran[pos] = i;
			return mem[pos] = 1;
		}
		int ret = dfs( nextapp[pos][i] ) + 1;
		if( ans > ret ){
			ans = ret;
			tran[pos] = i;
		}
	}

	return mem[pos] = ans;
}

