struct path {
  int sz, to;
  char c;

  path(int sz, int to, char c = 0) : sz(sz), to(to), c(c) {}
};

path zero(3e5, -1);

void calc(Graph<int> &pos, vector<path> &dp, int pre, int i, char c) {
  rep(j,26) {
    auto itr = lower_bound(ALL(pos[j]), pre);

    if (*itr == -1) {
      if (zero.sz < dp[i].sz + 1) continue;
      if (zero.sz == dp[i].sz + 1 && zero.c < c) continue;

      zero = {dp[i].sz + 1, i, c};
    }

    else if (pre <= *itr) {
      if (dp[*itr].sz < dp[i].sz + 1) continue;
      if (dp[*itr].sz == dp[i].sz + 1 && dp[*itr].c < c) continue;

      dp[*itr] = {dp[i].sz + 1, i, c};
    }
  }
}

void solve() {
  string s; cin >> s;

  Graph<int> pos(26, vi(1, -1));
  int sz = s.size();
  rep(i,sz) {
    pos[s[i]-'a'].emplace_back(i);
  }

  vector<path> dp(sz+1, path(3e5, sz));
  dp[sz] = {0, -1};

  rep(i,26) {
    if (pos[i].back() == -1) {
      cout << char('a' + i) << endl;
      return;
    }

    dp[sz].c = 'a' + i;
    calc(pos, dp, pos[i].back(), sz, dp[sz].c);
  }

  zero.to = sz;

  rrep(i,sz) {
    auto pre = lower_bound(ALL(pos[s[i]-'a']), i); --pre;
    calc(pos, dp, *pre, i, s[i]);
  }

  int idx = zero.to;
  string ans;
  ans.push_back(zero.c);

  while (idx != sz) {
    ans.push_back(dp[idx].c);
    idx = dp[idx].to;
  }

  cout << ans << endl;
}


