using namespace std;

const int N = 2e5+15;
const int M = 26;
const int G = N*M;
int Next[N][M];

int par[G];

char isChar[G];
void solve(){
   string s;
   cin>>s;
   int n = s.size();
   for(int j = 0;j<M;++j) {
      Next[n+1][j] = n+1;
   }
   for(int i=n;i>=0;--i){
      for(int j = 0;j<M;++j){
         Next[i][j] = Next[i+1][j];
      }
      if(i+1<=n){
         int g = s[i] - 'a';
         Next[i][g] = i+1; 
      }
   }
   int nodeNum = 1;
   queue<pair<int,int> > q;
   q.push(make_pair(0,0));
   int x,newNode,cur,ncur;
   string ret;
   while(!q.empty()) {
      x = q.front().first;
      cur = q.front().second;
      q.pop();
      for(int i=0;i<26;++i) {
         newNode = nodeNum++;
         ncur = Next[cur][i];
         par[newNode] = x;
         isChar[newNode] = char('a'+i);

         if(ncur>n) {
            while(newNode>0) {
               ret += isChar[newNode];
               newNode = par[newNode];
            }
            reverse(ret.begin(),ret.end());
            cout<<ret<<endl;
            return;
         } else {
            q.push(make_pair(newNode,ncur));
         }
      }
   }
}
int main() {
   //freopen("input.txt","r",stdin);
   solve();
}

