using namespace std;
char s[2050000];
bool vis[30];
int cnt=0;
int dp[2050000];
char ans[2050000];
int tot=0;
int main(){
	memset(ans, 0, sizeof(ans));
	scanf("%s", s+1);
	int n=strlen(s+1);
	reverse(s+1, s+1+n);
	dp[0]=1;
	for(int i=1;s[i];i++){
		if(!vis[s[i]-'a']){
			vis[s[i]-'a']=true;
			cnt++;
			if(cnt==26){
				memset(vis, false, sizeof(vis));
				cnt=0;
				dp[i]=dp[i-1]+1;
				continue;
			}
		}
		dp[i]=dp[i-1];
	}
	memset(vis, false, sizeof(vis));
	if(dp[n]!=dp[n-1]){
		for(int i=1;i<=dp[n];i++)printf("a");
		printf("\n");
	}
	else if(dp[n]==1){
		memset(vis, false, sizeof(vis));
		for(int i=1;i<=n;i++){
			vis[s[i]-'a']=true;
		}
		for(int i=0;i<26;i++){
			if(!vis[i]){
				printf("%c\n",i+'a');
				break;
			}
		}
	}
	else{
		int tot=0;
		for(int i=n;i>=1;i--){
			if(dp[i]!=dp[i-1]){tot=i;break;}
			vis[s[i]-'a']=true;
		}
		int last=0;
		for(int i=0;i<26;i++)if(!vis[i]){
			ans[dp[n]]=i+'a';
			last=i;
			break;
		}
		memset(vis, false, sizeof(vis));
		for(int i=tot, j=dp[n]-1;i>=1;i--){
			if(s[i]-'a'==last){
				memset(vis, false, sizeof(vis));
				int cnt=0;
				while(i>=0&&dp[i]==dp[i-1]){
					if(cnt!=0)vis[s[i]-'a']=1;
					cnt++;
					i--;
				}
				for(int k=0;k<26;k++){
					if(!vis[k]){
						ans[j]=k+'a';
						last=k;
						break;
					}
				}
				i++;
				j--;
			}
		}

		for(int i=dp[n];i>=1;i--)printf("%c", ans[i]);
		printf("\n");
	}
}

