using namespace std;

int cnt[26];
char S[200010];
int group[200010];
int N;
vector<int> pos[26];
vector<char> answer;

int main() {
  memset(S,0,sizeof(S));
  memset(cnt,0,sizeof(cnt));
  scanf("%s", S);
  N= strlen(S);
  for(int i=0;i<N;++i) {
    S[i]= S[i]-'a';
  }
  int gid=0;
  group[N]=-1;
  for(int i=N-1;i>=0;--i) {
    group[i] = gid;
    cnt[S[i]] ++;
    bool no=false;
    for(int j=0;j<26;++j) {
      if(cnt[j] ==0){
        no=true;
      }
    }
    if (!no) {
      gid++;
      memset(cnt,0,sizeof(cnt));
    }
  }
  for(int i=0;i<N;++i) {
    pos[S[i]].push_back(i);
  }
  for(int i=0;i<26;++i) {
    pos[i].push_back(N);
  }
  int currentPos=-1;
  for(int i=gid;i>=0;--i) {
    for(int j=0;j<26;++j) {
      int nextPos=*lower_bound(pos[j].begin(), pos[j].end(), currentPos+1);
      if (group[nextPos]==i-1) {
        currentPos = nextPos;
        answer.push_back('a' + j);
        break;
      }
    }
  }
  for(int i=0;i<answer.size();++i) {
    printf("%c", answer[i]);
  }
  printf("\n");

  return 0;
}

