#include <bits/stdc++.h>
using namespace std;

vector<int> idxs[26];
vector<vector<int>> nxt;
void build_nxt(string &s) {
    int n = s.size();
    nxt.assign(n, vector<int>(26, -1));
    for (int i = 0; i < n; ++i) {
        idxs[s[i] - 'a'].emplace_back(i);
    }
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < 26; ++j) {
            auto itr = lower_bound(idxs[j].begin(), idxs[j].end(), i + 1);
            if (itr == idxs[j].end()) continue;
            nxt[i][j] = *itr;
        }
    }
}

string decode(int k, int n) {
    string ret;
    for (int i = 0; i < n; ++i) {
        ret += (char)('a' + k % 26);
        k /= 26;
    }
    reverse(ret.begin(), ret.end());
    return ret;
}

void fin(int k, int n) {
    cout << decode(k, n) << endl;
    exit(0);
}

void solve(string &s, int k) {
    int n = s.size(), mx = 1;
    for (int i = 0; i < k; ++i) mx *= 26;
    for (int i = 0; i < mx; ++i) {
        int cur = i;
        vector<int> v;
        for (int j = 0; j < k; ++j) {
            v.emplace_back(cur % 26);
            cur /= 26;
        }
        reverse(v.begin(), v.end());
        // cout << decode(i, k) << endl;
        if (idxs[v.front()].size() == 0) fin(i, k);
        cur = idxs[v.front()].front();
        for (int j = 1; j < k; ++j) {
            cur = nxt[cur][v[j]];
            if (cur == -1) fin(i, k);
        }
    }
}

signed main() {
    string S; cin >> S;
    build_nxt(S);
    int N = S.size();
    for (int i = 1; i <= 10; ++i) solve(S, i);
}

