int dp[MAX];
int ne[MAX];

string solve() {
    for (int i = 0; i < str.size(); ++i) {
        int id = str[i] - 'a';
        place[id].push_back(i);
    }
    for (int i = 0; i < 26; ++i) {
      char c = 'a' + i;
      string res = ""; res += c;
      if (place[i].empty()) return res;
    }
    for (int i = 0; i < str.size(); ++i) {
      for (int j = 0; j < 26; ++j) {
	int it = upper_bound(place[j].begin(), place[j].end(), i) - place[j].begin();
	if (it == place[j].size()) nextc[i][j] = -1;
	else nextc[i][j] = place[j][it];
      }
    }

    for (int i = 0; i < MAX; ++i) dp[i] = 1<<29, ne[i] = -1;
    dp[(int)str.size() - 1] = 2;
    for (int i = (int)str.size() - 2; i >= 0; --i) {
      for (int j = 0; j < 26; ++j) {
	if (nextc[i][j] != -1) {
	  if (chmin(dp[i], dp[nextc[i][j]] + 1)) {
	    ne[i] = j;
	  }
	}
	else {
	  if (chmin(dp[i], 2)) {
	    ne[i] = j;
	  }
	}
      }
      //cout << i << ": " << dp[i] << endl;
    }

    string res = "";
    int Min = 1<<29;
    int MinI = -1;
    for (int j = 0; j < 26; ++j) {
      int ind = nextc[0][j];
      if (str[0] == (char)('a' + j)) ind = 0;
      if (chmin(Min, dp[ind])) {
	MinI = ind;
      }
    }
    res += str[MinI];
    do {
      int ch = ne[MinI];
      res += (char)('a' + ch);
      MinI = nextc[MinI][ch];
    } while (MinI != -1);

    return res;
}


