void update(const string& s1,string& s2){
    if(s2 == "#"){ s2 = s1; }
    else if(s1.length() < s2.length()){ s2 = s1; }
    else if(s1.length() == s2.length()){ s2 = min(s1,s2); }
    return ;
}
string solve(){
    string res = "#";
    string A; cin >> A;
    vector<vector<int>> loc(26);
    for(int i = 0; i < A.length();i++) loc[A[i]-'a'].push_back(i+1);
    vector<string> dp(A.length()+1,"#");
    dp[0] = "";
    for(int i = 0; i < A.length();i++){
        for(int j = 0; j < 26;j++){
            auto it = upper_bound(loc[j].begin(), loc[j].end(),i);
            if(it == loc[j].end()) { update(dp[i] + char(j + 'a'),res); }
            else{ update(dp[i] + char(j + 'a'),dp[*it]); }
        }
    }
    return res;
}
int main(void) {
	cin.tie(0); ios::sync_with_stdio(false);
    cout << solve() << endl;
	return 0;
}

