vector<int> dt[26];
int dp[100001][26];
int nx[100001][26];
int n;
string s;
int solve(int in, int c){
  if(in == n)
    return 1;
  if(dp[in][c] != -1)
    return dp[in][c];
  auto it = lower_bound(dt[c].begin(), dt[c].end(), in);
  if(it == dt[c].end())
    return 1;
  int mn = 100000;
  for(int i = 0;i < 26;i++){
    if(1 + solve(*it + 1, i) < mn){
      mn = 1 + solve(*it + 1, i);
      nx[in][c] = i;
    }
  }
  return dp[in][c] = mn;
}
void recon(int in, int c){
  cout << char(c + 'a');
  auto it = lower_bound(dt[c].begin(), dt[c].end(), in);
  if(it == dt[c].end())
    return;
  recon(*it + 1, nx[in][c]);
}
