string solve(string& A) {
    int L = A.size();
    vvi az(26);
    rep(i,L) {
        int ch = A[i] - 'a';
        az[ch].pb(i);
    }
#ifdef DEBUG
    rep(ch,26){
        cerr << (char)('a'+ch) << " " << az[ch] << endl;
    }
#endif

    vector<int> rev(L);
    set<int> abc;
    int k = 0;
    for (int i=L-1; i>=0; --i) {
        abc.insert(A[i] - 'a');
        rev[i] = k;
        if (abc.size() == 26) {
            ++k;
            abc.clear();
        }
    }
#ifdef DEBUG
    cerr << rev << endl;
#endif
    int len = k+1;

    vector<char> ans(len);
    rep(ch,26) {
        if (!found(abc, ch)) {
            ans[0] = ch;
            if (az[ch].empty()) {
                ans[0] += 'a';
                return string(ALL(ans));
            }
            break;
        }
    }

    int last = az[ans[0]][0];
    // cerr << last << endl;
    rep1(i,k) {
        rep(ch,26) {
            auto it = lower_bound(ALL(az[ch]), last+1);
            if (it != az[ch].end()) {
                int at = *it;
                if (rev[last]-1 != rev[at]) continue;
                last = at;
            }
            ans[i] = ch; break;
        }
    }

    rep(i, len) ans[i] += 'a';
    return string(ALL(ans));
}

