const int MR = 26;
const int MS = 2e5 + 10;

vector<int> pos[MR];

char s[MS];

bool done[MS];

string bfs()
{
	vector<PII> Q;
	Q.push_back(MP(-1, -1));

	int p = 0;

	while (true)
	{
		auto akt = Q[p]; p++;

		REP(i, MR)
		{
			int wsk = upper_bound(pos[i].begin(), pos[i].end(), akt.first) - pos[i].begin();
			if (wsk == pos[i].size())
			{
				string res = "";
				res += i + 'a';
				int tmp = akt.first;
				while (tmp != -1)
				{
					res += s[tmp];
					akt = Q[akt.second];
					tmp = akt.first;
				}

				reverse(res.begin(), res.end());

				return res;
			}

			if (!done[pos[i][wsk]])
			{
				Q.push_back(MP(pos[i][wsk], p - 1));
				done[pos[i][wsk]] = 1;
			}
		}
	}

	return "";
}

