#include <bits/stdc++.h>

#define MAX_LEN_A 200000

using namespace std;

string A;
int N;
int pangram[MAX_LEN_A]; // pangram[i] = min { j | {A[i], A[i+1],..., A[j-1]} includes {a, b,...,z} }
                        // if there does not exist such j, pangram[i] = -1
int first[MAX_LEN_A+1][26]; // first[i][j] == min { k | k >= i, A[k] == c[j] }

void setPangram()
{
    for (int i = 0; i < N; i++) {
        pangram[i] = -1;
    }
    int count[26];
    for (int i = 0; i < 26; i++) {
        count[i] = 0;
    }
    int res = 26;
    for (int i = 0; i < N; i++) {
        count[A[i]-'a']++;
        if (count[A[i]-'a'] == 1) {
            res--;
            if (res == 0) {
                pangram[0] = i + 1;
                break;
            }
        }
    }
    if (res > 0) {
        return;
    }
    for (int i = 1; i < N; i++) {
        count[A[i-1]-'a']--;
        if (count[A[i-1]-'a'] == 0) {
            for (int j = pangram[i-1]; j < N; j++) {
                count[A[j]-'a']++;
                if (A[j] == A[i-1]) {
                    pangram[i] = j + 1;
                    break;
                }
            }
            if (pangram[i] == -1) {
                return;
            }
        } else {
            pangram[i] = pangram[i-1];
        }
    }
}

void setFirst()
{
    for (int i = 0; i <= N; i++) {
        for (int j = 0; j < 26; j++) {
            first[i][j] = N;
        }
    }
    for (int i = 0; i < N; i++) {
        first[i][A[i]-'a'] = i;
    }
    for (int i = N - 2; i >= 0; i--) {
        for (int j = 0; j < 26; j++) {
            first[i][j] = min(first[i][j], first[i+1][j]);
        }
    }
}

int f(int i)
{
    if (i >= N || pangram[i] == -1) {
        return 0;
    } else {
        return 1 + f(pangram[i]);
    }
}

string solve(int index, string s, int M)
{
    if (M == 0) {
        for (int i = 0; i < 26; i++) {
            if (first[index][i] == N) {
                char c = 'a' + i;
                return s + c;
            }
        }
    }
    for (int i = 0; i < 26; i++) {
        if (f(first[index][i]+1) == M - 1) {
            char c = 'a' + i;
            return solve(first[index][i]+1, s + c, M - 1);
        }
    }
    assert(0);
}

int main(void)
{
    cin >> A;
    N = A.size();
    setPangram();
    setFirst();
    string answer;
    int M = f(0) ; // answer.size() == M + 1
    answer = solve(0, "", M);
    cout << answer << endl;
    return 0;
}

