void Main() {
  auto s = rs();
  int n = sz(s);

  vi A(n);
  rep(i, n) A[i] = s[i] - 'a';

  const int AL = 26;

  vvi P(AL);

  rep(i, n) {
    P[A[i]].emplace_back(i);
  }

  rep(c, AL) {
    if (sz(P[c]) == 0) {
      cout << (char)('a'+c) << endl;
      return;
    }
  }

  const int inf = 1e9;

  vi dp(n, inf);
  vi fp(n);

  rrep(i, n) {
    rep(c, AL) {
      auto it = upper_bound(all(P[c]), i);
      if (it != P[c].end()) {
        int idx = *it;
        if (amin(dp[i], dp[idx] + 1)) {
          fp[i] = c;
        }
      }
      else {
        if (amin(dp[i], 1)) {
          fp[i] = c;
        }
      }
    }
  }

  out(dp);
  out(fp);

  vi ans;
  int pos;
  {
    int ma = inf, fir = -1;
    rep(c, AL) {
      if (amin(ma, dp[P[c][0]])) {
        fir = c;
        pos = P[c][0];
      }
    }
    ans.emplace_back(fir);
  }

  while (1) {
    int nex = fp[pos];
    ans.emplace_back(nex);

    auto it = upper_bound(all(P[nex]), pos);
    if (it == P[nex].end()) break;

    pos = *it;
  }
  out(ans);
  string z;
  forr(c, ans) {
    z += ('a'+c);
  }
  cout << z << endl;
}

