#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int n;
char str[200005];
int a[200005];
int t[200005][26];

bool check(int l,int r){
  for(int i=0;i<26;i++){
    if( t[r][i] - t[l][i] == 0 )return false;
  }
  return true;
}

int mem[200005];
int find(int x){
  if(mem[x]!=-1)return mem[x];
  int left=x+1,right=n,mid;
  while(left<right){
    mid=(left+right)/2;
    if( check(x, mid ) )right=mid;
    else left=mid+1;
  }
  return mem[x]=left;
}

int dp[200005];
int solve(int p){
  if(dp[p]!=-1)  return dp[p];
  if(!check(p,n))return dp[p]=1;
  int nex=find(p);
  return dp[p]=solve(nex)+1;
}

int main(){
  memset(mem, -1, sizeof(mem));
  memset(dp, -1, sizeof(dp));

  set<int> st[26];

  scanf("%s",str);
  n=strlen(str);
  for(int i=0;i<n;i++){
    a[i]=str[i]-'a';
    t[i+1][ a[i] ]++;

    st[ a[i] ].insert(i);
  }


  for(int i=1;i<=n;i++)
    for(int j=0;j<26;j++)
      t[i][j]+=t[i-1][j];

  int len=solve(0);
  int x=-1;
  string ans="";

  for(int i=0;i<len;i++){
    for(int ch=0;ch<26;ch++){
      set<int> :: iterator it = st[ch].upper_bound(x);
      if(it!=st[ch].end())
        if( (int)ans.size() + 1 + solve( (*it)+1 ) > len)continue;

      if(it!=st[ch].end())  x=*it;
      ans+= ('a'+ch);
      break;
    }
  }

  cout<<ans<<endl;
  return 0;  
}

