vector<vector<int>> calcNext(const string &S)
{
	int n = (int)S.size();
	vector<vector<int>> ret(n + 2, vector<int>(26, n + 1));
	for (int i = n - 1; i >= 0; i--) {
		for (int j = 0; j < 26; j++) {
			ret[i][j] = ret[i + 1][j];
		}
		ret[i][S[i] - 'a'] = i;
	}
	return ret;
}

void solve()
{
	string S; cin >> S;
	int n = S.size();
	auto next = calcNext(S);

	vector<int> dp(n + 1, INF);
	vector<int> rc(n + 1, 'a');

	//calc dp
	dp[n] = 1;
	for (int i = n - 1; i >= 0; i--) {
		for (int j = 0; j < 26; j++) {
			if (next[i][j] == n + 1) {
				dp[i] = 1;
				rc[i] = j + 'a';
			}
			else {
				if (dp[i] > dp[next[i][j] + 1] + 1) {
					dp[i] = dp[next[i][j] + 1] + 1;
					rc[i] = j + 'a';
				}
			}
		}
	}

	//recovery
	string ans = "";
	int ind = 0;
	while (ind <= n) {
		ans += rc[ind];
		ind = next[ind][rc[ind] - 'a'] + 1;
	}
	cout << ans << endl;
}

int main() {
	ios_base::sync_with_stdio(0); cin.tie(0); cout << fixed << setprecision(13);
	solve();
	return 0;
}

