int get_len (string &S, int pos) 
{
    if (pos == S.size()) return 0;
    bool used[26] = {};
    int cnt = 0;
    int ret = 1;
    for (int i = (int)S.size() - 1; i >= pos; i--) {
        if (!used[S[i] - 'a']) {
            used[S[i] - 'a'] = true;
            cnt++;
        }
        if (cnt == 26) {
            fill (used, used + 26, false);
            cnt = 0;
            ret++;
        }
    }
    return ret;
}

