                } else {
                    ord.push_back(make_pair(0, make_pair(c, (int)A.size())));
                }
            }
        }
        sort(ord.begin(), ord.end());
        ans.push_back(ord.front().second.first);
        acc = ord.front().second.second;
    }

    cout << ans << endl;

    return 0;
}

