/*
<url:https://arc081.contest.atcoder.jp/tasks/arc081_c>
問題文============================================================
 文字列 S に対して，その文字列を構成する文字を 0 文字以上取り除き，
 残った文字を元の順番で並べて得られる文字列を S の部分列と呼びます．
 たとえば，arc や artistic や (空文字列) は artistic の部分列ですが，
 abc や ci は artistic の部分列ではありません．

 英小文字からなる文字列 A が与えられます．
 このとき，英小文字からなる文字列で，A の部分列ではないようなもののうち，最も短いものを求めてください．
 ただし，そのようなものが複数ある場合には，辞書順で最小のものを求めてください．
=================================================================

解説=============================================================

================================================================
*/

void update(const string& s1,string& s2){
    if(s2 == "#"){ s2 = s1; }
    else if(s1.length() < s2.length()){ s2 = s1; }
    else if(s1.length() == s2.length()){ s2 = min(s1,s2); }
    return ;
}

bool check(const string& s1,const string& s2){
    if(s1 == "#" || s2 == "#") return false;
    else if(s1.length() < s2.length()) return false;
    return true;
}
string solve(){
    string res = "#";
    string A; cin >> A;
    vector<vector<int>> loc(26);
    for(int i = 0; i < A.length();i++) loc[A[i]-'a'].push_back(i+1);
    vector<string> dp(A.length()+1,"#");
    dp[0] = "";
    for(int i = 0; i <= A.length();i++){
        if(check(dp[i],res)) continue;
        for(int j = 0; j < 26;j++){
            auto it = upper_bound(loc[j].begin(), loc[j].end(),i);
            if(it == loc[j].end()) {
                if(dp[i] != "#") update(dp[i] + char(j + 'a'),res);
            }
            else { if(dp[i] != "#")update(dp[i] + char(j + 'a'),dp[*it]); }
        }
    }
    return res;
}
int main(void) {
	cin.tie(0); ios::sync_with_stdio(false);
    cout << solve() << endl;
	return 0;
}

