typedef pair<int,int> pii;
vector<pii> V;
int cnt[30];

int cal(int l, int r, char ch){
	for(int i=l; i<=r; i++){
		if(ch == s[i]){
			memset(vis, 0, sizeof(vis));
			for(int k=i+1; k<=r; k++){
				vis[s[k]-'a'] = 1;
			}
			for(int i=0; i<26; i++){
				if(!vis[i]){
					return i + 'a';
				}
			}
			return -1;
		}
	}
	return 'a';
}

int main(){
	scanf("%s", s);
	n = strlen(s);
	memset(vis, 0, sizeof(vis));
	m = 0;
	p = 0;
	int x;
	for(int i=0; i<n; i++){
		x = s[i] - 'a';
		if(!vis[x]){
			vis[x] = 1;
			m++;
		}
		if(m == 26){
			V.push_back(make_pair(p, i));
			p = i + 1;
			m = 0;
			memset(vis, 0, sizeof(vis));
		}
	}
	V.push_back(make_pair(p, n-1));
	p = V.size();
	for(int i=0; i<26; i++){
		if(!vis[i]){
			t[p - 1] = 'a' + i;
