			}
			x = cal(V[i-1].first, V[i-1].second, t[i-1]);
			if(x == -1){
				flag = 1;
				break;
			}
			t[i] = x;
		}
		if(!flag){
			t[p] = '\0';
			break;
		}
	}
	puts(t);
	return 0;
