	rep(i,len[0]){
		for(char c='a';c<='z';c++){
			int p=*lower_bound(pos[c].begin(),pos[c].end(),idx);
			if(p==n || len[p+1]==len[0]-i-1){
				idx=p+1;
				ans+=c;
				break;
			}
		}
	}
	cout<<ans<<endl;

	return 0;
}

