bool good(string s){
  if(dt[s[0] - 'a'][0] >= dt[s[2] - 'a'].back() - 1)
    return false;
  auto it = upper_bound(dt[s[1] - 'a'].begin(), dt[s[1] - 'a'].end(), dt[s[0] - 'a'][0]);
  if(it == dt[s[1] - 'a'].end() || *it >= dt[s[2] - 'a'].back())
    return false;
  return true;
}
