const int N=200005;
int n,val[N],nxt[N],pre[N],cnt2[N][26];
string s;
bool done[N];
int main()
{
  std::ios::sync_with_stdio(false);
  cin.tie(NULL) ; cout.tie(NULL) ;
  string s;
  cin>>s; n=sz(s);
  s="#"+s;
  rep(i,1,n+1)
    {
      rep(j,0,26) cnt2[i][j]=cnt2[i-1][j];
      cnt2[i][s[i]-'a']++;
    }
  set<int> tmp;
  int ans=0;
  rep(i,1,n+1)
    {
      int j=i;
      while(j<=n && sz(tmp)<26)
	{
	  tmp.insert(s[j]-'a');
	  j++;
	}
      if(sz(tmp)==26) ans++;
      tmp.clear();
      i=j-1;
    }
  int cnt=0;
  repv(i,1,n+1)
    {
      int j=i;
      while(j>=1 && sz(tmp)<26)
	{
	  val[j]=cnt;
	  nxt[j]=i+1;
	  tmp.insert(s[j]-'a');
	  j--;
	}
      if(sz(tmp)==26) cnt++;
      tmp.clear();
      i=j+1;
    }
  val[0]=ans;
  int rem=ans,taken=0;
  string ret="";
  rep(i,1,n+1)
    {
      int c=s[i]-'a';
      if(val[i]==rem || pre[c]>taken)
	{
	  pre[c]=i;
	  continue;
	}
      rep(j,0,26) done[j]=false;
      vector<ii> valid;
      rep(j,i,nxt[i])
	{
	  c=s[j]-'a';
	  bool ok=false;
	  rep(k,0,26)
	    if(cnt2[nxt[j]-1][k]-cnt2[j][k]==0) ok=true;
	  if(ok && pre[c]<=taken && !done[c]) valid.pb(mp(c,j));
	  done[c]=true;
	}
      sort(all(valid));
      assert(sz(valid)>0);
      taken=valid[0].se;
      ret+=(char)(valid[0].fi+'a');
      rep(j,i,nxt[i])
	pre[s[j]-'a']=j;
      rem--;
    }
  rep(i,0,26)
    if(pre[i]<=taken)
      {
	ret+=(char)(i+'a');
	break;
      }
  assert(sz(ret)==ans+1);
  cout<<ret<<endl;
  return 0 ;
}

