			dp[n - 1][i] = alph.substr(i, 1) + 'a';
		else dp[n - 1][i] = alph[i];
	}

	auto min_str = [](string a, string b) {
		if (a.size() < b.size()) {
			return a;
		}
		else {
			return min(a, b);
		}
	};
	rrep(i, 0, n-1) {
		rrep(c, 0, 26) {
			if (next[i][c] == n) dp[i][c] = alph[c];
			else {
				auto k = next[i][c];
				if (k+1 == n) {
					dp[i][c] = dp[k][c];
				}
				else {
					dp[i][c] = dp[k + 1][0];
					rep(d, 1, 26) {
						dp[i][c] = min_str(dp[k + 1][d], dp[i][c]);
					}
					dp[i][c] = alph.substr(c, 1) + dp[i][c];
				}
			}
		}
	}

	string res= dp[0][0];

	rep(d, 1, 26) {
			res = min_str(dp[0][d], res);
	}
	cout << res;

	return 0;
}

