pair<int,int> check(string s, int start){
  int n = s.size();

  int t = 0;
  int p = 0;
  int q = -1;

  for(int i=start;i<n;i++){

    t |= 1 << (s[i]-'a');

    if(t == (1 << 26)-1){
      p++;
      t = 0;

      if(q == -1) q = i;      
    }
  }

  return {p,q};
}

int main(){
  string s;
  int n;

  cin >> s;

  n = s.size();

  auto res = check(s,0);
  int len = res.first + 1;
  int r = res.second;
  int l = 0;
  string ans = "";

  for(int i=0;i<len;i++){

    if(i + 1  == len){
      int t = 0;
      for(int j=l;j<n;j++){
        t |= 1 << (s[j]-'a'); 
      }

      for(int j=0;j<26;j++){
        if(!(t & (1 << j))){
          ans += "a";
          ans[ans.size()-1] += j;
          break;
        }
      }

      continue;
    }

    bool flag = false;
    bool used[26] = {};

    for(int j=0;j<26;j++){

      for(int k=l;k<=r;k++){
        if(s[k] - 'a' == j && !used[j]){
          used[j] = true;
          auto res = check(s, k+1);
          if(res.first + 2 + i == len){
            ans += "a";
            ans[ans.size()-1] += j;
            l = k + 1;
            r = res.second;
            flag = true;
          }
          break;
        }
      }

      if(flag) break;
    }
  }

  cout << ans << endl;

  return 0;
}

