int main() {
  char buf[262144];
  scanf("%s", buf);
  std::string s = buf;
  size_t n = s.length();

  constexpr size_t sigma = 26;
  std::bitset<sigma> bs;

  std::vector<int> dp(n+1);
  dp[n] = 1;
  for (size_t i = n; i--;) {
    dp[i] = dp[i+1];
    bs.set(s[i]-'a');
    if (bs.count() < bs.size()) continue;
    bs.reset();
    ++dp[i];
  }

  std::array<std::vector<size_t>, sigma> next;
  for (size_t i = 0; i < n; ++i)
    next[s[i]-'a'].push_back(i);
  for (size_t i = 0; i < sigma; ++i)
    next[i].push_back(n);

  std::string res;
  size_t i = 0;
  while (i < n) {
    for (size_t c = 0; c < sigma; ++c) {
      auto it = std::upper_bound(next[c].begin(), next[c].end(), i);
      if (*it < n && dp[i] == dp[*it]) continue;
      res += 'a' + c;
      i = *it;
      break;
    }
  }

  if (res.length() < dp[0]) res += 'a';
  printf("%s\n", res.c_str());
}

