    }
    info(string _p, int _pos){
        p = _p;
        pos = _pos;
    }

    string p;
    int pos;
};

vector<int> pos_vec[26];


int search(char c, int anchor){
    auto& target = pos_vec[c - 'a'];

    if(target.size() == 0){
        return -1;
    }

    int big = target.size() - 1;
    int small = 0;

    if(target[big] < anchor){
        return -1;
    }

    int mid;

    while(big != small){
        mid = (big + small) / 2;

        if(target[mid] > anchor){
            big = mid;
        }
        else{
            small = mid + 1;
        }
    }

    if(target[big] <= anchor){
        return -1;
     }

    return target[big];
}

