int find_char(int i, int bound) {
	int left = 0;
	int right = p[i].size() - 1;

	if (left > right) return -1; // 노 원소
	if (p[i][left] > bound) return -1; // 답이 없음

	int mid = (left + right) / 2;
	while (p[i][left] < bound && left < right) {
		//cout << left << " " << right << " " << mid << endl;
		mid = (left + right) / 2;
		if (p[i][mid] > bound) right = mid - 1;
		else if (p[i][mid] == bound) return bound;
		else left = mid + 1;
	}
	if (p[i][left] <= bound) return p[i][left];
	return p[i][mid];
}

