const int MAX_N = 200100;
const int MAX_C = 30;
int N;
string A;
int dp[MAX_N];
int nxt[MAX_N][MAX_C];
int restore[MAX_N];
int main() {
  cin >> A;
  N = A.size();
  for (int j = 0; j < MAX_C; j++){
      nxt[N][j] = N;
  }
  for (int i = N-1; i >= 0 ; i--){
      dp[i] = INF;
      for (int j = 0; j < MAX_C; j++){
          nxt[i][j] = nxt[i + 1][j];
          if (A[i] - 'a' == j){
              nxt[i][j] = i;
          }
      }
  }
  memset(restore, -1, sizeof(restore));
  dp[N] = 1;
  for (int i = N-1; i >= 0; i--){
      for (char j = 'a'; j <= 'z'; j++){
          const int p = j - 'a';
          if (dp[nxt[i][p] + 1] + 1 < dp[i]){
              restore[i] = p;
              dp[i] = dp[nxt[i][p] + 1] + 1;
          }
      }
  }
  int res = dp[0];
  int pos = 0;
  string result = "";
  while (result.size() < res){
      if (restore[pos] != -1){
          result += char('a' + restore[pos]);
          pos = nxt[pos][restore[pos]] + 1;
      }else{
          pos++;
      }

  }
  cout << result << endl;
  return 0;
}

