const int INF = 1e9 + 5;
const int ALPHABET = 26;
const char MIN_CHAR = 'a';

int main() {
    ios::sync_with_stdio(false);
#ifndef NEAL_DEBUG
    cin.tie(nullptr);
#endif

    string A;
    cin >> A;
    int N = int(A.size());
    vector<vector<int>> first(N + 1, vector<int>(ALPHABET, INF));
    vector<int> dp(N + 1, 0);

    for (int i = N - 1; i >= 0; i--) {
        first[i] = first[i + 1];
        first[i][A[i] - MIN_CHAR] = i;
        dp[i] = INF;

        for (int c = 0; c < ALPHABET; c++)
            if (first[i][c] == INF)
                dp[i] = 0;
            else
                dp[i] = min(dp[i], 1 + dp[first[i][c] + 1]);
    }

    int current = 0;
    string ans;

    while (current < N) {
        int now = -1;

        for (int c = 0; c < ALPHABET; c++)
            if (first[current][c] == INF || dp[current] == 1 + dp[first[current][c] + 1]) {
                now = c;
                break;
            }

        assert(now >= 0);
        ans += char(MIN_CHAR + now);
        current = first[current][now] + 1;
    }

    cout << ans << '\n';
}

