int main() {
	scanf("%s", S); N = strlen(S);
	for(int i=0; i<N; i++) Ix[S[i]-'a'].push_back(i);
	for(int k=0; k<26; k++) Ix[k].push_back(N);
	for(int i=0; i<=N; i++) for(int k=0; k<26; k++) Block[0][i] = max(Block[0][i], getL(Ix[k], i));
	for(int p=0; p<LOG_N; p++) Block[p][N+1] = N;
	for(int p=1; p<LOG_N; p++) for(int i=0; i<=N; i++) Block[p][i] = Block[p-1][Block[p-1][i]+1];

	int ansL = 0, nowIx = 0;
	for(int p=LOG_N-1; p>=0; p--) if(Block[p][nowIx] < N) ansL += (1<<p), nowIx = Block[p][nowIx] + 1;
	bitset<26> chkLast; for(int i=nowIx; i<N; i++) chkLast[S[i]-'a'] = true;
