string calc(int st) {
    if (dp.count(st)) return dp[st];
    for (char x='a'; x<='z';x++) {
        if (bucket[x-'a'].empty() || bucket[x-'a'][bucket[x-'a'].size()-1] < st) return (dp[st] = string(1, x));
