    string ans;
    for (char x='a'; x<='z';x++) {
        int ind = *lower_bound(bucket[x-'a'].begin(), bucket[x-'a'].end(), st);
        if (x=='a' || (x+calc(ind+1)).length() < ans.length()) {
            ans = x+calc(ind+1);
        }
    }

    return (dp[st] = ans);
}

