int t[100005][26];

bool check(int l,int r){
  for(int i=0;i<26;i++){
    if( t[r][i] - t[l][i] == 0 )return false;
  }
  return true;
}

int mem[100005];
int find(int x){
  if(mem[x]!=-1)return mem[x];
  int left=x+1,right=n,mid;
  while(left<right){
    mid=(left+right)/2;
    if( check(x, mid ) )right=mid;
    else left=mid+1;
  }
  return mem[x]=left;
}

int dp[100005];
int solve(int p){
  if(dp[p]!=-1)  return dp[p];
  if(!check(p,n))return dp[p]=1;
  int nex=find(p);
  return dp[p]=solve(nex)+1;
}

