// 二分探索（改）
// judge を満たすような下限を求める
// left:[X] 定義域の下限
// right:[X] 定義域の上限
// judge:[X -> bool] X を評価する関数
// lower:[bool] falseにすると代わりに上限を求める
// eps:[X] 終了距離

template <typename X>
X BinSearch(X left, X right, function<bool(X)> judge, bool lower = true, X eps = 1) {
    while (right - left > eps) {
        X mid = (right + left) / 2;
        if (judge(mid) == lower) {
            right = mid;
        } else {
            left = mid;
        }
    }
    return lower ? right : left;
}

const int N = 26;

string A;
string ans = "";
vector<int> p[N];

void recursive(int l, string s) {
    if(ans != "") return;
    if(l > s.size()) {
        for(char c = 'a'; c <= 'z'; c++) {
            recursive(l, s + c);
        }
    } else {
        int k = -1;
        for(int i = 0; i < l; i++) {
            int c = s[i] - 'a';
            int result = BinSearch<int>(-1, p[c].size(), [&](int j) -> bool {
                return k < p[c][j];
            });
            if(result == p[c].size()) {
                ans = s;
                return;
            }
            k = p[c][result];
        }
    }
}

