ull mergeteq (sll array[], ull n) {
	if (n == 1) return 0;

	ull left = n / 2;
	ull right = n - left;

	ull result = mergeteq(array, left) + mergeteq(array + left, right);

	sll tmparr[n];
	sll i = 0, j = 0;
	while (i < left || j < right) {
		if (i == left) {
			tmparr[i + j] = array[left + j];
			j++;
			continue;
		}
		if (j == right) {
			tmparr[i + j] = array[i];
			i++;
			continue;
		}


		if (array[i] > array[left + j]) {
			result += (left - i);

			tmparr[i + j] = array[left + j];
			j++;
		} else {
			tmparr[i + j] = array[i];
			i++;
		}
	}

	for (i = 0; i < n; i++) {
		array[i] = tmparr[i];
	}

	return result;
}

