	private static final int maxN = (int) 2e5 + 5;
	private static final int maxM = (int) 1e6 + 5;
	private static final int maxC = (int) 'z' - 'a' + 1;
	private static final int inf = (int) 1e9 + 7;

	private static int N;
	private static String s;
	private static int[] pos, dp, trace;
	static {
		pos = new int[maxC];
		dp = new int[maxN];
		trace = new int[maxN];
	}

	private static void init() {
		for (int i = 0; i < maxN; ++i) {
			dp[i] = inf;
		}
	}

	private static void enter() throws IOException {
		s = nextLine();
		N = s.length();
		s = '!' + s;
	}

	private static void solve() throws IOException {
		for (int i = N; i >= 0; --i) {
			boolean fl = false;
			for (int nex = 0; nex <= 'z' - 'a'; ++nex) {
				if (pos[nex] == 0) {
					dp[i] = 1;
					trace[i] = nex;
					fl = true;
					break;
				}
			}

			if (!fl) {
				for (int nex = 0; nex <= 'z' - 'a'; ++nex) {
					if (dp[i] > dp[pos[nex]] + 1) {
						dp[i] = dp[pos[nex]] + 1;
						trace[i] = pos[nex];
					}
				}
			}

			if (i > 0)
				pos[s.charAt(i) - 'a'] = i;
		}
	}

	private static void doTrace() {
		int ind = 0;
		while (dp[ind] >= 1) {
			if (dp[ind] == 1) {
				output.print((char) (trace[ind] + 'a'));
				break;
			}
			else {
				output.print(s.charAt(trace[ind]));
			}
			ind = trace[ind];
		}
	}

	public static void main(String[] args) throws IOException {
		openFile();
		init();
		enter();
		solve();
		doTrace();
		output.close();
	}
}

import java.util.*;

public class Main {
    private static final int N = 26;

    public void main(Scanner sc) {
        char a[] = sc.next().toCharArray();
        sc.close();
        int len = a.length;

        Map<Character, TreeSet<Integer>> map = new HashMap<>();
        for (int i = 0; i < len; i++) {
            map.putIfAbsent(a[i], new TreeSet<>());
            map.get(a[i]).add(i + 1);
        }

        int data[] = new int[len + 1];
        BitSet bset = new BitSet();
        data[len] = 0;
        for (int i = len - 1; i >= 0; i--) {
            bset.set(a[i] - 'a');
            data[i] = data[i + 1];
            if (bset.cardinality() == N) {
                bset.clear();
                data[i]++;
            }
        }

        int p = 0;
        int ansLen = data[0] + 1;
        char ans[] = new char[ansLen];
        for (int i = 0; i < ansLen; i++) {
            for (char c = 'a'; c <= 'z'; c++) {
                if (!map.containsKey(c)) {
                    ans[i] = c;
                    p = len + 1;
                    break;
                } else {
                    Integer next = map.get(c).ceiling(p);
                    if (next == null || (data[p] - data[next] == 1)) {
                        ans[i] = c;
                        p = getOrDefault(next, len) + 1;
                        break;
                    }
                }
            }
        }
        System.out.println(new String(ans));
    }

    private int getOrDefault(Integer n, int def) {
        return n == null ? def : n;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        new Main().main(sc);
    }
}

