		int[] next2 = Arrays.copyOf(next[0], 26);
		next2[A.charAt(0)-'a']=0;
		int min=Integer.MAX_VALUE;
		char minC=0;
		for(char c='a'; c<='z'; ++c) {
			if(dp[next2[c-'a']]<min) {
				min=dp[next2[c-'a']];
				minC=c;
			}
		}
		int i=next2[minC-'a'];
		System.out.print(minC);
		while(i<A.length()) {
			System.out.print(nextChar[i]);
			//if(nextChar[i]==A.charAt(i))
			//	System.out.print(nextChar[i]);
