    static int inf = 0x7ffffff;

    void solve() {
        String a = scanner.next();
        int n = a.length();
        int[] k = new int[n];
        boolean[] used = new boolean[26];
        int[][] p = new int[26][n + 1];
        for (int i = 0; i < 26; i++) {
            p[i][n] = inf;
        }
        int rem = 26;
        for (int i = n - 1, j = 1; i >= 0; i--) {
            for (int l = 0; l < 26; l++) {
                if (i < n - 1 && a.charAt(i + 1) - 'a' == l) {
                    p[l][i] = i + 1;
                } else {
                    p[l][i] = p[l][i + 1];
                }
            }
            if (!used[a.charAt(i) - 'a']) {
                used[a.charAt(i) - 'a'] = true;
                rem--;
            }
            if (rem == 0) {
                j++;
                used = new boolean[26];
                rem = 26;
            }
            k[i] = j;
        }
        StringBuilder ans = new StringBuilder();
        for (int i = 0, j = 0; i < k[0]; i++) {
            for (int c = 0; c < 26; c++) {
                if (j >= inf) {
                    ans.appendCodePoint('a');
                    break;
                }
                if (p[c][j] >= inf || k[j] - 1 == k[p[c][j]]) {
                    ans.appendCodePoint(c + 'a');
                    j = p[c][j];
                    break;
                }
            }
        }
        System.out.println(ans);
    }

