public void solve() {
	char c[] = nc(-1);
	int num = c.length;
	int a[] = new int[num];
	for(int i = 0; i < num; i ++) {
		a[i] = (int)(c[i] - 'a');
	}

	next = new int[num + 1][26];
	fill(next, num + 100);
	for(int i = 1; i <= num; i ++) {
		next[i - 1][a[i - 1]] = i - 1;
	}
	for(int i = num; i > 0; i --) {
		for(int j = 0; j < 26; j ++) {
			next[i - 1][j] = min(next[i - 1][j], next[i][j]);
		}
	}

	dp = new long[num + 1];
	fill(dp, INF);
	dp[num] = 1;
	for(int i = num - 1; i >= 0; i --) {
		for(int j = 0; j < 26; j ++) {
			if(next[i][j] < num) {
				dp[i] = min(dp[i], dp[next[i][j]] + 1);
			}else {
				dp[i] = 1;
			}
		}
	}
	// errprtln(next);
	// errprtln(dp);
	search(num, (int)dp[0], 0);
	prtln();
}

void search(int num, int len, int index) {
	if(len <= 0) { return; }
	if(index >= num) { prt('a'); search(num, len - 1, index); }
	for(int i = 0; i < 26; i ++) {
		if(next[index][i] >= num || dp[next[index][i] + 1] < len) {
			prt((char)(i + 'a'));
			search(num, len - 1, next[index][i] + 1);
			return;
		}
	}
}

