import java.io.*;
import java.util.*;

class Solver {
  final char[] cs;
  final int n;

  Solver(char[] cs) {
    this.cs = cs;
    this.n = cs.length;
  }

  public String solve() {
    int[] hasAll = new int[n + 1];
    hasAll[n] = 0;
    boolean[] exist = new boolean[26];
    int existCount = 0;
    for (int i = n-1; i >= 0; i--) {
      hasAll[i] = hasAll[i + 1];
      int charIndex = cs[i] - 'a';

      if (exist[charIndex]) {
        continue;
      }
      exist[charIndex] = true;
      existCount++;
      if (existCount < 26) {
        continue;
      }

      hasAll[i]++;
      Arrays.fill(exist, false);
      existCount = 0;
    }

    List<TreeSet<Integer>> charIndexSetList = new ArrayList<>();
    for (int i = 0; i < 26; i++) {
      charIndexSetList.add(new TreeSet<>());
    }
    for (int i = 0; i < n; i++) {
      int charIndex = cs[i] - 'a';
      charIndexSetList.get(charIndex).add(i);
    }

    int length = hasAll[0] + 1;
    int index = -1;
    StringBuffer sb = new StringBuffer();
    while (sb.length() < length) {
      for (int i = 0; i < 26; i++) {
        Integer nextIndex = charIndexSetList.get(i).higher(index);
        if (nextIndex == null || sb.length() + 1 + hasAll[nextIndex + 1] < length) {
          index = nextIndex != null ? nextIndex : n;
          sb.append((char)('a' + i));
          break;
        }
      }
    }
    return sb.toString();
  }
}

