import java.util.*;

public class Main {
    private static final int INF = 1000000000;

    public static void main(String[] args) {
        // read inputs
        Scanner in = new Scanner(System.in);
        String cs = in.next();
        final int N = cs.length();
        // System.out.printf("cs = %s\n", cs);

        // solve dp
        int[][] dpss = new int[N + 1][];
        for (int i = 0; i <= N; i++) {
            dpss[i] = new int[26];
        }
        // initialize
        for (int j = 0; j < 26; j++) {
            dpss[N][j] = 0;
        }
        // solve
        for (int i = N - 1; i >= 0; i--) {
            final char ci = cs.charAt(i);
            int jmin = 0;
            for (int j = 0; j < 26; j++) {
                if (dpss[i + 1][j] < dpss[i + 1][jmin]) {
                    jmin = j;
                }
            }
            for (int j = 0; j < 26; j++) {
                final char cj = (char) ((int) 'a' + j);
                if (ci == cj) {
                    dpss[i][j] = dpss[i + 1][jmin] + 1;
                } else {
                    dpss[i][j] = dpss[i + 1][j];
                }
            }
        }
        StringBuilder builder = new StringBuilder();
        int K = INF;
        char c = 'a';
        for (int j = 0; j < 26; j++) {
            if (dpss[0][j] < K) {
                K = dpss[0][j];
                c = (char) ((int) 'a' + j);
            }
        }
        int i = 0;
        for (int k = 0; k < K; k++) {
            final int j0 = (int) c - 'a';
            while (i < N && cs.charAt(i) != c) {
                i++;
            }
            for (int j = 0; j < 26; j++) {
                final char cj = (char) ((int) 'a' + j);
                if (dpss[i][j0] == dpss[i + 1][j] + 1) {
                    builder.append(c);
                    c = cj;
                    break;
                }
            }    
        }
        builder.append(c);
        System.out.printf("%s\n", builder);
    }
}

import java.util.*;

class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String a = sc.next();
        char[] A = a.toCharArray();
        int n = A.length;
        HashSet<Character> dic = new HashSet<>();
        ArrayList<int[]> interval = new ArrayList<>();
        int right = n-1;
        for(int i=n-1;i>=0;i--){
            dic.add(A[i]);
            if(dic.size()==26){
                interval.add(new int[]{i,right});
                right = i-1;
                dic = new HashSet<>();
            }
        }
        int tot = interval.size();
        if(tot==0){
            System.out.println(helper(A,0,A.length-1));
            System.exit(0);
        }
        StringBuilder res = new StringBuilder();
        int[] next = interval.get(tot-1);
        char cur = helper(A,0,next[0]-1);
        res.append(cur);
        for(int i=1;i<=tot;i++){
            int idx = find(A,next[0],cur);
            cur = helper(A,idx+1,next[1]);
            res.append(cur);
            if(i<tot) next = interval.get(tot-i-1);
        }
        System.out.println(res.toString());
    }
    static char helper(char[] A, int left, int right){
        int[] cnt = new int[26];
        for(int i=left;i<=right;i++) cnt[A[i]-'a']++;
        for(int i=0;i<26;i++){
            if(cnt[i]==0) return (char)(i+'a');
        }
        return 'z';
    }
    static int find(char[] A, int left, char target){
        for(int i=left;i<A.length-1;i++){
            if(A[i]==target) return i;
        }
        return A.length;
    }
}

