		solve();
		out.flush();
		long G = System.currentTimeMillis();
		tr(G-S+"ms");
	}

	private static boolean eof()
	{
		if(lenbuf == -1)return true;
		int lptr = ptrbuf;
		while(lptr < lenbuf)if(!isSpaceChar(inbuf[lptr++]))return false;

		try {
			is.mark(1000);
			while(true){
				int b = is.read();
				if(b == -1){
					is.reset();
					return true;
				}else if(!isSpaceChar(b)){
					is.reset();
					return false;
				}
			}
		} catch (IOException e) {
			return true;
		}
	}

	private static byte[] inbuf = new byte[1024];
	static int lenbuf = 0, ptrbuf = 0;

	private static int readByte()
	{
		if(lenbuf == -1)throw new InputMismatchException();
		if(ptrbuf >= lenbuf){
			ptrbuf = 0;
			try { lenbuf = is.read(inbuf); } catch (IOException e) { throw new InputMismatchException(); }
			if(lenbuf <= 0)return -1;
		}
		return inbuf[ptrbuf++];
	}

	private static boolean isSpaceChar(int c) { return !(c >= 33 && c <= 126); }
//	private static boolean isSpaceChar(int c) { return !(c >= 32 && c <= 126); }
	private static int skip() { int b; while((b = readByte()) != -1 && isSpaceChar(b)); return b; }

	private static double nd() { return Double.parseDouble(ns()); }
	private static char nc() { return (char)skip(); }

	private static String ns()
	{
		int b = skip();
		StringBuilder sb = new StringBuilder();
		while(!(isSpaceChar(b))){
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}

	private static char[] ns(int n)
	{
		char[] buf = new char[n];
		int b = skip(), p = 0;
		while(p < n && !(isSpaceChar(b))){
			buf[p++] = (char)b;
			b = readByte();
		}
		return n == p ? buf : Arrays.copyOf(buf, p);
	}

	private static char[][] nm(int n, int m)
	{
		char[][] map = new char[n][];
		for(int i = 0;i < n;i++)map[i] = ns(m);
		return map;
	}

	private static int[] na(int n)
	{
		int[] a = new int[n];
		for(int i = 0;i < n;i++)a[i] = ni();
		return a;
	}

	private static int ni()
	{
		int num = 0, b;
		boolean minus = false;
		while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
		if(b == '-'){
			minus = true;
			b = readByte();
		}

		while(true){
			if(b >= '0' && b <= '9'){
				num = num * 10 + (b - '0');
			}else{
				return minus ? -num : num;
			}
			b = readByte();
		}
	}

	private static long nl()
	{
		long num = 0;
		int b;
		boolean minus = false;
		while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
		if(b == '-'){
			minus = true;
			b = readByte();
		}

		while(true){
			if(b >= '0' && b <= '9'){
				num = num * 10 + (b - '0');
			}else{
				return minus ? -num : num;
			}
			b = readByte();
		}
	}

	private static void tr(Object... o) { if(INPUT.length() != 0)System.out.println(Arrays.deepToString(o)); }
}

import java.util.*;

public class Main {
    private static final int INF = 1000000000;

    public static void main(String[] args) {
        // read inputs
        Scanner in = new Scanner(System.in);
        String cs = in.next();
        final int N = cs.length();
        // System.out.printf("cs = %s\n", cs);

        // solve dp
        int[][] dpss = new int[N + 1][];
        for (int i = 0; i <= N; i++) {
            dpss[i] = new int[26];
        }
        // initialize
        for (int j = 0; j < 26; j++) {
            dpss[N][j] = 0;
        }
        // solve
        for (int i = N - 1; i >= 0; i--) {
            final char ci = cs.charAt(i);
            int jmin = 0;
            for (int j = 0; j < 26; j++) {
                if (dpss[i + 1][j] < dpss[i + 1][jmin]) {
                    jmin = j;
                }
            }
            for (int j = 0; j < 26; j++) {
                final char cj = (char) ((int) 'a' + j);
                if (ci == cj) {
                    dpss[i][j] = dpss[i + 1][jmin] + 1;
                } else {
                    dpss[i][j] = dpss[i + 1][j];
                }
            }
        }
        StringBuilder builder = new StringBuilder();
        int K = INF;
        char c = 'a';
        for (int j = 0; j < 26; j++) {
            if (dpss[0][j] < K) {
                K = dpss[0][j];
                c = (char) ((int) 'a' + j);
            }
        }
        int i = 0;
        for (int k = 0; k < K; k++) {
            final int j0 = (int) c - 'a';
            while (i < N && cs.charAt(i) != c) {
                i++;
            }
            if (i >= N) {
                break;
            }
            for (int j = 0; j < 26; j++) {
                final char cj = (char) ((int) 'a' + j);
                if (dpss[i][j0] == dpss[i + 1][j] + 1) {
                    builder.append(c);
                    c = cj;
                    break;
                }
            }    
        }
        builder.append(c);
        System.out.printf("%s\n", builder);
    }
}

import java.util.HashSet;
