public class Main {
    char[] cs;

    public static void main(String args[]) {
        new Main().run();
    }

    void run() {
        FastReader sc = new FastReader();
        cs = sc.next().toCharArray();
        solve();
    }

    void solve() {
        int[] used = new int[26];
        List<Integer> list = new ArrayList<>();
        List<List<Integer>> occurrences = new ArrayList<>();
        for (int i = 0; i < 26; i++) {
            occurrences.add(new ArrayList<>());
        }
        for (int i = cs.length - 1; i >= 0; i--) {
            occurrences.get(cs[i] - 'a').add(i);
            used[cs[i] - 'a']++;
            boolean flag = true;
            for (int j = 0; j < used.length; j++) {
                if (used[j] == 0) {
                    flag = false;
                    break;
                }
            }
            if (flag) {
                list.add(i);
                Arrays.fill(used, 0);
            }
        }
        Collections.sort(list);
        list.add(cs.length);
        for (int i = 0; i < occurrences.size(); i++) {
            Collections.sort(occurrences.get(i));
        }
        //for (int i = 0; i < occurrences.get(0).size(); i++) {
            //System.out.print(" " + occurrences.get(0).get(i));
        //}
        //System.out.println();
        int index = 0;
        int currentPosition = 0;
        StringBuilder ans = new StringBuilder();
        for (int i = 0; i < list.size(); i++) {
            //System.out.println(i + " " + currentPosition);
            for (int j = 0; j < used.length; j++) {
                int nextOccurrence =
                        lower_bound(occurrences.get(j), currentPosition);
                if (nextOccurrence == occurrences.get(j).size()) {
                    ans.append((char)(j + 'a'));
                    break;
                }
                //System.out.println(index);
                //System.out.println(list.get(index) + " " + occurrences.get(j).get(nextOccurrence) + " " + list.get(index + 1));
                if (index < list.size() - 1) {
                    if (list.get(index) <= occurrences.get(j).get(nextOccurrence) &&
                            occurrences.get(j).get(nextOccurrence) < list.get(index + 1)) {
                        ans.append((char) (j + 'a'));
                        currentPosition = occurrences.get(j).get(nextOccurrence) + 1;
                        index++;
                        break;
                    }
                }
            }
            //System.out.println(ans);
        }
        System.out.println(ans);
    }

    static int lower_bound(List<Integer> arr, int key) {
        int low = 0;
        int high = arr.size() - 1;
        while (high - low >= 0) {
            int mid = (low + high) / 2;
            if (key <= arr.get(mid)) {
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new
                    InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements())
            {
                try
                {
                    st = new StringTokenizer(br.readLine());
                }
                catch (IOException e)
                {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt()
        {
            return Integer.parseInt(next());
        }

        long nextLong()
        {
            return Long.parseLong(next());
        }

        double nextDouble()
        {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try
            {
                str = br.readLine();
            }
            catch (IOException e)
            {
                e.printStackTrace();
            }
            return str;
        }
    }
}

import java.io.*;
import java.util.*;

class Main {
    public static void main(String[] args) {
        new Main().solve();
    }

    final int INF = Integer.MAX_VALUE / 4;

    String s;
    int[][] f;
    void solve() {
        final BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        try { s = reader.readLine(); } catch (IOException e) {}
        final int N = s.length();
        f = new int[N + 1][26];
        for (int[] f_line : f) Arrays.fill(f_line, INF);
        final int[] last = new int[26]; Arrays.fill(last, INF);
        for (int i = N - 1; i >= 0; i--) {
            char c = s.charAt(i);
            int c_index = (int)(c - 'a');
            last[c_index] = i;
            for (int j = 0; j < 26; j++) {
                f[i][j] = last[j];
            }
        }

        int count = 26;
        int last_char_index = -1;
        boolean[] used = new boolean[26]; Arrays.fill(used, false);
        for (int i = N - 1; i >= 0; i--) {
            char c = s.charAt(i);
            int c_index = (int)(c - 'a');
            if (used[c_index]) continue;
            used[c_index] = true;
            count--;
            if (count == 0) last_char_index = c_index;
        }
        assert last_char_index >= 0;

        int[] g = new int[N]; Arrays.fill(g, INF);
        int[] n = new int[N]; Arrays.fill(n, INF);
        int[] c = new int[N]; Arrays.fill(n, INF);
        for (int i = N - 1; i >= 0; i--) {
            for (int j = 0; j < 26; j++) {
                int k = f[i + 1][j];
                int v = k == INF ? (last_char_index == j ? 2 : 1) : g[k] + 1;
                if (g[i] > v) {
                    g[i] = v;
                    n[i] = k;
                    c[i] = j == last_char_index ? 500 + j : j;
                }
            }
        }
        for (int i = 0; i < N; i++) {
            if (g[i] == 1) c[i] = (s.charAt(i) == 'a' ? 1 : 0);
        }
        int i = 0;
        final StringBuilder builder = new StringBuilder();
        while (i < N) {
            int j = c[i];
            if (j >= 500) {
                builder.append((char)(j - 500 + 'a'));
                builder.append((char)(j - 500 + 'a'));
            } else {
                builder.append((char)(j + 'a'));
            }
            i = n[i];
        }
        System.out.println(builder.toString());
    }
}

import java.util.HashMap;
import java.util.LinkedList;
import java.util.Scanner;
import java.util.TreeSet;

public class Main {
    private static String solve(Scanner scanner) {
        String s = scanner.nextLine();

        HashMap<Character, TreeSet<Integer>> c2inds = new HashMap<>();
        for (int i = 0; i < s.length(); i ++) {
            Character c = s.charAt(i);
            TreeSet<Integer> inds = c2inds.getOrDefault(c, new TreeSet<>());
            inds.add(i);
            c2inds.put(c, inds);
        }

        int len = 1;
        while (true) {
            LinkedList<String> strs = listupStrs(len);
            for (String str: strs) {
                Integer ind = -1;
                for (int si = 0; si < str.length(); si ++) {
                    TreeSet<Integer> inds = c2inds.getOrDefault(str.charAt(si), null);
                    if (inds == null) return str;

                    ind = inds.higher(ind);
                    if (ind == null) return str;
                }
            }
            len ++;
        }
    }

    private static LinkedList<String> listupStrs(int len) {
        LinkedList<String> ret = new LinkedList<>();

        if (len == 0) {
            ret.add("");
            return ret;
        }

        LinkedList<String> seed = listupStrs(len - 1);

        for (int i = 0; i < 26; i ++) {
            for (String s: seed) {
                char c = (char) ((int) 'a' + i);
                ret.add(c + s);
            }
        }

        return ret;
    }

