          d = 1 + dplen[c + 1];
          str = s + dpstr[c + 1];
        }
        if(c == len - 1) {
          d = 2;
          str = s + "a";
        }
        if(d < minlen) {
          minlen = d;
          minstr = str;
        }
      }
      dplen[n] = minlen;
      dpstr[n] = minstr;      
    }
  }
}

