		void SolveOne()
		{
			var N = S.Length;
			var set = new BinaryIndexedTree[26];
			for (var i = 0; i < 26; i++) set[i] = new BinaryIndexedTree(N);
			var first = new int[26];
			for (var c = 0; c < 26; c++) first[c] = N;
			for (var i = 0; i < N; i++) { var c = S[i] - 'a'; set[S[i] - 'a'].Add(i, 1); first[c] = Min(first[c], i); }
			for (var c = 0; c < 26; c++) if (first[c] == N) { pr.WriteLine((char)('a' + c)); return; }
			var next = new int[N, 26];
			var end = new int[N];
			for (var i = 0; i < N; i++)
			{
				var flag = true;
				end[i] = -1;
				for (var c = 0; c < 26; c++)
					if (set[c].Sum(i + 1, N) > 0) next[i, c] = FirstBinary(i + 1, N, j => set[c].Sum(i + 1, j) > 0) - 1;
					else
					{
						next[i, c] = -1;
						if (flag) { end[i] = c; flag = false; }
					}
			}
			var len = new int[N];
			var good = new int[N];
			for (var i = N - 1; i >= 0; i--)
			{
				len[i] = N + 1;
				if (end[i] >= 0) len[i] = 2;
				else for (var c = 0; c < 26; c++) if (len[i] > len[next[i, c]] + 1) { len[i] = len[next[i, c]] + 1; good[i] = c; }
			}
			var ans = new string[26];
			for (var c = 0; c < 26; c++)
			{
				var x = first[c];
				var s = new char[len[x]];
				var i = 0;
				s[i++] = (char)(c + 'a');
				while (true)
				{
					if (end[x] >= 0) { s[i++] = (char)(end[x] + 'a'); break; }
					else { s[i++] = (char)(good[x] + 'a'); x = next[x, good[x]]; }
				}
				ans[c] = new string(s);
			}
			var t = ans[0];
			for (var c = 1; c < 26; c++) if (t.Length > ans[c].Length) t = ans[c];
			pr.WriteLine(t);
		}
		int[] SuffixArray(string S)
		{
			var N = S.Length;
			var sa = new int[N + 1];
			var r = new int[N + 1];
			for (var i = 0; i <= N; i++)
			{
				sa[i] = i;
				r[i] = i < N ? S[i] : -1;
			}
			var k = 1;
			Comparison<int> comp = (i, j) =>
			{
				if (r[i] != r[j]) return r[i] - r[j];
				var a = i + k <= N ? r[i + k] : -1;
				var b = j + k <= N ? r[j + k] : -1;
				return a - b;
			};
			for (; k <= N; k *= 2)
			{
				Array.Sort(sa, comp);
				var tmp = new int[N + 1];
				for (var i = 1; i <= N; i++) tmp[sa[i]] = tmp[sa[i - 1]] + (comp(sa[i - 1], sa[i]) < 0 ? 1 : 0);
				r = tmp;
			}
			return sa;
		}
	}
	class RangeSegmentTree
	{
		int N2;
		int[] seg, unif;
		public RangeSegmentTree(int N)
		{
			N2 = 1;
			while (N2 < N) N2 <<= 1;
			seg = new int[2 * N2 - 1];
			unif = new int[2 * N2 - 1];
		}
		void LazyEvaluate(int node)
		{
			if (unif[node] == 0) return;
			seg[node] += unif[node];
			if (node < N2 - 1)
			{
				unif[2 * node + 1] += unif[node];
				unif[2 * node + 2] += unif[node];
			}
			unif[node] = 0;
		}
		void Update(int node) => seg[node] = seg[2 * node + 1] + seg[2 * node + 2];
		public void AddRange(int from, int to, int value) => AddRange(from, to, value, 0, 0, N2);
		void AddRange(int from, int to, int value, int node, int l, int r)
		{
			if (from <= l && r <= to) unif[node] += value;
			else if (l < to && from < r)
			{
				AddRange(from, to, value, 2 * node + 1, l, (l + r) >> 1);
				AddRange(from, to, value, 2 * node + 2, (l + r) >> 1, r);
				Update(node);
			}
			LazyEvaluate(node);
		}
		public int this[int n] { get { return Sum(n, n + 1); } set { AddRange(n, n + 1, value - this[n]); } }
		public int Sum(int from, int to) => Sum(from, to, 0, 0, N2);
		int Sum(int from, int to, int node, int l, int r)
		{
			LazyEvaluate(node);
			if (to <= l || r <= from) return 0;
			else if (from <= l && r <= to) return seg[node];
			else return Sum(from, to, 2 * node + 1, l, (l + r) >> 1) + Sum(from, to, 2 * node + 2, (l + r) >> 1, r);
		}
	}
