namespace Kujikatsu039.Questions
{
    /// <summary>
    /// https://atcoder.jp/contests/arc081/tasks/arc081_c
    /// </summary>
    public class QuestionG : AtCoderQuestionBase
    {
        public override IEnumerable<object> Solve(TextReader inputStream)
        {
            var s = inputStream.ReadLine();
            var candidates = new Queue<string>();

            for (var c = 'a'; c <= 'z'; c++)
            {
                candidates.Enqueue(c.ToString());
            }

            while (true)
            {
                var candidate = candidates.Dequeue();
                if (Contains(s, candidate))
                {
                    for (var c = 'a'; c <= 'z'; c++)
                    {
                        candidates.Enqueue(candidate + c);
                    }
                }
                else
                {
                    yield return candidate;
                    yield break;
                }
            }
        }

        bool Contains(string s, string candidate)
        {
            var cursor = 0;
            foreach (var c in s)
            {
                if (c == candidate[cursor])
                {
                    cursor++;
                    if (cursor == candidate.Length)
                    {
                        return true;
                    }
                }
            }
            return false;
        }
    }
}

