        static void Solve()
        {
            var A = Cin.Str;
            int N = A.Length;
            var nx = new int[N][];
            for(var i = 0; i < N; i++)
            {
                nx[i] = new int[26];
                Fill(nx[i], INF);
            }
            for(var i = N - 1; i >= 0; i--)
            {
                for(var j = 0; j < 26; j++)
                {
                    if (i + 1 < N) nx[i][j] = nx[i + 1][j];
                }
                nx[i][A[i] - 'a'] = i;
            }
            var dp = new int[N + 1];
            var nxc = new int[N + 1];
            Fill(dp, INF);
            Fill(nxc, -1);
            dp[N] = 1;
            for(var i = N - 1; i >= 0; i--)
            {
                for(var c = 0; c < 26; c++)
                {
                    if (nx[i][c] == INF)
                    {
                        if (dp[i] == 1) continue;
                        dp[i] = 1;
                        nxc[i] = c;
                    }
                    else
                    {
                        if (dp[i] > dp[nx[i][c] + 1] + 1)
                        {
                            dp[i] = dp[nx[i][c] + 1] + 1;
                            nxc[i] = c;
                        }
                    }
                }
            }
            /*Out_Sep(dp);
            Out_Sep(nxc);*/
            var ans = new StringBuilder();
            var id = 0;
            for(var i = 0; i < dp[0]; i++)
            {
                ans.Append((char)('a' + nxc[id]));
                if (i + 1 < dp[0]) id = nx[id][nxc[id]];
            }
            OutL(string.Join("", ans.ToString().Reverse()));

        }

