.using System;
using System.Linq;//リストの使用
using System.Collections.Generic;
using System.Text;//テキストの高速出力に必要
class Solve{
  StringBuilder sb;
  public static int Main()
  {
    new Solve().Run();
    return 0;
  }

  void Run()
  {
    sb = new StringBuilder();//解答
    Calc();
    Console.Write(sb.ToString());
  }

  void Calc()
  {
    string S = Console.ReadLine();
    int N = S.Length;//文字数
    int[,] D = new int[N+1,26];
    int[] DM = new int[N+1];

    for(int i = 0; i < 26; i++) D[N,i] = N;//最大値の初期化
    DM[N] = N;

    for(int i = N-1; i >= 0; i--)//逆側から
    {
      int max = 0;
      for(int j = 0; j < 26; j++)//26文字を順に
      {
        if((S[i] - 'a') == j)//i番目はアルファベットj個目
        {
          D[i,j] = i;//Dを最小値のiに更新
        }
        else D[i,j] = D[i+1,j];//Dは変更しない

        max = Math.Max(max,D[i,j]);
      }

      DM[i] = max;//D[i]の任意のアルファベットjでの最大値
    }

    int[] A = new int[N+2];
    for(int i = N-1; i >= 0; i--)//逆側から
    {
      if(DM[i] == N) A[i] = 1;//1度も使っていないアルファベットが存在する
      else if(DM[i] == N-1) A[i] = 2;
      else A[i] = A[DM[i]+1]+1;
    }
    A[N] = -1;
    int L = A[0];//解答の文字列の長さ
    int count = L;
    int p = 0;
    for(int i = 0; i < L; i++)//解答の文字列の長さだけ回して文字列を作成
    {
      for(int j = 0; j < 26; j++)//全てのアルファベット。a>b>c順に優先。
      {
        if(D[p,j] == N ||//1度も使っていないアルファベット
          D[p,j] == N-1 && count == 2 ||
            A[D[p,j]+1]+1 == count)
        {
          p = D[p,j]+1;
          sb.Append((char)('a'+j));//解答の文字追加
          count--;
          break;
        }
      }
    }
    sb.Append("\n");//改行
  }
}

