class Solver
{
    public void Solve(Scanner sc)
    {
        var S = ReadLine();
        int N = S.Length;
        var nx = Create(26, () => Create(N+1, () => -1));
        for (var i = N - 1; i >= 0; i--)
        {
            for (var j = 0; j < 26; j++)
                nx[j][i] = nx[j][i + 1];
            nx[S[i] - 'a'][i] = i;
        }
        var dp = new P[N+1];
        dp[N] = new P(1, N, '_');
        for(int i = N-1; i >= 0; i--)
        {
            dp[i] = new P(int.MaxValue, N, '_');
            for(int j=0;j<26;j++)
                if (nx[j][i] == -1)
                {
                    dp[i] = new P(1, N, (char)('a' + j));break;
                }
                else
                {
                    if(chmin(ref dp[i].len, dp[nx[j][i] + 1].len + 1))
                    {
                        dp[i].nx = nx[j][i] + 1;
                        dp[i].ch = (char)('a' + j);
                    }
                }
        }
        var idx = 0;
        var res = new List<char>();
        while (idx != N)
        {
            res.Add(dp[idx].ch);
            idx = dp[idx].nx;
        }
        Console.WriteLine(new string(res.ToArray()));
    }
    struct P
    {
        public int nx, len;public char ch;
        public P(int l,int n,char c)
        {
            len = l;nx = n;ch = c;
        }
    }
}

