static class P
{
    static void Main()
    {
        string s = Console.ReadLine();
        int[] nextCharIndex = new int[s.Length];
        int[] eachLength = new int[26];
        int[] nextIndex = Enumerable.Repeat(s.Length, 26).ToArray();
        int min;
        for (int i = s.Length - 1; i >= 0; i--)
        {
            var elem = s[i] - 'a';
            nextIndex[elem] = i;
            min = eachLength.Where((x,y) => y != elem).Min();
            for (int j = 0; j < 26; j++)
            {
                if (elem != j && eachLength[j] == min)
                {
                    nextCharIndex[i] = nextIndex[j];
                    eachLength[elem] = eachLength[j] + 1;
                    break;
                }
            }
        }
        min = eachLength.Min();
        for (int i = 0; i < 26; i++)
        {
            if(eachLength[i] == min)
            {
                StringBuilder builder = new StringBuilder();
                var currentInd = nextIndex[i];
                while (currentInd < s.Length)
                {
                    builder.Append(s[currentInd]);
                    currentInd = nextCharIndex[currentInd];
                }
                builder.Append('a');
                Console.WriteLine(builder.ToString());
                break;
            }
        }
    }
}

