class Program
{
    private static void chmin<T>(ref T num, T val) where T : IComparable<T>
        => num = num.CompareTo(val) == 1 ? val : num;
    private static void chmax<T>(ref T num, T val) where T : IComparable<T>
        => num = num.CompareTo(val) == -1 ? val : num;
    private static void swap<T>(ref T v1, ref T v2)
    { var t = v2; v2 = v1; v1 = t; }
    static void Main(string[] args)
    {
        var pr = new Program();
        var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        Console.SetOut(sw);
        pr.Solve();
        Console.Out.Flush();
    }
    void Solve()
    {
        var str = ReadLine();
        var next = Enumerable.Repeat(0, str.Length + 1).Select(_ => new int[30]).ToArray();
        next[str.Length] = Enumerable.Repeat(str.Length, 26).ToArray();
        for (var i = str.Length; i > 0; i--)
            for (var j = 0; j < 26; j++)
                if (str[i - 1] - 'a' == j)
                    next[i - 1][j] = i-1;
                else next[i - 1][j] = next[i][j];
        var dp = Enumerable.Repeat(str.Length, str.Length + 2).ToArray();
        var ne = new int[str.Length + 1];
        var res = new StringBuilder();
        dp[str.Length] = 1;
        dp[str.Length + 1] = 0;
        for(var i=str.Length-1;i>=0;i--)
            for(var j = 0; j < 26; j++)
                if(next[i][j]==str.Length)
                {
                    if (dp[i] > 1)
                        dp[i] = 1;
                }else if(dp[i]>dp[next[i][j]+1]+1)
                {
                    dp[i] = dp[next[i][j]+1] + 1;
                    ne[i] = next[i][j] + 1;
                }
        var index = 0;
        while (index <= str.Length)
            for (var i = 0; i < 26; i++)
                if (dp[index] - 1 == dp[next[index][i]+1])
                { res.Append((char)(i + 'a')); index = next[index][i]+1; break; }

        WriteLine(res.ToString());
    }
}

