func Pre(A *[]int, s int) int {
  N := len((*A))
  if N < 1 || s <= (*A)[0] { return -1 }
  if (*A)[N - 1] < s { return (*A)[N - 1] }
  ges, lts := N - 1, 0
  for 1 < ges - lts {
    med := (ges + lts) / 2
    if (*A)[med] < s {
      lts = med
    } else {
      ges = med
    }
  }
  return (*A)[lts]
}
func Post(A *[]int, s int) int {
  N := len((*A))
  if N < 1 || (*A)[N - 1] <= s { return -1 }
  if s < (*A)[0] { return (*A)[0] }
  gts, les := N - 1, 0
  for 1 < gts - les {
    med := (gts + les) / 2
    if s < (*A)[med] {
      gts = med
    } else {
      les = med
    }
  }
  return (*A)[gts]
}

