    if _p < 0 { break }
    pos = _p
    Z[pos]++
  }
  for i := range Z[1:] {
    Z[i + 1] += Z[i]
  }
  ans := make([]rune, Z[N] + 1)
  pos = 0
  for i := range ans {
    for j, s := range S {
