  ans := ""
  S := make([]map[string]int, N + 1)
  T := make([]map[string]int, N + 1)
  for i := range S {
    S[i] = map[string]int{}
    T[i] = map[string]int{}
  }
  for j := int('a'); j <= int('z'); j++ {
    S[0][string(j)] = 0
    T[N][string(j)] = 0
  }
  for i := 0; i < N; i++ {
    for j := int('a'); j <= int('z'); j++ {
      S[i + 1][string(j)] = S[i][string(j)]
      T[N - i - 1][string(j)] = T[N - i][string(j)]
    }
