    long K = 26;
    string as = readln.chomp;
    auto lists = [DList!char()];
    bool[] used = char.max.rep!(()=>false);
    long cnt = 0;
    foreach(a; as.retro.to!string) {
        if (!used[a]) cnt++;
        used[a] = true;
        lists.back.insertFront(a);
        if (cnt == K) {
            used[] = false;
            cnt = 0;
            lists ~= DList!char();
        }
    }
    lists.reverse();
    auto tree = redBlackTree!("a<b", false, long)();
    string ans = "";
    foreach(i, list; lists) {
        tree.clear;
        tree.insert(list[]);
        foreach(c; 'a'..'z'+1) {
            if (c !in tree) {
                ans ~= c;
                break;
            }
        }
        if (i < lists.length-1) {
            while(ans.back!=lists[i+1].front) {
                lists[i+1].removeFront;
            }
            lists[i+1].removeFront;
        }
    }
    ans.writeln;
}

