      if (ci == ai) {
        continue;
      }
      bool cmp() {
        if (s[ci].length >= s[ai].length) {
          return false;
        }
        if (s[ci].length + 1 < s[ai].length) {
          return true;
        }
        auto idx = c[tuple(ai, ci)];
        while (idx < s[ci].length) {
          if (s[ci][idx] != s[ai][idx]) {
            return s[ci][idx] < s[ai][idx];
          }
          ++idx;
        }
        return ai <= s[ai][idx];
      }

      if (cmp()) {
        s[ai] = s[ci].idup ~ ai;
        c[tuple(ai, ai)] = s[ai].length;
        c[tuple(ai, ci)] = s[ci].length;
        c[tuple(ci, ai)] = s[ci].length;
        foreach (j; iota(26)) {
          char cj = ('a' + j).to!char;
          if (cj == ci || ai == cj) {
            continue;
          }
          c[tuple(ai, cj)] = c[tuple(ci, cj)];
          c[tuple(cj, ai)] = c[tuple(cj, ci)];
          while (c[tuple(ai, cj)] < s[ai].length && c[tuple(ai,
              cj)] < s[cj].length && s[ai][c[tuple(ai, cj)]] == s[cj][c[tuple(ai, cj)]]) {
            ++c[tuple(ai, cj)];
            ++c[tuple(cj, ai)];
          }
        }
      }
    }
  }
  char ans = 'a';
  foreach (i; iota(25)) {
    char ci = ('b' + i).to!char;
    if (s[ci].length < s[ans].length) {
      ans = ci;
      continue;
    }
    if (s[ci].length == s[ans].length) {
      long idx = c[tuple(ans, ci)];
      if (s[ci][idx] < s[ans][idx]) {
        ans = ci;
        continue;
      }
    }
  }
  writeln(s[ans]);
}

