def solve_case():
    S = read_str()

    @lru_cache(maxsize=None)
    # the position of the first `char` from `from_idx`
    def next_char_pos(from_idx, char):
        if from_idx == len(S):
            return len(S)
        if S[from_idx] == char:
            return from_idx
        return next_char_pos(from_idx+1, char)

    recon = dict()

    @lru_cache(maxsize=None)
    # the length of the shortest "non subsequence" in S[from_idx:]
    def non_subseq_len(from_idx):
        if from_idx == len(S):
            return 1
        if from_idx > len(S):
            return 0
        ans = inf
        for letter in ascii_lowercase:
            new_ans = non_subseq_len(next_char_pos(from_idx, letter) + 1) + 1
            if ans > new_ans:
                ans = new_ans
                recon[from_idx] = (letter, next_char_pos(from_idx, letter) + 1)
        return ans

    for from_idx in reversed(range(len(S))):
        non_subseq_len(from_idx)

    ans = ''
    idx = 0
    while idx < len(S):
        letter, next_idx = recon[idx]
        ans += letter
        idx = next_idx
    return ans

