from string import ascii_lowercase


def solve(s):
    d = [('', 0)]
    while True:
        e = []
        ans = set()
        for ds, di in d:
            max_ci = -1
            for c in ascii_lowercase:
                ci = s.find(c, di) + 1
                if max_ci >= ci:
                    continue
                max_ci = ci
                ns = ds + c
                if not ci:
                    ans.add(ns)
                    continue
                e.append((ns, ci))
        if ans:
            return min(ans)
        d = e


