fn solve() {
    while let Some(s) = read::<String>() {
        let a = s.bytes().map(|c| c - b'a').collect::<Vec<u8>>();
        let n = s.len();
        let mut pos = vec![vec![]; 26];
        for i in 0..n {
            pos[a[i] as usize].push(i);
        }
        for i in 0..26 {
            pos[i].push(n);
        }

        let mut s = BTreeSet::<u8>::new();
        let mut len = vec![0; n];
        for i in (0..n).rev() {
            s.insert(a[i]);
            if s.len() == 26 {
                len[i] = len[i + 1] + 1;
                s.clear();
            } else if i != n - 1 {
                len[i] = len[i + 1];
            } else {
                len[i] = 1;
            }
        }

        let stdout = stdout();
        let mut buf = BufWriter::new(stdout.lock());
        let mut cur = 0;
        for k in (0..len[0]).rev() {
            for c in 0..26 {
                let ipos = pos[c as usize].binary_search(&cur).unwrap_or_else(|e| e);
                let i = pos[c as usize][ipos];
                let l = if i + 1 < n { len[i + 1] } else { 0 };
                if l == k {
                    write!(&mut buf, "{}", (c + b'a') as char).ok();
                    cur = i + 1;
                    break;
                }
            }
        }
        writeln!(&mut buf, "").ok();
    }
}

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());
    let s = sc
        .read::<String>()
        .chars()
        .map(|c| c as usize - 'a' as usize)
        .collect::<Vec<_>>();
    let n = s.len();
    let mut group = vec![0; n];
    let mut cur = 0;
    let mut set = 0;
    for i in (0..n).rev() {
        set |= 1 << s[i];
        group[i] = cur;
        if set == (1 << 26) - 1 {
            set = 0;
            cur += 1;
        }
    }

    let mut pos = vec![vec![]; 26];
    for i in 0..n {
        pos[s[i]].push(i);
    }

    let mut ans = vec![];
    let mut lower = 0;
    loop {
        for i in 0..26 {
            let next = pos[i]
                .binary_search_by_key(&(lower * 2), |&pos| pos * 2 + 1)
                .err()
                .unwrap();
            if next == pos[i].len() {
                // end
                ans.push(i);
                for ans in ans.into_iter() {
                    let c = (ans as u8 + 'a' as u8) as char;
                    sc.write(c);
                }
                sc.write("\n");
                return;
            } else if group[pos[i][next]] == cur - 1 {
                lower = pos[i][next] + 1;
                cur -= 1;
                ans.push(i);
                break;
            }
        }
    }
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> Self {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: ToString>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.to_string().as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

