        .chars()
        .map(|c| ((c as u8) - ('a' as u8)) as usize)
        .collect();
    let mut indices = vec![vec![]; LETTER_NUM];
    for i in 0..s.len() {
        indices[s[i]].push(i + 1);
    }

    let mut cur = Vec::new();
    for i in 1..5 {
        if dfs(&indices, &mut cur, i) {
            for &c in &cur {
                let c = (c as u8 + ('a' as u8)) as char;
                print!("{}", c);
            }
            println!();
