fn main() {
    let a = util::line();

    let mut positions: Vec<Vec<usize>> = vec![Vec::new(); 26];

    for (i, c) in a.chars()
        .map(|c| (c as u8 - 'a' as u8) as usize)
        .enumerate()
    {
        positions[c].push(i);
    }

    let a: Vec<usize> = (1..)
        .flat_map(move |l| {
            (0..26usize.pow(l.clone() as u32)).map(move |d| {
                let mut v = Vec::new();
                let mut d = d;
                while d > 0 {
                    v.push(d % 26);
                    d = d / 26;
                }
                while v.len() < l {
                    v.push(0)
                }
                v.into_iter().rev().collect::<Vec<_>>()
            })
        })
        .find(|v| {
            let mut last = 0;
            for &c in v.iter() {
                let pc = &positions[c];
                match pc.binary_search(&last) {
                    Ok(i) => last = pc[i] + 1,
                    Err(i) => {
                        if i >= positions[c].len() {
                            return true;
                        } else {
                            last = pc[i] + 1;
                        }
                    }
                }
            }
            false
        })
        .unwrap();

    println!(
        "{}",
        a.iter()
            .map(|&c| ('a' as u8 + c as u8) as char)
            .collect::<String>()
    );
}

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());
    let a = sc
        .read::<String>()
        .chars()
        .map(|c| c as usize - 'a' as usize)
        .collect::<Vec<_>>();
    let n = a.len();
    let mut seg = vec![0; n];
    let mut set: usize = 0;
    let mut cur = 0;
    for i in (0..n).rev() {
        set |= 1 << a[i];
        seg[i] = cur;
        if set.count_ones() == 26 {
            cur += 1;
            set = 0;
        }
    }

    let ans = calc(cur, seg, a);
    let s =
        ans.into_iter()
            .map(|i| (i as u8 + 'a' as u8) as char)
            .fold(String::new(), |mut s, c| {
                s.push(c);
                s
            });
    println!("{}", s);
}

fn calc(mut cur: usize, seg: Vec<usize>, a: Vec<usize>) -> Vec<usize> {
    let mut pos = vec![vec![]; 26];
    let n = a.len();
    for i in 0..n {
        pos[a[i]].push(i);
    }

    let mut ans = vec![];
    let mut cur_pos = 0;
    loop {
        for i in 0..26 {
            let idx = pos[i].binary_search(&cur_pos).unwrap_or_else(|x| x);
            match pos[i].get(idx) {
                Some(&idx) => {
                    if seg[idx] < cur {
                        ans.push(i);
                        cur_pos = idx + 1;
                        cur -= 1;
                        break;
                    }
                }
                None => {
                    ans.push(i);
                    return ans;
                }
            }
        }
    }
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> IO<R, W> {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: std::ops::Deref<Target = str>>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

