fn rec(depth: usize, q: &mut VecDeque<u8>, pos: &Vec<Vec<usize>>, n: usize) -> bool {
    if q.len() == depth {
        let mut cur: i32 = -1;
        for p in q.iter() {
            let i = *p as usize;
            //            println!("i={}, cur={}, q={:?}, pos[i]={:?}", i, cur, q, pos[i]);
            match pos[i].binary_search(&((cur + 1) as usize)) {
                Ok(t) => cur = pos[i][t] as i32,
                Err(t) => if t >= pos[i].len() {
                    cur = n as i32;
                } else {
                    cur = pos[i][t] as i32;
//                    println!("cur={}", cur);
                },
            };
            if cur >= n as i32 {
                return true;
            }
        }
        return false;
    }
    for i in 0..26 {
        q.push_back(i);
        if rec(depth, q, pos, n) {
            return true;
        }
        q.pop_back();
    }
    return false;
}


