    let INF = n+10;
    dp[n] = INF;
    for i in (0..n).rev() {
        let mut best = n+10;
        for nx in 0..26 {
            best = min(best, dp[next[i][nx]]+1);
        }
        dp[i] = best;
    }

    let mut left = dp[0];
    let mut ans = vec![];
    let mut now = 0;
    for i in 0..left {
