trait MyRead {
    fn read_one<T: FromStr>(&mut self) -> Option<T>;
    fn r<A: FromStr>(&mut self) -> A;
    fn r2<A: FromStr, B: FromStr>(&mut self) -> (A, B);
    fn r3<A: FromStr, B: FromStr, C: FromStr>(&mut self) -> (A, B, C);
    fn r4<A: FromStr, B: FromStr, C: FromStr, D: FromStr>(&mut self) -> (A, B, C, D);
    fn rn<A: FromStr>(&mut self, n: usize) -> Vec<A>;
}
impl<'a> MyRead for BufReader<StdinLock<'a>> {
    fn read_one<T: FromStr>(&mut self) -> Option<T> {
        let s = self.bytes()
            .map(|c| c.unwrap() as char)
            .skip_while(|c| c.is_whitespace())
            .take_while(|c| !c.is_whitespace())
            .collect::<String>();
        if s.is_empty() {
            None
        } else {
            s.parse::<T>().ok()
        }
    }
    fn r<A: FromStr>(&mut self) -> A {
        self.read_one().unwrap()
    }
    fn r2<A: FromStr, B: FromStr>(&mut self) -> (A, B) {
        (self.r(), self.r())
    }
    fn r3<A: FromStr, B: FromStr, C: FromStr>(&mut self) -> (A, B, C) {
        (self.r(), self.r(), self.r())
    }
    fn r4<A: FromStr, B: FromStr, C: FromStr, D: FromStr>(&mut self) -> (A, B, C, D) {
        (self.r(), self.r(), self.r(), self.r())
    }
    fn rn<A: FromStr>(&mut self, n: usize) -> Vec<A> {
        (0..n).map(|_| self.r()).collect()
    }
}

trait MyWrite {
    fn print<A: Display>(&mut self, a: &A);
    fn p<A: Display>(&mut self, a: &A);
    fn p2<A: Display, B: Display>(&mut self, a: &A, b: &B);
    fn p3<A: Display, B: Display, C: Display>(&mut self, a: &A, b: &B, c: &C);
    fn p4<A: Display, B: Display, C: Display, D: Display>(&mut self, a: &A, b: &B, c: &C, d: &D);
    fn pns<A: Display>(&mut self, v: &Vec<A>);
    fn pnl<A: Display>(&mut self, v: &Vec<A>);
}
impl<'a> MyWrite for BufWriter<StdoutLock<'a>> {
    fn print<A: Display>(&mut self, a: &A) {
        write!(self, "{}", a).ok();
    }
    fn p<A: Display>(&mut self, a: &A) {
        self.print(a);
        self.print(&'\n');
    }
    fn p2<A: Display, B: Display>(&mut self, a: &A, b: &B) {
        self.print(a);
        self.print(&' ');
        self.p(b);
    }
    fn p3<A: Display, B: Display, C: Display>(&mut self, a: &A, b: &B, c: &C) {
        self.print(a);
        self.print(&' ');
        self.p2(b, c);
    }
    fn p4<A: Display, B: Display, C: Display, D: Display>(&mut self, a: &A, b: &B, c: &C, d: &D) {
        self.print(a);
        self.print(&' ');
        self.p3(b, c, d);
    }
    fn pns<A: Display>(&mut self, v: &Vec<A>) {
        let n = v.len();
        for (i, x) in v.iter().enumerate() {
            if i + 1 == n {
                self.p(x);
            } else {
                self.print(x);
            }
        }
    }
    fn pnl<A: Display>(&mut self, v: &Vec<A>) {
        v.iter().map(|x| self.p(x)).count();
    }
}

