    let mut pos = (0..26).map(|_| {
        Vec::new()
    }).collect::<Vec<_>>();
    for i in 0..a.len() {
        let c = (a[i] - 'a' as u8) as usize;
        pos[c].push(i);
    }

    let mut q = VecDeque::new();
    for i in 0..5 {
        if rec(i, &mut q, &pos, a.len()) {
            for p in q.iter() {
                print!("{}", (*p + 'a' as u8) as char)
            }
            println!();
            return;
        }
    }
}

struct Scanner {
    stdin: Stdin,
    buf: Vec<u8>,
}

impl Scanner {
    fn new() -> Scanner {
        Scanner {
            stdin: io::stdin(),
            buf: Vec::with_capacity(256),
        }
    }

    fn parse<T: FromStr>(&mut self) -> T
        where <T as FromStr>::Err: Debug
    {
        self.buf.clear();
        let mut it = self.stdin.lock().bytes();
        let mut c = it.next().unwrap().unwrap();
        while c == ' ' as u8 || c == '\n' as u8 {
            c = it.next().unwrap().unwrap();
        }
        while !(c == ' ' as u8 || c == '\n' as u8) {
            self.buf.push(c);
            c = it.next().unwrap().unwrap();
        }
        str::from_utf8(&self.buf).unwrap().parse::<T>().unwrap()
    }
}

